import type { AutoUpdater } from "electron";
import type { AppUpdateView } from "../../shared/appUpdates.ts";
import { updateFeed } from "./platform.ts";

export const UPDATE_BASE_URL = "https://polaris.lux.dev";

export const CHECK_INTERVAL_MS = 6 * 60 * 60 * 1000;

type UpdateHeaders = {
  "X-Polaris-macOS-Version"?: string;
  "X-Polaris-Windows-Version"?: string;
  "X-Polaris-Install-ID"?: string;
};

export interface UpdateInput {
  readonly native: Pick<
    AutoUpdater,
    "on" | "removeListener" | "setFeedURL" | "checkForUpdates" | "quitAndInstall"
  >;
  readonly version: string;
  readonly installId: string;
  readonly osVersion: string;
  readonly platform?: string;
  readonly firstRun?: boolean;
  readonly fetch?: (url: string, init: RequestInit) => Promise<Response>;
  readonly arch: string;
  readonly supported: boolean;
  readonly blocked: boolean;
  readonly automatic: boolean;
  readonly lastCheckedAt: number | null;
  readonly save: (change: {
    automaticAppUpdates?: boolean;
    appUpdateLastCheckedAt?: number;
  }) => void;
  readonly publish: (view: AppUpdateView) => void;
  readonly now?: () => number;
  readonly schedule?: (run: () => void, delay: number) => () => void;
}

const scheduleCheck = (run: () => void, delay: number) => {
  const timer = setTimeout(run, delay);
  timer.unref();

  return () => clearTimeout(timer);
};

const CORE = String.raw`(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)`;

const PRERELEASE = String.raw`(?:alpha|beta|rc)`;

const assetVersion = new RegExp(
  String.raw`\/Polaris-(${CORE}(?:-${PRERELEASE}\.(?:0|[1-9]\d*))?)(?:-arm64-mac\.zip|-(?:x64|arm64)-win-Setup\.exe)$`
);

const nugetVersion = new RegExp(String.raw`^(${CORE})(?:-(${PRERELEASE})(0|[1-9]\d*))?$`);

/** A Squirrel NuGet version (`1.2.3-alpha1`) as the release's semver (`1.2.3-alpha.1`). */
export const versionFromNuget = (name: string): string | null => {
  const match = nugetVersion.exec(name);

  if (!match) return null;

  return match[2] === undefined ? match[1]! : `${match[1]}-${match[2]}.${match[3]}`;
};

/** The asset name is authoritative; a Release title can be arbitrary prose. */
export const versionFromAsset = (url: string): string | null => {
  const asset = assetVersion.exec(url)?.[1];

  if (asset !== undefined) return asset;
  const nupkg = /\/Polaris-(?:x64|arm64)-win-([^/]+)-full\.nupkg$/.exec(url)?.[1];

  return nupkg === undefined ? null : versionFromNuget(nupkg);
};

export const createAppUpdates = (input: UpdateInput) => {
  const platform = input.platform ?? "darwin";
  const now = input.now ?? Date.now;
  const schedule = input.schedule ?? scheduleCheck;
  let cancelTimer: (() => void) | null = null;
  let disposed = false;

  let view: AppUpdateView = {
    phase: input.supported && input.blocked ? "blocked" : "idle",
    version: input.version,
    availableVersion: null,
    automatic: input.automatic,
    lastCheckedAt: input.lastCheckedAt,
    installId: input.installId,
    osVersion: input.osVersion,
    platform,
    arch: input.arch,
    supported: input.supported,
  };

  const change = (patch: Partial<AppUpdateView>) => {
    if (disposed) return;
    view = { ...view, ...patch };
    input.publish(view);
  };

  const check = (): AppUpdateView => {
    if (disposed || !view.supported || input.blocked) return view;

    if (["checking", "downloading", "ready"].includes(view.phase)) return view;

    const headers: UpdateHeaders =
      platform === "win32"
        ? { "X-Polaris-Windows-Version": view.macOSVersion }
        : { "X-Polaris-macOS-Version": view.macOSVersion };

    if (view.automatic) headers["X-Polaris-Install-ID"] = view.installId;

    change({ phase: "checking", availableVersion: null });

    const url = updateFeed(UPDATE_BASE_URL, platform, input.arch, view.version);

    const nativeCheck = () => {
      if (disposed) return;
      input.native.setFeedURL({
        url,
        headers,
      });
      input.native.checkForUpdates();
    };

    try {
      if (platform === "win32") {
        // Squirrel ignores custom headers; the preflight carries the consent-controlled telemetry.
        void (input.fetch ?? fetch)(`${url}/RELEASES`, {
          headers,
          cache: "no-store",
          signal: AbortSignal.timeout(5_000),
        })
          .then((response) => {
            if (disposed) return;

            if (response.status === 204) finish("current");
            else if (response.ok) nativeCheck();
            else finish("failed");
          })
          .catch(() => finish("failed"));
      } else nativeCheck();
    } catch {
      finish("failed");
    }

    return view;
  };

  const arm = () => {
    cancelTimer?.();
    cancelTimer = null;

    if (disposed || !view.supported || input.blocked || !view.automatic || view.phase === "ready")
      return;
    cancelTimer = schedule(() => {
      cancelTimer = null;
      check();
      arm();
    }, CHECK_INTERVAL_MS);
  };

  const finish = (
    phase: "current" | "failed" | "ready",
    availableVersion: string | null = null
  ) => {
    if (disposed) return;
    const lastCheckedAt = now();
    input.save({ appUpdateLastCheckedAt: lastCheckedAt });
    change({ phase, availableVersion, lastCheckedAt });
    arm();
  };

  const checking = () => change({ phase: "checking" });
  const available = () => change({ phase: "downloading" });
  const current = () => finish("current");
  const failed = () => finish("failed");

  const downloaded = (
    _event: Electron.Event,
    _notes: string,
    name: string,
    _date: Date,
    url: string
  ) =>
    finish(
      "ready",
      (platform === "win32" ? versionFromNuget(name) : null) ?? versionFromAsset(url)
    );

  input.native.on("checking-for-update", checking);
  input.native.on("update-available", available);
  input.native.on("update-not-available", current);
  input.native.on("error", failed);
  input.native.on("update-downloaded", downloaded);

  return {
    get: () => view,
    check,
    start: () => {
      if (view.automatic && !input.firstRun) check();
      arm();
    },
    setAutomatic: (automatic: boolean) => {
      input.save({ automaticAppUpdates: automatic });
      change({ automatic });
      // A request already sent cannot be recalled; future manual checks omit the identity.
      arm();

      return view;
    },
    install: () => {
      if (view.phase === "ready") input.native.quitAndInstall();
    },
    dispose: () => {
      disposed = true;
      cancelTimer?.();
      input.native.removeListener("checking-for-update", checking);
      input.native.removeListener("update-available", available);
      input.native.removeListener("update-not-available", current);
      input.native.removeListener("error", failed);
      input.native.removeListener("update-downloaded", downloaded);
    },
  };
};

export type AppUpdates = ReturnType<typeof createAppUpdates>;

import { errorInfo, withWideEvent } from "../../../../lib/log";
import {
  latestRelease,
  releaseAssetNamed,
  releasesPage,
  windowsAssetName,
  type PublishedRelease,
  type WindowsArch,
} from "./releases.ts";
import { compareVersions, parseVersion } from "./version.ts";
import { requestFields } from "./telemetry.ts";

const headers = { "Cache-Control": "no-store" };

const unavailable = () =>
  Response.json(
    { error: "The latest release is unavailable. Try again shortly." },
    {
      status: 503,
      headers: { ...headers, "Retry-After": "60" },
    }
  );

/** Preserve Squirrel's hash and byte length; only a validated full-package URL reaches the Client. */
export const windowsReleases = (
  release: PublishedRelease,
  arch: WindowsArch,
  body: string
): string => {
  const name = windowsAssetName(release.version.text, arch, "nupkg");
  const line = /^([a-fA-F0-9]{40}) ([A-Za-z0-9._-]+) ([1-9]\d*)$/.exec(body.trim());

  if (line === null || line[2] !== name) throw new Error("Invalid Squirrel RELEASES");

  return `${line[1]} ${releaseAssetNamed(release, name)} ${line[3]}\n`;
};

export const windowsDownloadArch = (request: Request): WindowsArch | null => {
  const explicit = new URL(request.url).searchParams.get("arch");

  if (explicit !== null) return explicit === "x64" || explicit === "arm64" ? explicit : null;
  const hint = request.headers.get("sec-ch-ua-arch");

  if (hint === '"arm"' || hint === '"arm64"') return "arm64";

  return /\b(?:ARM64|aarch64)\b/i.test(request.headers.get("user-agent") ?? "") ? "arm64" : "x64";
};

interface Dependencies {
  readonly latest: () => Promise<PublishedRelease | null>;
  readonly fetch?: (url: string, init: RequestInit) => Promise<Response>;
  readonly log?: NonNullable<Parameters<typeof withWideEvent>[2]>;
}

export const createWindowsRoutes = (deps: Dependencies) => ({
  releases: (arch: WindowsArch) =>
    withWideEvent<{ params: Promise<{ version: string }> }>(
      `/api/update/win32-${arch}/[version]/RELEASES`,
      async (request, event, context) => {
        const { version } = await context.params;
        Object.assign(
          event,
          requestFields(request, "update_check", version, { platform: "win32", arch })
        );
        const caller = parseVersion(version);

        if (!caller)
          return Response.json(
            { error: "Use a valid semantic version." },
            { status: 400, headers }
          );

        try {
          const release = await deps.latest();
          event.release_version = release?.tag_name ?? null;

          if (!release || compareVersions(caller, release.version) >= 0) {
            event.update = "current";

            return new Response(null, { status: 204, headers });
          }

          const url = releaseAssetNamed(
            release,
            windowsAssetName(release.version.text, arch, "releases")
          );

          const response = await (deps.fetch ?? fetch)(url, {
            cache: "no-store",
            signal: AbortSignal.timeout(5_000),
          });

          if (!response.ok) throw new Error("Squirrel manifest unavailable");
          const body = windowsReleases(release, arch, await response.text());
          event.update = "available";

          return new Response(body, {
            headers: { ...headers, "Content-Type": "text/plain; charset=utf-8" },
          });
        } catch (error) {
          event.failure = "release_unavailable";
          event.error = errorInfo(error);

          return unavailable();
        }
      },
      deps.log
    ),
  download: withWideEvent<unknown>(
    "/download/windows",
    async (request, event) => {
      const arch = windowsDownloadArch(request);

      if (arch === null)
        return Response.json({ error: "Use arch=x64 or arch=arm64." }, { status: 400, headers });
      Object.assign(event, requestFields(request, "download", null, { platform: "win32", arch }));

      try {
        const release = await deps.latest();
        event.release_version = release?.tag_name ?? null;

        if (!release) return releasesPage();

        const url = releaseAssetNamed(
          release,
          windowsAssetName(release.version.text, arch, "setup")
        );

        return new Response(null, { status: 307, headers: { ...headers, Location: url } });
      } catch (error) {
        event.failure = "release_unavailable";
        event.error = errorInfo(error);

        return unavailable();
      }
    },
    deps.log
  ),
});

export const windowsRoutes = createWindowsRoutes({ latest: latestRelease });

/**
 * The tabs over Review's centre pane (Paper R9 AMW-0): each label with its figure, the
 * chosen one on `fill-selected`, and the jump to Changes trailing. ⌘⇧[ / ⌘⇧] cycle them.
 */
import { cn, Kbd, Tooltip, TooltipContent, TooltipTrigger } from "@polaris/ui";
import { type TabId, TAB_LABELS } from "../model/tabs.ts";
import { commandShortcut } from "../../../../../shared/keymap.ts";

export interface TabBarProps {
  readonly tabs: ReadonlyArray<TabId>;
  readonly current: TabId;
  readonly figures: Readonly<Partial<Record<TabId, string>>>;
  /** What a tab's tooltip says beyond its label ("9 files, 0 viewed"). */
  readonly hints: Readonly<Partial<Record<TabId, string>>>;
  /** A tab whose content changed since the last review ("updated", "3 new"). */
  readonly news: Readonly<Partial<Record<TabId, string>>>;
  readonly onPick: (tab: TabId) => void;
  /** "Review changes", "Review 2 new commits"; null hides the jump (on Changes). */
  readonly jumpLabel: string | null;
}

const next = () => commandShortcut("review.nextTab");

const previous = () => commandShortcut("review.previousTab");

const keyTo = (tabs: ReadonlyArray<TabId>, current: TabId, tab: TabId) => {
  const from = tabs.indexOf(current);
  const to = tabs.indexOf(tab);

  if ((from + 1) % tabs.length === to) return next();

  return (to + 1) % tabs.length === from ? PREVIOUS : null;
};

export const TabBar = ({ tabs, current, figures, hints, news, onPick, jumpLabel }: TabBarProps) => (
  <div
    role="tablist"
    aria-label="Review"
    data-testid="review-tabs"
    className="border-hairline px-panel flex h-10 shrink-0 items-center gap-1 border-b"
  >
    {tabs.map((tab) => {
      const key = keyTo(tabs, current, tab);
      const hint = [TAB_LABELS[tab], hints[tab]].filter((p) => p !== undefined).join(" · ");

      return (
        <Tooltip key={tab}>
          <TooltipTrigger asChild>
            <button
              type="button"
              role="tab"
              id={`review-tab-${tab}`}
              aria-selected={tab === current}
              aria-controls={`review-panel-${tab}`}
              data-testid={`review-tab-${tab}`}
              onClick={() => onPick(tab)}
              className={cn(
                "rounded-control h-tree-row px-row-x flex shrink-0 cursor-default items-center gap-1.5",
                tab === current ? "bg-fill-selected" : "hover:bg-fill-hover"
              )}
            >
              <span
                className={cn(
                  "text-body font-medium",
                  tab === current ? "text-text-strong" : "text-text-subtle"
                )}
              >
                {TAB_LABELS[tab]}
              </span>
              {figures[tab] !== undefined && (
                <span className="text-caption text-text-subtle tabular">{figures[tab]}</span>
              )}
              {news[tab] !== undefined && (
                <span className="text-caption text-text-default">{news[tab]}</span>
              )}
            </button>
          </TooltipTrigger>
          <TooltipContent side="bottom" className="flex items-center gap-2">
            {hint}
            {key !== null && <Kbd>{key}</Kbd>}
          </TooltipContent>
        </Tooltip>
      );
    })}
    <span className="flex-1" />
    {jumpLabel !== null && (
      <button
        type="button"
        data-testid="review-jump-changes"
        onClick={() => onPick("changes")}
        className="rounded-control h-tree-row pr-row-x bg-fill-selected text-body text-text-strong hover:bg-fill-selected/70 gap-gap flex shrink-0 cursor-default items-center pl-3 font-medium"
      >
        {jumpLabel} →{current === "overview" && <Kbd>{NEXT}</Kbd>}
      </button>
    )}
  </div>
);

/**
 * "Keep daemons up to date": the app-wide switch in the hosts table's sunken
 * foot, and each Host's override, in its row's menu and its opened settings.
 */
import {
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Switch,
} from "@polaris/ui";
import { useId } from "react";
import type { DaemonUpdateView } from "./contract.ts";
import { defaultChoiceLabel, type OverrideChoice, overrideChoice, overrideValue } from "./model.ts";

const CHOICES = (daemon: DaemonUpdateView) =>
  [
    { value: "default", label: defaultChoiceLabel(daemon) },
    { value: "on", label: "Always keep up to date" },
    { value: "off", label: "Only when I ask" },
  ] as const;

const isChoice = (value: string): value is OverrideChoice =>
  value === "default" || value === "on" || value === "off";

export interface OverrideProps {
  readonly daemon: DaemonUpdateView;
  readonly onChange: (enabled: boolean | null) => void;
}

/** The row menu's section: a radio group under its label. */
export const OverrideMenuItems = ({ daemon, onChange }: OverrideProps) => (
  <>
    <DropdownMenuSeparator />
    <DropdownMenuLabel>Daemon upgrades</DropdownMenuLabel>
    <DropdownMenuRadioGroup
      value={overrideChoice(daemon)}
      onValueChange={(value) => {
        if (isChoice(value)) onChange(overrideValue(value));
      }}
    >
      {CHOICES(daemon).map((choice) => (
        <DropdownMenuRadioItem key={choice.value} value={choice.value}>
          {choice.label}
        </DropdownMenuRadioItem>
      ))}
    </DropdownMenuRadioGroup>
  </>
);

/** The same choice as a select, in the opened row's settings. */
export const OverrideSelect = ({ daemon, onChange }: OverrideProps) => (
  <Select
    value={overrideChoice(daemon)}
    onValueChange={(value) => {
      if (isChoice(value)) onChange(overrideValue(value));
    }}
  >
    <SelectTrigger aria-label="Daemon updates" className="text-label h-7 w-[260px]">
      <SelectValue />
    </SelectTrigger>
    <SelectContent>
      {CHOICES(daemon).map((choice) => (
        <SelectItem key={choice.value} value={choice.value}>
          {choice.label}
        </SelectItem>
      ))}
    </SelectContent>
  </Select>
);

export interface KeepUpToDateProps {
  readonly checked: boolean;
  readonly onChange: (enabled: boolean) => void;
}

/** The table's foot (DESIGN.md, Settings: a sunken strip holds secondary defaults). */
export const KeepUpToDate = ({ checked, onChange }: KeepUpToDateProps) => {
  const id = useId();

  return (
    <div
      data-testid="keep-daemons-up-to-date"
      className="border-hairline bg-surface-sunken px-panel flex items-center gap-4 border-t py-[calc(var(--spacing-gap)+2px)]"
    >
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <label htmlFor={id} className="text-label text-text-default">
          Keep daemons up to date
        </label>
        <span className="text-caption text-text-subtle">
          Upgrades a host's daemon when it connects, with working agent sessions kept. Never
          installs on a host you haven't approved.
        </span>
      </div>
      <Switch id={id} checked={checked} onCheckedChange={onChange} />
    </div>
  );
};

/**
 * A resumable, cached, multicast view of one Daemon stream (`subscribeHost`
 * or `subscribeSession`).
 *
 * One upstream subscription serves every local subscriber. After a reconnect
 * it resubscribes with `afterSequence` = the last sequence seen and drops any
 * event at or below it, so a replay overlap never duplicates. A subscriber the
 * Daemon drops for falling behind has its stream ended (never skipped), so the
 * feed needs no gap check to stay gapless; `gapless` is only for a stream
 * whose sequences truly have no gaps. The host stream is not one: it leaves
 * out session-only events.
 *
 * Reopens that make no progress back off (`REOPEN_BACKOFF_MS`, doubling up to
 * `MAX_REOPEN_BACKOFF_MS`), so a stream that keeps asking to be reopened at the
 * same point can never loop hot against the Daemon.
 *
 * The feed keeps the last Snapshot and the events after it. A new subscriber
 * first gets that cache (the Desktop App paints from it at once), then live
 * items; if the feed was idle, the upstream restarts from the cached sequence
 * and revalidates. A Snapshot may arrive at any point (e.g. after the cache
 * overflowed and the feed asked for a fresh one), and replaces all prior state.
 */
import {
  HostStreamItem,
  type NotFound,
  Sequence,
  type SessionId,
  SessionStreamItem,
} from "@polaris/protocol";
import {
  Effect,
  Exit,
  Fiber,
  Predicate,
  PubSub,
  Result,
  type Scope,
  Semaphore,
  Stream,
} from "effect";
import type { RpcClientError } from "effect/rpc/RpcClientError";
import type { DaemonClient } from "./rpc.ts";

export type SequenceMark =
  | { readonly kind: "snapshot"; readonly sequence: number }
  | { readonly kind: "event"; readonly sequence: number }
  | { readonly kind: "synchronized"; readonly sequence: number }
  | { readonly kind: "ephemeral" };

/** Where a feed gets connections from: the HostConnection. */
export interface LiveSource<C> {
  /** Waits for a live connection whose epoch is at least `minEpoch`. */
  readonly next: (
    minEpoch: number
  ) => Effect.Effect<{ readonly epoch: number; readonly client: C }>;
}

export interface FeedOptions<C, A, E> {
  readonly source: LiveSource<C>;
  readonly open: (client: C, afterSequence: number | null) => Stream.Stream<A, E>;
  readonly mark: (item: A) => SequenceMark;
  /** Errors that mean "the connection went away": resubscribe after reconnecting. */
  readonly isDisconnect: (error: E) => boolean;
  /**
   * Sequences on this stream have no gaps, so a gap means something was missed
   * and the feed reopens. False for both Daemon streams: the host stream leaves
   * out session-only events, and a session stream is a subset of the log.
   */
  readonly gapless: boolean;
  /** Cached events after the Snapshot before the feed asks for a fresh Snapshot. */
  readonly maxCachedEvents?: number;
  /** Pause before reopening a stream the Daemon ended normally. */
  readonly reopenDelayMs?: number;
}

export interface Feed<A, E> {
  /** Cached items first, then live ones, across reconnects. Fails only with non-connection errors. */
  readonly stream: Stream.Stream<A, E>;
  readonly lastSequence: () => number | null;
  readonly subscribers: () => number;
}

/** What subscribers receive: an item, or the failure that ended the feed. */
type Message<A, E> = Exit.Exit<A, E>;

class Reopen {
  readonly _tag = "Reopen";
  constructor(readonly fresh: boolean) {}
}

/** The first pause before a reopen that made no progress, doubled each time up to the max. */
export const REOPEN_BACKOFF_MS = 25;

export const MAX_REOPEN_BACKOFF_MS = 5_000;

/** How long to wait before the `stalled`-th reopen in a row that made no progress. */
export const reopenBackoff = (stalled: number): number =>
  stalled <= 0 ? 0 : Math.min(MAX_REOPEN_BACKOFF_MS, REOPEN_BACKOFF_MS * 2 ** (stalled - 1));

export const openFeed = Effect.fnUntraced(function* <C, A, E>(
  options: FeedOptions<C, A, E>
): Effect.fn.Return<Feed<A, E>, never, Scope.Scope> {
  const scope = yield* Effect.scope;
  const pubsub = yield* PubSub.unbounded<Message<A, E>>();
  const lock = Semaphore.makeUnsafe(1);
  const maxCached = options.maxCachedEvents ?? 10_000;

  let lastSequence: number | null = null;
  let snapshot: A | null = null;
  let events: Array<A> = [];
  let synchronized: A | null = null;
  let failure: { readonly error: E } | null = null;
  let refCount = 0;
  let upstream: Fiber.Fiber<void> | null = null;

  const publish = (message: Message<A, E>) => PubSub.publish(pubsub, message);

  const handle = (item: A): Effect.Effect<void, Reopen> =>
    lock.withPermit(
      Effect.suspend(() => {
        const mark = options.mark(item);

        switch (mark.kind) {
          case "snapshot":
            lastSequence = mark.sequence;
            snapshot = item;
            events = [];
            synchronized = null;
            break;
          case "event": {
            if (lastSequence !== null && mark.sequence <= lastSequence) return Effect.void;

            if (options.gapless && lastSequence !== null && mark.sequence !== lastSequence + 1)
              return Effect.fail(new Reopen(false));
            lastSequence = mark.sequence;

            if (snapshot !== null) {
              events.push(item);

              if (events.length > maxCached) {
                snapshot = null;
                events = [];
                synchronized = null;

                return Effect.andThen(publish(Exit.succeed(item)), Effect.fail(new Reopen(true)));
              }
            }

            break;
          }

          case "synchronized":
            synchronized = item;
            break;
          case "ephemeral":
            break;
        }

        return Effect.asVoid(publish(Exit.succeed(item)));
      })
    );

  const run = Effect.gen(function* () {
    let minEpoch = 0;
    let fresh = false;
    /** Reopens in a row that saw no new event: each waits longer. */
    let stalled = 0;

    while (true) {
      const live = yield* options.source.next(minEpoch);
      const after: number | null = fresh ? null : lastSequence;
      const before = lastSequence;
      fresh = false;

      const result: Result.Result<void, E | Reopen> = yield* options
        .open(live.client, after)
        .pipe(Stream.runForEach(handle), Effect.result);

      if (Result.isSuccess(result)) {
        minEpoch = live.epoch;
        yield* Effect.sleep(options.reopenDelayMs ?? 1000);
        continue;
      }

      const error: E | Reopen = result.failure;

      if (error instanceof Reopen) {
        minEpoch = live.epoch;
        fresh = error.fresh;
        stalled = lastSequence !== before ? 0 : stalled + 1;

        if (stalled > 0) yield* Effect.sleep(reopenBackoff(stalled));
        continue;
      }

      if (options.isDisconnect(error)) {
        minEpoch = live.epoch + 1;
        continue;
      }

      yield* lock.withPermit(
        Effect.suspend(() => {
          failure = { error };

          return publish(Exit.fail(error));
        })
      );

      return;
    }
  });

  const retain = Effect.suspend(() => {
    refCount++;

    if (upstream === null) {
      if (failure !== null) {
        failure = null;
        lastSequence = null;
        snapshot = null;
        events = [];
        synchronized = null;
      }

      return Effect.map(Effect.forkIn(run, scope), (fiber) => {
        upstream = fiber;
        fiber.addObserver(() => {
          if (upstream === fiber) upstream = null;
        });
      });
    }

    return Effect.void;
  });

  const release = Effect.suspend(() => {
    refCount--;

    if (refCount === 0 && upstream !== null) {
      const fiber = upstream;
      upstream = null;

      return Fiber.interrupt(fiber);
    }

    return Effect.void;
  });

  const stream: Stream.Stream<A, E> = Stream.unwrap(
    Effect.gen(function* () {
      const { subscription, replay, failed } = yield* lock.withPermit(
        Effect.gen(function* () {
          const subscription = yield* PubSub.subscribe(pubsub);
          const replay: Array<A> = [];

          if (snapshot !== null) replay.push(snapshot, ...events);

          if (synchronized !== null) replay.push(synchronized);

          return { subscription, replay, failed: upstream === null ? null : failure };
        })
      );

      yield* Effect.acquireRelease(retain, () => release);

      const live = Stream.fromSubscription(subscription).pipe(
        Stream.mapEffect((message) => message)
      );

      if (failed !== null) return Stream.fail(failed.error);

      return Stream.concat(Stream.fromIterable(replay), live);
    })
  );

  return {
    stream,
    lastSequence: () => lastSequence,
    subscribers: () => refCount,
  };
});

const isDisconnect = Predicate.isTagged("RpcClientError");

const afterSequenceOf = (sequence: number | null) =>
  sequence === null ? null : Sequence.make(sequence);

const markHost = HostStreamItem.match<SequenceMark>({
  Snapshot: (item) => ({ kind: "snapshot", sequence: item.sequence }),
  Event: (item) => ({ kind: "event", sequence: item.envelope.sequence }),
  Synchronized: (item) => ({ kind: "synchronized", sequence: item.sequence }),
});

const markSession = SessionStreamItem.match<SequenceMark>({
  Snapshot: (item) => ({ kind: "snapshot", sequence: item.sequence }),
  Event: (item) => ({ kind: "event", sequence: item.envelope.sequence }),
  Synchronized: (item) => ({ kind: "synchronized", sequence: item.sequence }),
  Delta: () => ({ kind: "ephemeral" }),
  ItemProgress: () => ({ kind: "ephemeral" }),
});

/** A Daemon's host stream as a Feed. */
export const openHostFeed = (source: LiveSource<DaemonClient>) =>
  openFeed<DaemonClient, HostStreamItem, RpcClientError>({
    source,
    open: (client, afterSequence) =>
      client.subscribeHost({ afterSequence: afterSequenceOf(afterSequence) }),
    mark: markHost,
    isDisconnect,
    // The host stream leaves out session-only events (TurnItemCompleted, CheckpointRecorded),
    // so its sequences have gaps; the sequence dedupe keeps the feed exact (ENG-209 finding 1).
    gapless: false,
  });

/** A Daemon's stream of one Agent Session as a Feed. */
export const openSessionFeed = (
  source: LiveSource<DaemonClient>,
  sessionId: SessionId,
  turnLimit: number | null
) =>
  makeFeed<DaemonClient, SessionStreamItem, NotFound | RpcClientError>({
    source,
    open: (client, afterSequence) =>
      client.subscribeSession({
        sessionId,
        afterSequence: afterSequenceOf(afterSequence),
        turnLimit,
      }),
    mark: markSession,
    isDisconnect,
    gapless: false,
  });

import type { EmailTransport } from "./transport";
import type { BotCheck } from "./bot";
import { unavailableValidator, type EmailValidator } from "./validator";
import { readSubmission, validEmail } from "./validation";

type Dependencies = {
  checkBot: BotCheck;
  validator?: EmailValidator;
  transport: () => EmailTransport | null;
  rateLimit: (headers: Headers) => number;
  requested: () => void;
};

function reply(status: number, message: string, headers?: Readonly<Record<string, string>>) {
  return Response.json(
    { message },
    { status, headers: { "Cache-Control": "no-store", ...headers } }
  );
}

export function createEmailHandler({
  checkBot,
  validator = passThroughValidator,
  transport,
  rateLimit,
  requested,
}: Dependencies) {
  return async (request: Request): Promise<Response> => {
    try {
      const verification = await checkBot(request);

      if (verification.isBot || verification.isVerifiedBot)
        return reply(403, "This request was blocked. Please try again from your browser.");
    } catch {
      return reply(503, "Email is unavailable. Please try again later.");
    }

    const origin = request.headers.get("origin");
    const publicUrl = new URL(request.url);
    const host = request.headers.get("host");

    // Next can normalize the internal URL to localhost in development; Host is the browser's authority.
    if (host) publicUrl.host = host;

    if (origin && origin !== publicUrl.origin)
      return reply(403, "Send this form from the Polaris site.");

    if (request.headers.get("content-type")?.split(";")[0]?.trim() !== "application/json") {
      return reply(415, "Send the email form as JSON.");
    }

    let submission;

    try {
      submission = await readSubmission(request);
    } catch {
      return reply(400, "Enter a valid email address.");
    }

    if (submission.website !== "") return reply(200, "Check your inbox for the Mac download.");

    if (!validEmail(submission.email)) return reply(400, "Enter a valid email address.");

    const retryAfter = rateLimit(request.headers);

    if (retryAfter)
      return reply(429, "Too many requests. Try again in 15 minutes.", {
        "Retry-After": String(retryAfter),
      });
    requested();

    try {
      if (!(await validator.validate(submission.email)))
        return reply(422, "Use another email address.");
      const sender = transport();

      if (!sender) return reply(503, "Email is not available yet. Please try again later.");
      await sender.send(submission.email);

      return Response.json(
        {},
        {
          headers: {
            "Cache-Control": "no-store",
            "X-Polaris-Email-Preview": sender.preview ? "1" : "0",
          },
        }
      );
    } catch {
      return reply(503, "The email could not be sent. Please try again later.");
    }
  };
}

