            {p.comment.body}
          </span>
        </div>
      ))}
      <div className="px-gap gap-row-pad flex h-[26px] items-center">
        <span className="text-caption text-text-subtle w-[150px] shrink-0">Viewed</span>
        <span className="text-caption text-text-default">
          {viewed} of {detail.files.length} files{left > 0 ? ` · ${left} not viewed yet` : ""}
        </span>
      </div>
    </div>
  );
};

const Dialog = ({
  subjectKey,
  detail,
  onDone,
}: {
  readonly subjectKey: string;
  readonly detail: PullDetailView;
  readonly onDone: () => void;
}) => {
  const risk = useOpenRisk(subjectKey);
  const choices = submitChoices(detail, risk);
  const pending = pendingCount(detail);
  const [event, setEvent] = useState<ReviewEvent>("comment");
  const [body, setBody] = useState("");

  const [state, setState] = useState<{ busy: boolean; error: string | null }>({
    busy: false,
    error: null,
  });

  const problem = submitProblem(event, body, pending);
  const owner = detail.repo.split("/")[0] ?? detail.repo;

  const submit = async () => {
    if (problem !== null || state.busy) return;
    setState({ busy: true, error: null });
    const done = await submitReview(subjectKey, event, body);

    if (done.ok) onDone();
    else setState({ busy: false, error: done.message });
  };

  return (
    <div className="flex flex-col" data-testid="submit-review">
      <div className="flex flex-col gap-0.5 px-3.5 pt-3.5 pb-2">
        <span className="text-heading-sm text-text-strong font-medium">
          Submit review on #{detail.number}
        </span>
        <span className="text-caption text-text-subtle">{pendingCaption(pending)}</span>
      </div>
      <div className="px-3.5 pb-3">
        <Textarea
          autoFocus
          aria-label="Summary"
          placeholder={
            event === "request-changes" ? "Say what needs to change" : "Leave a summary (optional)"
          }
          className="min-h-[72px]"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) void submit();
          }}
        />
      </div>
      <div role="radiogroup" aria-label="Review" className="flex flex-col gap-0.5 px-1.5 pb-2">
        {choices.map((c) => (
          <Choice
            key={c.event}
            choice={c}
            chosen={c.event === event}
            onChoose={() => setEvent(c.event)}
          />
        ))}
      </div>
      <GoesOut detail={detail} />
      {state.error !== null && (
        <p className="text-caption text-failed-text px-3.5 pb-2">{state.error}</p>
      )}
      <div className="border-hairline bg-surface-sunken gap-gap flex items-center border-t px-3.5 py-2">
        <span className="text-caption text-text-subtle min-w-0 flex-1 truncate">
          As {detail.viewerLogin}, for {owner}
        </span>
        {pending > 0 && (
          <Button
            size="xs"
            variant="ghost"
            disabled={state.busy}
            onClick={() => void discardReview(subjectKey).then(onDone)}
          >
            Discard pending
          </Button>
        )}
        <Button
          size="xs"
          variant="primary"
          data-testid="submit-review-send"
          disabled={problem !== null || state.busy}
          title={problem ?? undefined}
          onClick={() => void submit()}
        >
          {SUBMIT_LABEL[event]} <span className="opacity-60">⌘↵</span>
        </Button>
      </div>
    </div>
  );
};

/** The pull request's primary action (DESIGN.md, Review: "Submit review" with the pending count). */
export const SubmitReviewAction = (props: ReviewSlotProps) => {
  const key = keyOf(props.subject);
  const detail = useComments((s) => s.pulls[key]?.detail ?? null);
  const [open, setOpen] = useState(false);
  const pending = pendingCount(detail);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="primary"
          disabled={detail === null || detail.state !== "open"}
          data-testid="submit-review-open"
        >
          Submit review
          {pending > 0 && (
            <span className="text-micro flex h-[18px] min-w-[18px] items-center justify-center rounded-[5px] bg-[color-mix(in_oklab,currentColor_12%,transparent)] px-[5px] font-medium">
              {pending}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-[400px] overflow-clip p-0">
        {detail !== null && (
          <Dialog subjectKey={key} detail={detail} onDone={() => setOpen(false)} />
        )}
      </PopoverContent>
    </Popover>
  );
};

/**
 * Onboarding's decisions (DESIGN.md, Onboarding): which stage the app opens
 * to, and the lines that say what was found. Pure, so it is unit-tested.
 */
import { harnessEntry, type HostHarnesses, type Workspace } from "@polaris/protocol";
import type { HostView, Plain } from "../../../shared/api.ts";
import type { HostModel } from "../../store/hostModel.ts";
import { olderThanTestedNote } from "../harness/model/options.ts";

/** "unknown" until the settings arrive, so the welcome never flashes for a returning user. */
export type Welcome = "unknown" | "show" | "seen";

/**
 * - `welcome`: O1, full-bleed, before anything else.
 * - `waiting`: no Host has said what it holds yet; the stage stays an empty scene.
 * - `setup`: O2, no Workspace on any Host.
 * - `shell`: the Orchestrator as usual.
 */
export type Stage = "welcome" | "waiting" | "setup" | "shell";

export interface StageInput {
  readonly welcome: Welcome;
  readonly hosts: ReadonlyArray<HostView>;
  readonly models: Readonly<Record<string, HostModel>>;
}

const shown = (model: HostModel | undefined) =>
  model === undefined ? [] : [...model.workspaces.values()].filter((w) => !w.hidden);

/** Whether a Host's Workspaces are known: synchronized, or painted from the cache. */
const known = (model: HostModel | undefined) =>
  model !== undefined && (model.synchronized || model.fromCache);

export const onboardingStage = ({ welcome, hosts, models }: StageInput): Stage => {
  if (welcome === "show") return "welcome";

  if (hosts.some((h) => shown(models[h.key]).length > 0)) return "shell";

  return hosts.some((h) => known(models[h.key])) ? "setup" : "waiting";
};

/** Whether the Orchestrator's stage is the setup (no Workspace on any Host). */
export const noWorkspaceAnywhere = (input: Omit<StageInput, "welcome">) =>
  onboardingStage({ ...input, welcome: "seen" }) !== "shell";

export type Availability = Plain<HostHarnesses>;

const harnessName = (kind: string) => harnessEntry(kind)?.name ?? kind;

type Reported = Availability["harnesses"][number];

const named = (harnesses: ReadonlyArray<Reported>) =>
  harnesses.map((h) => {
    const name =
      h.version === null ? harnessName(h.harness) : `${harnessName(h.harness)} ${h.version}`;

    const note = olderThanTestedNote(h.olderThanTested);

    // A comma, not "·": the footer already separates its parts with dots.
    return note === null ? name : `${name}, ${note}`;
  });

/**
 * Installed Harnesses with their versions: "Claude Code 2.1.4", in catalogue order; one older
 * than tested says so, quietly: "Claude Code 2.1.272, older than tested (2.1.283)".
 */
export const installedHarnesses = (availability: Availability | null): ReadonlyArray<string> =>
  named((availability?.harnesses ?? []).filter((h) => h.status !== "not-installed"));

/** The installed Harnesses' names alone: "Claude Code". */
export const installedNames = (availability: Availability | null): ReadonlyArray<string> =>
  (availability?.harnesses ?? [])
    .filter((h) => h.status !== "not-installed")
    .map((h) => harnessName(h.harness));

export const hostsLine = (count: number) =>
  count === 1 ? "1 host in ~/.ssh/config" : `${count} hosts in ~/.ssh/config`;

/** O1's footer: "Claude Code 2.1.4 · Codex 0.52.0 · 14 hosts in ~/.ssh/config". */
export const foundLine = (availability: Availability | null, sshHosts: number | null): string => {
  const parts = [...installedHarnesses(availability)];

  if (sshHosts !== null && sshHosts > 0) parts.push(hostsLine(sshHosts));

  return parts.length === 0 ? "No agents yet" : parts.join(" · ");
};

/** "A and B", "A, B, and C"; past `max` names, "A, B, and 3 more" (the serial comma). */
export const listed = (names: ReadonlyArray<string>, max = names.length): string => {
  const shown = names.length > max ? [...names.slice(0, max), `${names.length - max} more`] : names;

  return shown.length <= 2
    ? shown.join(" and ")
    : `${shown.slice(0, -1).join(", ")}, and ${shown[shown.length - 1]}`;
};

/** O1's line on what Polaris drives: the Harnesses found here, or the catalogue's first two. */
export const drivesLine = (installed: ReadonlyArray<string>, catalogue: ReadonlyArray<string>) => {
  const names = installed.length > 0 ? installed : catalogue;

  return names.length > 2 ? `${names.slice(0, 2).join(", ")} and more` : listed(names);
};

/** The Workspace already registered at a path, shown or hidden. */
export const workspaceAt = (model: HostModel | undefined, path: string): Workspace | undefined =>
  model === undefined ? undefined : [...model.workspaces.values()].find((w) => w.path === path);

import { useEffect } from "react";
import { useCommands } from "../../../shell/hooks.ts";
