const mac = typeof navigator !== "undefined" && /Mac/.test(navigator.userAgent);

export interface CodeHostProps {
  /** The active file's key; null for none. */
  readonly bufferKey: string | null;
  /** Re-runs the attach once the file has loaded. */
  readonly ready: boolean;
  /** Take focus when the file shows (a tab click, an open from elsewhere). */
  readonly focus: boolean;
}

export const CodeHost = ({ bufferKey, ready, focus }: CodeHostProps) => {
  const host = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const parent = host.current;

    return parent === null ? undefined : forwardShellChords(parent);
  }, []);

  useEffect(() => {
    const parent = host.current;

    if (parent === null || bufferKey === null || !ready) return undefined;

    if (attachView(bufferKey, parent) && focus) {
      parent.querySelector<HTMLElement>(".cm-content")?.focus({ preventScroll: true });
    }

    return () => detachView(bufferKey);
  }, [bufferKey, ready, focus]);

  return (
    <div
      ref={host}
      data-testid="editor-code"
      className="min-h-0 flex-1 overflow-hidden [&>.cm-editor]:h-full"
    />
  );
};

/**
 * One file's CodeMirror state: the shared look and keys, its own line
 * endings and indentation, and compartments for what arrives later (its
 * grammar, vim mode, other features' extensions).
 */
import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
import { bracketMatching, indentOnInput, indentUnit } from "@codemirror/language";
import { highlightSelectionMatches, search, searchKeymap } from "@codemirror/search";
import { Compartment, EditorState, type Extension } from "@codemirror/state";
import {
  drawSelection,
  dropCursor,
  EditorView,
  highlightActiveLine,
  highlightActiveLineGutter,
  keymap,
  lineNumbers,
} from "@codemirror/view";
import {
  type EditorFile,
  editorFile,
  registeredCompartment,
  registeredExtensions,
} from "../cm/extensions.ts";
import { shellSafe } from "../cm/keys.ts";
import { reloadHighlight } from "../cm/reload.ts";
import { agentMarks } from "../cm/agent.ts";
import { currentKeyPlatform } from "../../../../shared/chord.ts";
import { editorLook } from "../cm/theme.ts";
import { inlineDiagnostics } from "../cm/inlineDiagnostics.ts";
import { detectIndent, type Indent, lineSeparatorOf } from "../model/indent.ts";

export const languageCompartment = new Compartment();

export const vimCompartment = new Compartment();

export const readOnlyCompartment = new Compartment();

/** Which file the state holds; a rename reconfigures it. */
export const fileCompartment = new Compartment();

/** The file's own line endings; a reload that changes them reconfigures it, so saves keep the disk's. */
export const lineEndingCompartment = new Compartment();

export const lineEnding = (separator: "\r\n" | "\n"): Extension =>
  separator === "\r\n" ? EditorState.lineSeparator.of("\r\n") : [];

const mac = typeof navigator !== "undefined" && /Mac/.test(navigator.userAgent);

/** Built once: the keys with every shell chord taken out. */
let keys: Extension | null = null;

const editorKeys = () => {
  keys ??= keymap.of([
    ...shellSafe(
      [...defaultKeymap, ...historyKeymap, ...searchKeymap, indentWithTab],
      currentKeyPlatform()
    ),
  ]);

  return keys;
};

/** CodeMirror's own words in sentence case (rule/sentence-case). */
const PHRASES = EditorState.phrases.of({
  Find: "Find",
  Replace: "Replace",
  next: "Next",
  previous: "Previous",
  all: "All",
  "match case": "Match case",
  regexp: "Regex",
  "by word": "Whole word",
  replace: "Replace",
  "replace all": "Replace all",
  close: "Close",
  "current match": "Current match",
  "on line": "on line",
  "Go to line": "Go to line",
  go: "Go",
});

export interface StateInput {
  readonly file: EditorFile;
  readonly text: string;
  readonly readOnly: boolean;
  /** Vim's extension when the setting is on and it has loaded. */
  readonly vim: Extension;
  /** Called with every update while the state is in a view. */
  readonly onUpdate: Extension;
}

export interface FileState {
  readonly state: EditorState;
  readonly indent: Indent;
}

export const createFileState = ({ file, text, readOnly, vim, onUpdate }: StateInput): FileState => {
  const indent = detectIndent(text);
  const separator = lineSeparatorOf(text);

  const state = EditorState.create({
    doc: text,
    extensions: [
      // Vim first, so its keys win over the editor's (codemirror-vim's README).
      vimCompartment.of(vim),
      fileCompartment.of(editorFile.of(file)),
      lineEndingCompartment.of(lineEnding(separator)),
      EditorState.tabSize.of(indent.width),
      indentUnit.of(indent.tabs ? "\t" : " ".repeat(indent.width)),
      // The agent's bar first: it overlays the git bar's place on the lines it wrote.
      agentMarks,
      // Before the line numbers, so a registered gutter (the git bars) sits left of them.
      registeredCompartment.of(registeredExtensions(file)),
      lineNumbers(),
      highlightActiveLineGutter(),
      inlineDiagnostics,
      highlightActiveLine(),
      history(),
      drawSelection(),
      dropCursor(),
      indentOnInput(),
      bracketMatching(),
      highlightSelectionMatches(),
      search({ top: true }),
      editorKeys(),
      editorLook,
      PHRASES,
      reloadHighlight,
      languageCompartment.of([]),
      readOnlyCompartment.of(readOnly ? EditorState.readOnly.of(true) : []),
      EditorView.contentAttributes.of({ "aria-label": `Editing ${file.path}` }),
      onUpdate,
    ],
  });

  return { state, indent };
};

/** Advanced (Paper L4): collapsed; custom servers, executable overrides and Markdown images, per Host. */
import * as P from "@polaris/protocol";
import { DisclosureChevron } from "@polaris/ui";
import { useMemo, useState } from "react";
import type { LanguageApi } from "../../../../shared/api.ts";
import { CustomServers } from "./CustomServers.tsx";
import { useRecord, type Committed } from "./hooks.ts";
import { MarkdownImages, type PolicyWorkspace } from "./MarkdownImages.tsx";
import { Overrides } from "./Overrides.tsx";
import { withKey } from "./records.ts";

export interface AdvancedHost {
  readonly key: string;
  readonly id: P.HostId;
  readonly label: string;
}

const Heading = ({ children }: { readonly children: string }) => (
  <h3 className="text-caption text-text-subtle px-0.5 font-medium">{children}</h3>
);

const Sections = ({
  api,
  host,
  providers,
  workspaces,
  committed,
  onPolicySaved,
}: {
  readonly api: LanguageApi;
  readonly host: AdvancedHost;
  readonly providers: ReadonlyArray<string>;
  readonly workspaces: ReadonlyArray<PolicyWorkspace>;
  readonly committed: Committed;
  readonly onPolicySaved: (workspaceId: P.WorkspaceId) => void;
}) => {
  const scope = useMemo(
    () => P.LanguageSettingsScope.cases.Host.make({ hostId: host.id }),
    [host.id]
  );

  const { record, failed, update } = useRecord(api, host.key, scope, committed);
  const disabled = record === null;

  return (
    <div className="flex flex-col gap-4">
      {failed && (
        <p role="status" className="text-caption text-text-subtle">
          Couldn't read or save {host.label}'s language settings. Try again.
        </p>
      )}
      <Heading>{`Custom language servers on ${host.label}`}</Heading>
      <CustomServers
        servers={record?.settings.customServers ?? []}
        disabled={disabled}
        onChange={(servers) =>
          void update(withKey("customServers", servers.length > 0 ? servers : undefined))
        }
      />
      <Heading>{`Executable overrides on ${host.label}`}</Heading>
      <Overrides
        overrides={record?.settings.executableOverrides ?? {}}
        providers={providers}
        disabled={disabled}
        onChange={(overrides) =>
          void update(
            withKey(
              "executableOverrides",
              Object.keys(overrides).length > 0 ? overrides : undefined
            )
          )
        }
      />
      <Heading>Markdown previews</Heading>
      <MarkdownImages
        api={api}
        hostKey={host.key}
        hostId={host.id}
        workspaces={workspaces}
        onSaved={onPolicySaved}
      />
    </div>
  );
};

export const Advanced = (props: {
  readonly api: LanguageApi | undefined;
  readonly host: AdvancedHost | null;
  readonly providers: ReadonlyArray<string>;
  readonly workspaces: ReadonlyArray<PolicyWorkspace>;
  readonly committed: Committed;
  readonly onPolicySaved: (workspaceId: P.WorkspaceId) => void;
}) => {
  const [open, setOpen] = useState(false);
  const Chevron = open ? ChevronDownIcon : ChevronRightIcon;
  const { api, host } = props;

  return (
    <section aria-label="Advanced" className="flex flex-col gap-4">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen(!open)}
        className="flex cursor-default items-center gap-2 self-start px-0.5 py-1 text-left"
      >
        <DisclosureChevron open={open} size={12} className="text-text-subtle" />
        <span className="text-body text-text-default font-medium">Advanced</span>
        <span className="text-caption text-text-faint">
          Custom language servers and executable overrides, per host
        </span>
      </button>
      {open &&
        (api && host ? (
          <Sections {...props} api={api} host={host} />
