import { randomUUID } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir, hostname } from "node:os";
import { join } from "node:path";
import { HostId, HostInfo, Platform } from "@polaris/protocol";
import { Effect, Schema } from "effect";
import { ServiceError } from "../services.ts";

/** The Daemon's version; `polaris version` and `hello` report it. */
export const DAEMON_VERSION = VERSION;

const platformOf = (os: string, arch: string) =>
  Schema.decodeUnknownEffect(Platform)(`${os}-${arch}`).pipe(
    Effect.mapError(
      () =>
        new ServiceError({
          service: "transport",
          message: `unsupported platform ${os}-${arch}`,
        })
    )
  );

/**
 * A stable id for this Host, created on first run under the Polaris home and
 * kept across Daemon upgrades, so Clients can tell Hosts apart even when two
 * SSH aliases point at the same machine.
 */
const loadHostId = (root: string) =>
  Effect.try({
    try: () => {
      const file = join(root, "host-id");

      try {
        const existing = readFileSync(file, "utf8").trim();

        if (existing.length > 0) return existing;
      } catch {}

      mkdirSync(root, { recursive: true, mode: 0o700 });
      const id = randomUUID();
      writeFileSync(file, `${id}\n`, { mode: 0o600, flag: "w" });

      return id;
    },
    catch: (cause) =>
      new ServiceError({ service: "transport", message: "cannot read host id", cause }),
  });

export const loadHostInfo = Effect.fnUntraced(function* (root: string) {
  const hostId = yield* loadHostId(root);
  const platform = yield* platformOf(process.platform, process.arch);

  return new HostInfo({
    hostId: HostId.make(hostId),
    hostname: hostname(),
    platform,
    daemonVersion: DAEMON_VERSION,
    homeDir: homedir(),
    startedAt: new Date().toISOString(),
  });
});

import { randomUUID } from "node:crypto";
import { lstat, mkdir, open, rename, stat, unlink } from "node:fs/promises";
import { homedir } from "node:os";
import { basename, join } from "node:path";
import { FsFailure } from "./fs.ts";

export const supportsTrash = process.platform === "darwin" || process.platform === "linux";

const MAC_TRASH = `ObjC.import('Foundation');
function run(argv) {
  const url = $.NSURL.fileURLWithPath(argv[0]);
  const result = Ref(), error = Ref();
  if (!$.NSFileManager.defaultManager.trashItemAtURLResultingItemURLError(url, result, error)) {
    throw Error(ObjC.unwrap(error[0].localizedDescription));
  }
}`;

const macTrash = async (path: string): Promise<void> => {
  const child = Bun.spawn(["/usr/bin/osascript", "-l", "JavaScript", "-e", MAC_TRASH, path], {
    env: childEnv(),
    stdin: "ignore",
    stdout: "ignore",
    stderr: "pipe",
  });

  const message = await new Response(child.stderr).text();

  if ((await child.exited) !== 0)
    throw new FsFailure(path, "ETRASH", message.trim() || "could not move to Trash");
};

const localDeletionDate = () => {
  const now = new Date();

  return new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 19);
};

/** Freedesktop home trash; a different filesystem requires explicit permanent-delete confirmation. */
export const linuxTrash = async (path: string, dataHome: string): Promise<void> => {
  const trash = join(dataHome, "Trash");
  const files = join(trash, "files");
  const info = join(trash, "info");
  await mkdir(files, { recursive: true, mode: 0o700 });
  await mkdir(info, { recursive: true, mode: 0o700 });
  const source = await lstat(path);

  if (source.dev !== (await stat(files)).dev)
    throw new FsFailure(
      path,
      "ENOTSUP",
      "Trash is on a different filesystem; confirm permanent deletion"
    );
  const name = `${basename(path)}-${randomUUID()}`;
  const metadata = join(info, `${name}.trashinfo`);
  const handle = await open(metadata, "wx", 0o600);

  try {
    await handle.writeFile(
      `[Trash Info]\nPath=${encodeURI(path).replaceAll("#", "%23").replaceAll("?", "%3F")}\nDeletionDate=${localDeletionDate()}\n`
    );
    await handle.sync();
  } finally {
    await handle.close();
  }

  try {
    await rename(path, join(files, name));
  } catch (cause) {
    await unlink(metadata);
    throw cause;
  }
};

export const trashPath = async (path: string): Promise<void> => {
  if (process.platform === "darwin") return macTrash(path);

  if (process.platform === "linux")
    return linuxTrash(path, process.env.XDG_DATA_HOME || join(homedir(), ".local", "share"));
  throw new FsFailure(path, "ENOTSUP", "Trash is unavailable; confirm permanent deletion");
};

/**
 * The Harness drivers this Daemon runs. The Codex driver owns the Host's shared
 * `codex app-server`, and the OpenCode driver its `opencode serve`; neither
 * outlives this layer's scope.
 *
 * Each driver's module is loaded on first use (`probe`, `open`), not at start:
 * the Claude Agent SDK and the Codex protocol schemas would otherwise sit in
 * every idle Daemon's memory. `kind` and `capabilities` are known up front
 * (the engine reads them without opening anything), and Claude's terminal
 * follow-along comes from the hook receiver, which does not need the SDK.
 *
 * Under launchd / systemd a user's PATH often lacks nvm or Homebrew bins, so
 * `POLARIS_CODEX`, `POLARIS_CLAUDE`, `POLARIS_OPENCODE`, `POLARIS_GEMINI` and
 * `POLARIS_COPILOT` can point at the binaries explicitly.
 * Requires `PlanLimitReporter`, where the drivers report what their Harness exposes.
 */
import type { HarnessKind, KnownHarnessKind } from "@polaris/protocol";
import { Effect, Layer, Scope } from "effect";
import { HarnessRegistry, ServiceError } from "../services.ts";
import { ACP_HARNESSES } from "./acp/harnesses.ts";
import { isBenchKind } from "./bench/kinds.ts";
import { ClaudeHookReceiver } from "./claude/hooks.ts";
import { type HarnessDriver, HarnessError } from "./HarnessDriver.ts";
import { PlanLimitReporter } from "./limits/PlanLimitReporter.ts";

const binary = (env: string, name: string): string | null =>
  process.env[env] || which(name) || null;

/** What each driver declares; checked against the loaded drivers in registry.test.ts. */
export const DRIVER_CAPABILITIES = {
  codex: { steer: true, liveCoAttach: true, switchModel: true },
  claude: { steer: true, liveCoAttach: false, switchModel: true },
  opencode: { steer: true, liveCoAttach: true, switchModel: true },
  gemini: { steer: false, liveCoAttach: false, switchModel: true },
  copilot: { steer: false, liveCoAttach: false, switchModel: true },
  bench: { steer: true, liveCoAttach: true, switchModel: true },
} as const satisfies Record<KnownHarnessKind | "bench", HarnessDriver["capabilities"]>;

/**
 * A driver that loads the real one the first time it is probed or opened.
 * `extra` carries members that must not wait for the load (Claude's follow-along).
 */
export const lazyDriver = (
  kind: HarnessKind,
  capabilities: HarnessDriver["capabilities"],
  load: Effect.Effect<HarnessDriver>,
  extra: Pick<HarnessDriver, "terminalFollow"> = {}
): Effect.Effect<HarnessDriver> =>
  Effect.map(Effect.cached(load), (loaded) => ({
    kind,
    capabilities,
    ...extra,
    probe: Effect.flatMap(loaded, (driver) => driver.probe),
    listModels: Effect.flatMap(
      loaded,
      (driver) =>
        driver.listModels ??
        Effect.fail(new HarnessError({ harness: kind, message: "it doesn't list its Models yet" }))
    ),
    listCommands: (cwd) =>
      Effect.flatMap(loaded, (driver) => driver.listCommands?.(cwd) ?? Effect.succeed([])),
    open: (options) => Effect.flatMap(loaded, (driver) => driver.open(options)),
  }));

export interface RegistryOptions {
  /**
   * Benchmarks and the dev Desktop App: the scripted bench Harness stands in for
   * Claude Code and Codex (`bench/kinds.ts`); the others stay real. Defaults to
   * `POLARIS_BENCH_HARNESS=1`.
   */
  readonly bench?: boolean;
}

export const harnessRegistryLayer = (options: RegistryOptions = {}) =>
  Layer.effect(
    HarnessRegistry,
    Effect.gen(function* () {
      const hookReceiver = yield* ClaudeHookReceiver;
      const { report } = yield* PlanLimitReporter;
      const planLimits = { report };
      // The app-server the Codex driver may start belongs to this layer, not to the first `open`.
      const scope = yield* Effect.scope;
      const codexPath = binary("POLARIS_CODEX", "codex");
      const bench = options.bench ?? process.env.POLARIS_BENCH_HARNESS === "1";

      const benchDriver = (kind: HarnessKind) =>
        lazyDriver(
          kind,
          DRIVER_CAPABILITIES.bench,
          Effect.promise(() => import("./bench/BenchDriver.ts")).pipe(
            Effect.map(({ makeBenchDriver }) => makeBenchDriver(kind))
          )
        );

      // Every driver is lazy, so building the real ones the bench replaces costs nothing.
      const real: ReadonlyArray<HarnessDriver> = [
        yield* lazyDriver(
          "codex",
          DRIVER_CAPABILITIES.codex,
          Effect.promise(() => import("./codex/CodexDriver.ts")).pipe(
            Effect.flatMap(({ makeCodexDriver }) => makeCodexDriver({ codexPath, planLimits })),
            Scope.provide(scope)
          )
        ),
        yield* lazyDriver(
          "claude",
          DRIVER_CAPABILITIES.claude,
          Effect.promise(() => import("./claude/ClaudeDriver.ts")).pipe(
            Effect.map(({ makeClaudeDriver }) =>
              // Looked up per session, so a Claude Code installed after start is found.
              makeClaudeDriver({
                hookReceiver,
                claudePath: () => binary("POLARIS_CLAUDE", "claude"),
                planLimits,
              })
            )
          ),
          // While In Terminal, Polaris follows the TUI through its HTTP hooks (hooks.ts).
          { terminalFollow: { events: hookReceiver.events, release: hookReceiver.release } }
        ),
        yield* lazyDriver(
          "opencode",
          DRIVER_CAPABILITIES.opencode,
          Effect.promise(() => import("./opencode/OpenCodeDriver.ts")).pipe(
            Effect.flatMap(({ makeOpenCodeDriver }) =>
              makeOpenCodeDriver({ opencodePath: () => binary("POLARIS_OPENCODE", "opencode") })
            ),
            Scope.provide(scope)
          )
        ),
        ...(yield* Effect.forEach(ACP_HARNESSES, (harness) =>
          lazyDriver(
            harness.kind,
            DRIVER_CAPABILITIES[harness.kind],
            Effect.promise(() => import("./acp/AcpDriver.ts")).pipe(
              Effect.flatMap(({ makeAcpDriver }) =>
                makeAcpDriver({
                  harness,
                  binaryPath: () => binary(harness.binaryEnv, harness.binary),
                })
              ),
              Scope.provide(scope)
            )
          )
        )),
      ];

      const drivers = bench
        ? yield* Effect.forEach(real, (driver) =>
            isBenchKind(driver.kind) ? benchDriver(driver.kind) : Effect.succeed(driver)
          )
        : real;

      const byKind = new Map<HarnessKind, HarnessDriver>(drivers.map((d) => [d.kind, d]));

      return HarnessRegistry.of({
        get: (kind) => {
          const driver = byKind.get(kind);

          return driver
            ? Effect.succeed(driver)
            : Effect.fail(new ServiceError({ service: "harness", message: `no ${kind} driver` }));
        },
        all: Effect.succeed(drivers),
      });
    })
  ).pipe(Layer.provide(ClaudeHookReceiver.layer));

export const HarnessRegistryLive = harnessRegistryLayer();

/**
 * Sending commands from the session view. A refusal comes back with the
 * Daemon's reason ("interrupt the Turn in flight before archiving"), which is
 * what the user reads; it's shown as a Polaris toast unless the caller shows it.
 */
import type { Command } from "@polaris/protocol";
import { PixelFailedIcon, showToast } from "@polaris/ui";
import { createElement } from "react";
import type { IpcError } from "../../../shared/api.ts";
import { newCommandId } from "../../commands.ts";

export type Sent = { readonly ok: true } | { readonly ok: false; readonly error: IpcError };

export const dispatch = async (hostKey: string, command: Command): Promise<Sent> => {
  const result = await polaris().request("dispatch", {
    hostKey,
    commandId: newCommandId(),
    command,
  });

  return result.ok ? { ok: true } : { ok: false, error: result.error };
};

/** The Daemon's reason, first letter up: "Interrupt the Turn in flight before archiving". */
export const refusalText = (error: IpcError): string => {
  const text = error.message.replace(/^CommandRejected:\s*/, "").trim();

  return text === "" ? error.code : text.charAt(0).toUpperCase() + text.slice(1);
};

export const showRefusal = (title: string, error: IpcError) =>
  showToast({
    source: "starlight",
    icon: createElement(PixelFailedIcon, { size: 16 }),
    title,
    message: refusalText(error),
  });

/** Dispatch, and toast the refusal under `title` ("Couldn't archive"). */
export const send = async (hostKey: string, command: Command, title: string) => {
  const sent = await dispatch(hostKey, command);

  if (!sent.ok) showRefusal(title, sent.error);

  return sent.ok;
};

/**
 * Context for a Fork's first Turn.
 *
 * A Fork never reuses its parent's Harness cursor: the Fork may run a different
 * Harness, and even with the same one, resuming the parent's native session
 * would carry every Turn after the fork point too. The Fork's Harness starts a
 * fresh native session instead, and its first Turn is prefixed with a short
 * account of the parent's conversation up to the fork point: each Turn's prompt
 * and the Harness's last reply, newest kept when the budget runs out. The Turn
 * the user sees keeps their own prompt; only the Harness gets the preamble.
 */
import type { TurnItem } from "@polaris/protocol";

/** Characters of earlier conversation to include, at most. */
export const FORK_CONTEXT_BUDGET = 24_000;

/** Characters of one prompt or reply, at most. */
const PART_LIMIT = 2_000;

export interface ForkedTurn {
  readonly prompt: string;
  /** The Harness's final reply, when it gave one. */
  readonly reply: string | null;
}

const clip = (text: string, limit = PART_LIMIT): string => {
  const trimmed = text.trim();

  return trimmed.length > limit ? `${trimmed.slice(0, limit - 1)}…` : trimmed;
};

/** The last assistant message of a Turn: what the Harness answered in the end. */
export const finalReply = (items: ReadonlyArray<TurnItem> | undefined): string | null => {
  if (items === undefined) return null;

  for (let i = items.length - 1; i >= 0; i--) {
    const item = items[i]!;

    if (Predicate.isTagged(item, "AssistantMessage") && item.text.trim() !== "") return item.text;
  }

  return null;
};

export const forkPreamble = (options: {
  readonly parentTitle: string;
  /** The Turns up to and including the one forked from, oldest first. */
  readonly turns: ReadonlyArray<ForkedTurn>;
  /** The Fork works in its own Worktree created at the forked Turn's checkpoint. */
  readonly ownWorktree: boolean;
  readonly prompt: string;
}): string => {
  const blocks: Array<string> = [];
  let used = 0;
  let omitted = 0;

  for (let i = options.turns.length - 1; i >= 0; i--) {
    const turn = options.turns[i]!;

    const block = [
      `Turn ${i + 1}`,
      `User: ${clip(turn.prompt) || "(no prompt recorded)"}`,
      `Assistant: ${turn.reply === null ? "(no reply recorded)" : clip(turn.reply)}`,
    ].join("\n");

    if (used + block.length > FORK_CONTEXT_BUDGET && blocks.length > 0) {
      omitted = i + 1;
      break;
    }

    blocks.unshift(block);
    used += block.length;
  }

  const where = options.ownWorktree
    ? "The working directory is a new git worktree holding the files exactly as they were right after the last Turn below."
    : "The working directory is shared with that session, so files may have changed since.";

  return [
    `[Context from Polaris] This session is a fork of the session "${clip(options.parentTitle, 200)}". You have not seen its conversation, so here it is for context. ${where}`,
    "",
    "<earlier-conversation>",
    ...(omitted > 0 ? [`(${omitted} earlier Turn${omitted === 1 ? "" : "s"} omitted)`, ""] : []),
    blocks.join("\n\n"),
    "</earlier-conversation>",
    "",
    "The user's new request follows.",
    "",
    options.prompt,
  ].join("\n");
};

import { childEnv } from "../../service/childEnv.ts";
import { Effect } from "effect";
import { WorktreeSetupRun } from "@polaris/protocol";

const MAX_OUTPUT = 256 * 1024;

/** Keep draining both pipes even after the retained transcript tail reaches its limit. */
const output = async (pipe: ReadableStream<Uint8Array>) => {
  const reader = pipe.getReader();
  const decoder = new TextDecoder();
  let text = "";

  while (true) {
    const next = await reader.read();

    if (next.done) break;
    text = (text + decoder.decode(next.value, { stream: true })).slice(-MAX_OUTPUT);
  }

  return text + decoder.decode();
};

export const executeSetup = Effect.fn("WorktreeSetup.execute")(function* (run: WorktreeSetupRun) {
  const proc = yield* Effect.acquireRelease(
    Effect.try({
      try: () =>
        Bun.spawn(["/bin/sh", "-c", run.command], {
          cwd: run.cwd,
          env: c
          stdin: "ignore",
          stdout: "pipe",
          stderr: "pipe",
          detached: true,
        }),
      catch: (error) => new Error(String(error)),
    }),
    (child) =>
      Effect.promise(async () => {
        if (child.exitCode !== null) return;

        try {
          process.kill(-child.pid, "SIGKILL");
        } catch {
          child.kill("SIGKILL");
        }

        await child.exited;
      })
  );

  const [stdout, stderr, code] = yield* Effect.promise(() =>
    Promise.all([output(proc.stdout), output(proc.stderr), proc.exited])
  );

  return new WorktreeSetupRun({
    id: run.id,
    constellationId: run.constellationId,
    taskId: run.taskId,
    command: run.command,
    cwd: run.cwd,
    startedAt: run.startedAt,
    output: (stdout + stderr).slice(-MAX_OUTPUT),
    exitCode: code,
    status: code === 0 ? "completed" : "failed",
    endedAt: new Date().toISOString(),
  });
});

