  TurnItemJson,
  TurnJson,
  writeEvent,
  writeProjection,
} from "./projection.ts";

export { type EphemeralItem, LiveItem } from "./hub.ts";

export interface StoreSettings {
  /**
   * Items buffered per live subscriber. A subscriber that falls this far behind
   * (a stalled Client) is dropped: its stream ends after the items it already
   * has, and the Client resubscribes from its last sequence. Ephemeral items are
   * dropped earlier, once the buffer is half full, so they never cost a subscriber.
   */
  readonly subscriberCapacity: number;
}

export const StoreConfig = Context.Reference<StoreSettings>("polaris/daemon/store/StoreConfig", {
  defaultValue: () => ({ subscriberCapacity: 4096 }),
});

export type CommitResult =
  | {
      readonly _tag: "Committed";
      readonly envelopes: ReadonlyArray<EventEnvelope>;
      /** Sequence of the last event written; null when the command produced none. */
      readonly sequence: Sequence | null;
      readonly model: ReadModel;
    }
  | {
      /** The command id already has a receipt; nothing was written. */
      readonly _tag: "Duplicate";
      readonly sequence: Sequence | null;
    };

/** Constructors and matchers for `CommitResult`. */
export const CommitResult = Data.taggedEnum<CommitResult>();

export type Rejection = CommandRejected | NotFound;

export interface CommitOptions<E extends Rejection> {
  /** Client-chosen id; null for events the Daemon records on its own (Harness output, recovery). */
  readonly commandId: CommandId | null;
  /** Runs under the commit lock against the latest read model. */
  readonly decide: (model: ReadModel) => Effect.Effect<ReadonlyArray<DomainEvent>, E>;
}

export class EventStore extends Context.Service<
  EventStore,
  {
    readonly model: Effect.Effect<ReadModel>;
    /**
     * Decide and commit atomically. A command id seen before returns
     * `Duplicate` (or re-fails with the original rejection) without deciding again.
     */
    readonly commit: <E extends Rejection = never>(
      options: CommitOptions<E>
    ) => Effect.Effect<CommitResult, E | ServiceError>;
    /**
     * Subscribe before reading a snapshot, so nothing committed in between is
     * missed. The subscription lives as long as the scope; `filter` keeps
     * unrelated items out of its buffer. The stream ends (without an error) if
     * the subscriber falls `subscriberCapacity` items behind; resume from the
     * last sequence seen.
     */
    readonly subscribe: (options?: {
      /** Only this session's items; cheaper than a filter, since other sessions' items skip it. */
      readonly sessionId?: SessionId;
      readonly filter?: (item: LiveItem) => boolean;
    }) => Effect.Effect<Stream.Stream<LiveItem>, never, Scope.Scope>;
    readonly publishEphemeral: (item: EphemeralItem) => Effect.Effect<void>;
    /** Live subscribers right now (for tests and diagnostics). */
    readonly subscriberCount: Effect.Effect<number>;
    /**
     * Committed events with `after < sequence <= upTo`, in order. With a
     * session id, only that session's events; without, the Host stream's events.
     */
    readonly readEvents: (options: {
      readonly after: number;
      readonly upTo: number;
      readonly sessionId: SessionId | null;
    }) => Effect.Effect<ReadonlyArray<EventEnvelope>, ServiceError>;
    /**
     * A session's Turns from SQL, ordered by index: those with `index < beforeIndex`
     * (all when null), at most the last `limit` of them (all when null).
     */
    readonly readTurns: (options: {
      readonly sessionId: SessionId;
      readonly beforeIndex: number | null;
      readonly limit: number | null;
    }) => Effect.Effect<ReadonlyArray<Turn>, ServiceError>;
    /** The last recorded state of a Worktree, even one since removed (from its `WorktreeDetected`). */
    readonly lastKnownWorktree: (
      worktreeId: Worktree["id"]
    ) => Effect.Effect<Worktree | null, ServiceError>;
    /** Completed items of the given Turns (not their Subagents'), as of `upTo`, in completion order. */
    readonly readTurnItems: (options: {
      readonly turnIds: ReadonlyArray<TurnId>;
      readonly upTo: number;
    }) => Effect.Effect<ReadonlyMap<TurnId, ReadonlyArray<TurnItem>>, ServiceError>;
    /**
     * The Subagents the given Turns spawned, with their own items as of `upTo`.
     * A Subagent's record is its latest, which may be newer than `upTo`; the
     * `SubagentStarted`/`SubagentEnded` events after it replace it by id.
     */
    readonly readSubagents: (options: {
      readonly turnIds: ReadonlyArray<TurnId>;
      readonly upTo: number;
    }) => Effect.Effect<ReadonlyMap<TurnId, ReadonlyArray<SubagentDetail>>, ServiceError>;
    /** Risk Summaries and Verdicts, which live in SQL only (`review.ts`). */
    readonly review: ReviewReads;
  }
>()("polaris/daemon/store/EventStore") {
  static readonly layer = Layer.effect(
    EventStore,
    Effect.gen(function* () {
      const sql = yield* SqlClient.SqlClient;
      const loaded = yield* loadModel(sql).pipe(Effect.mapError(storeError("load the read model")));
      // A commit is durable once it is in the WAL: see docs/adr/0003-wal-with-synchronous-normal.md.
      yield* sql`PRAGMA synchronous = NORMAL`.pipe(Effect.orDie);
      const modelRef = yield* Ref.make(loaded);
      const { subscriberCapacity } = yield* StoreConfig;
      const hub = new LiveHub(subscriberCapacity);
      const commit = yield* groupCommit({ sql, modelRef, hub });

      const readEvents = (options: {
        readonly after: number;
        readonly upTo: number;
        readonly sessionId: SessionId | null;
      }) =>
        (options.sessionId === null
          ? sql<EventRow>`
              SELECT sequence, occurred_at, command_id, payload FROM events
              WHERE sequence > ${options.after} AND sequence <= ${options.upTo}
                AND event_type NOT IN ${sql.in(sessionOnlyEventTypes)}
              ORDER BY sequence`
          : sql<EventRow>`
              SELECT sequence, occurred_at, command_id, payload FROM events
              WHERE session_id = ${options.sessionId}
                AND sequence > ${options.after} AND sequence <= ${options.upTo}
              ORDER BY sequence`
        ).pipe(
          Effect.map((rows) => rows.map(decodeEventRow)),
          Effect.mapError(storeError("read events"))
        );

      const readTurnItems = (options: {
        readonly turnIds: ReadonlyArray<TurnId>;
        readonly upTo: number;
      }) =>
        Effect.gen(function* () {
          if (options.turnIds.length === 0) return new Map<TurnId, Array<TurnItem>>();

          const rows = yield* sql<{ turn_id: string; item_id: string; data: string }>`
            SELECT turn_id, item_id, data FROM turn_items
            WHERE turn_id IN ${sql.in(options.turnIds)} AND sequence <= ${options.upTo}
              AND subagent_id IS NULL
            ORDER BY sequence`;

          // An item completed twice keeps its first position and its latest content.
          const byTurn = new Map<TurnId, Map<string, TurnItem>>();

          for (const row of rows) {
            const turnId = TurnId.make(row.turn_id);
            const items = byTurn.get(turnId) ?? new Map<string, TurnItem>();
            items.set(row.item_id, TurnItemJson.decode(row.data));
            byTurn.set(turnId, items);
          }

          return new Map([...byTurn].map(([turnId, items]) => [turnId, [...items.values()]]));
        }).pipe(Effect.mapError(storeError("read turn items")));

      const readSubagents = (options: {
        readonly turnIds: ReadonlyArray<TurnId>;
        readonly upTo: number;
      }) =>
        Effect.gen(function* () {
          if (options.turnIds.length === 0) return new Map<TurnId, Array<SubagentDetail>>();

          const subagents = yield* sql<{ data: string }>`
            SELECT data FROM subagents WHERE turn_id IN ${sql.in(options.turnIds)}`;

          if (subagents.length === 0) return new Map<TurnId, Array<SubagentDetail>>();

          const rows = yield* sql<{ subagent_id: string; item_id: string; data: string }>`
            SELECT subagent_id, item_id, data FROM turn_items
            WHERE turn_id IN ${sql.in(options.turnIds)} AND sequence <= ${options.upTo}
              AND subagent_id IS NOT NULL
            ORDER BY sequence`;

          // As for a Turn: an item completed twice keeps its first position and its latest content.
          const items = new Map<string, Map<string, TurnItem>>();

          for (const row of rows) {
            const own = items.get(row.subagent_id) ?? new Map<string, TurnItem>();
            own.set(row.item_id, TurnItemJson.decode(row.data));
            items.set(row.subagent_id, own);
          }

          const byTurn = new Map<TurnId, Array<SubagentDetail>>();

          for (const row of subagents) {
            const subagent = SubagentJson.decode(row.data);
            const list = byTurn.get(subagent.turnId) ?? [];
            list.push(
              new SubagentDetail({ subagent, items: [...(items.get(subagent.id)?.values() ?? [])] })
            );
            byTurn.set(subagent.turnId, list);
          }

          for (const list of byTurn.values())
            list.sort((a, b) => a.subagent.startedAt.localeCompare(b.subagent.startedAt));

          return byTurn;
        }).pipe(Effect.mapError(storeError("read subagents")));

      const readTurns = (options: {
        readonly sessionId: SessionId;
        readonly beforeIndex: number | null;
        readonly limit: number | null;
      }) =>
        sql<{ data: string }>`
          SELECT data FROM (
            SELECT data, turn_index FROM turns
            WHERE session_id = ${options.sessionId}
              AND turn_index < ${options.beforeIndex ?? Number.MAX_SAFE_INTEGER}
            ORDER BY turn_index DESC
            LIMIT ${options.limit ?? -1}
          ) ORDER BY turn_index`.pipe(
          Effect.map((rows) => rows.map((row) => TurnJson.decode(row.data))),
          Effect.mapError(storeError("read turns"))
        );

      const lastKnownWorktree = (worktreeId: Worktree["id"]) =>
        sql<{ payload: string }>`
          SELECT payload FROM events
          WHERE event_type = 'WorktreeDetected'
            AND json_extract(payload, '$.worktree.id') = ${worktreeId}
          ORDER BY sequence DESC LIMIT 1`.pipe(
          Effect.map((rows) => {
            const event = rows[0] === undefined ? null : EventJson.decode(rows[0].payload);

            return Predicate.isTagged(event, "WorktreeDetected") ? event.worktree : null;
          }),
          Effect.mapError(storeError("read a Worktree"))
        );

      return EventStore.of({
        model: Ref.get(modelRef),
        commit,
        subscribe: (options) => hub.subscribe(options),
        publishEphemeral: (item) => Effect.sync(() => hub.publish(item)),
        subscriberCount: Effect.sync(() => hub.size),
        readEvents,
        readTurns,
        lastKnownWorktree,
        readTurnItems,
        readSubagents,
        review: reviewReads(sql),
      });
    })
  );

  /** A migrated SQLite database at `filename` (`:memory:` in tests). */
  static readonly layerSqlite = (filename: string) =>
    EventStore.layer.pipe(
      Layer.provide(MigrationsLayer),
      Layer.provide(SqliteClient.layer({ filename })),
      Layer.orDie
    );

  /** The Host's database at `~/.polaris/state.sqlite`. */
  static readonly layerLive = Layer.unwrap(
    Effect.sync(() => {
      const file = paths().database;
      mkdirSync(dirname(file), { recursive: true });

      return EventStore.layerSqlite(file);
    })
  );
}

// ── Group commit (docs/adr/0002-group-commit.md) ────────────────────────────

interface Pending {
  readonly options: CommitOptions<Rejection>;
  readonly deferred: Deferred.Deferred<CommitResult, Rejection | ServiceError>;
  /** The caller was interrupted before its batch started: skip it. */
  abandoned: boolean;
}

type Outcome = Exit.Exit<CommitResult, Rejection | ServiceError>;

interface Receipt {
  readonly sequence: number | null;
  readonly rejection: Rejection | null;
}

/** What the store's commit writes to and publishes on. */
interface CommitTarget {
  readonly sql: SqlClient.SqlClient;
  readonly modelRef: Ref.Ref<ReadModel>;
  readonly hub: LiveHub;
}

/** One batch in progress: the model so far, and what it will write and publish. */
interface Batch {
  readonly now: string;
  next: ReadModel;
  readonly writes: Array<Effect.Effect<unknown, SqlError.SqlError>>;
  readonly published: Array<EventEnvelope>;
  /** Receipts written earlier in this batch, not yet visible in SQL. */
  readonly receipts: Map<CommandId, Receipt>;
}

const sequenceOf = (value: number | null) => (value === null ? null : Sequence.make(value));

/** The store's `commit`: queued commits are decided in order and written one batch at a time. */
const groupCommit = ({ sql, modelRef, hub }: CommitTarget) =>
  Effect.gen(function* () {
    let queued: Array<Pending> = [];
    /** A drain is scheduled or running; later commits queue for it. */
    let writing = false;
    const context = yield* Effect.context<never>();

    const findReceipt = (batch: Batch, commandId: CommandId) =>
      Effect.suspend(() => {
        const known = batch.receipts.get(commandId);

        if (known !== undefined) return Effect.succeed<Receipt | undefined>(known);

        return sql<{ sequence: number | null; rejection: string | null }>`
          SELECT sequence, rejection FROM command_receipts WHERE command_id = ${commandId}`.pipe(
          Effect.map(([row]): Receipt | undefined =>
            row === undefined
              ? undefined
              : {
                  sequence: row.sequence,
                  rejection: row.rejection === null ? null : RejectionJson.decode(row.rejection),
                }
          ),
          Effect.mapError(storeError("read a command receipt"))
        );
      });

    const writeReceipt = (batch: Batch, commandId: CommandId, receipt: Receipt) => {
      batch.writes.push(
        sql`INSERT INTO command_receipts ${sql.insert({
          command_id: commandId,
          sequence: receipt.sequence,
          rejection: receipt.rejection === null ? null : RejectionJson.encode(receipt.rejection),
          recorded_at: batch.now,
        })}`
      );
      batch.receipts.set(commandId, receipt);
    };

    const rejected = (
      batch: Batch,
      commandId: CommandId | null,
      cause: Cause.Cause<Rejection>
    ): Outcome => {
      const rejection = Cause.findErrorOption(cause);

      if (commandId !== null && Option.isSome(rejection)) {
        writeReceipt(batch, commandId, { sequence: null, rejection: rejection.value });
      }

      return Exit.failCause(cause);
    };

    const committed = (
      batch: Batch,
      commandId: CommandId | null,
      events: ReadonlyArray<DomainEvent>
    ): Outcome => {
      const envelopes: Array<EventEnvelope> = [];

      for (const event of events) {
        const envelope = new EventEnvelope({
          sequence: Sequence.make(batch.next.sequence + 1),
          occurredAt: batch.now,
          commandId,
          event,
        });

        const after = project(batch.next, envelope);
        batch.writes.push(writeEvent(sql, envelope), writeProjection(sql, after, envelope));
        envelopes.push(envelope);
        batch.published.push(envelope);
        batch.next = after;
      }

      const sequence = envelopes.at(-1)?.sequence ?? null;

      if (commandId !== null) writeReceipt(batch, commandId, { sequence, rejection: null });

      return Exit.succeed(CommitResult.Committed({ envelopes, sequence, model: batch.next }));
    };

    /** Decide one command against the batch's model so far. */
    const decideOne = (batch: Batch, options: CommitOptions<Rejection>) =>
      Effect.gen(function* () {
        const { commandId } = options;

        if (commandId !== null) {
          const receipt = yield* findReceipt(batch, commandId);

          if (receipt !== undefined) {
            return receipt.rejection === null
              ? Exit.succeed(CommitResult.Duplicate({ sequence: sequenceOf(receipt.sequence) }))
              : Exit.fail(receipt.rejection);
          }
        }

        const decided = yield* Effect.exit(options.decide(batch.next));

        return Exit.isFailure(decided)
          ? rejected(batch, commandId, decided.cause)
          : committed(batch, commandId, decided.value);
      });

    const runBatch = (pending: ReadonlyArray<Pending>) =>
      Effect.gen(function* () {
        const batch: Batch = {
          now: new Date(yield* Clock.currentTimeMillis).toISOString(),
          next: yield* Ref.get(modelRef),
          writes: [],
          published: [],
          receipts: new Map(),
        };

        const outcomes: Array<Outcome> = [];

        for (const { options } of pending) outcomes.push(yield* decideOne(batch, options));

        if (batch.writes.length > 0) {
          yield* sql
            .withTransaction(Effect.forEach(batch.writes, (write) => write, { discard: true }))
            .pipe(Effect.mapError(storeError("commit events")));
        }

        yield* Ref.set(modelRef, batch.next);

        for (const envelope of batch.published) {
          hub.publish(LiveItem.Event({ envelope, sessionId: sessionOf(envelope.event) }));
        }

        return outcomes;
      });

    const settle = (batch: ReadonlyArray<Pending>, outcomes: ReadonlyArray<Outcome>) => {
      for (let i = 0; i < batch.length; i++) Deferred.doneUnsafe(batch[i]!.deferred, outcomes[i]!);
    };

    /** A failed batch settles each of its commands with the batch's failure. */
    const failedWith = (result: Exit.Exit<unknown, ServiceError>, size: number): Array<Outcome> =>
      Exit.isFailure(result)
        ? Array.from({ length: size }, () => Exit.failCause(result.cause))
        : [];

    const writeBatch = (taken: ReadonlyArray<Pending>) =>
      Effect.gen(function* () {
        const batch = taken.filter((pending) => !pending.abandoned);

        if (batch.length === 0) return;
        const result = yield* Effect.exit(runBatch(batch));

        if (Exit.isSuccess(result)) return settle(batch, result.value);

        if (batch.length === 1) return settle(batch, failedWith(result, 1));

        // A failed batch wrote nothing: commit its commands one by one, so one bad command only fails itself.
        for (const pending of batch) {
          const single = yield* Effect.exit(runBatch([pending]));
          settle([pending], Exit.isSuccess(single) ? single.value : failedWith(single, 1));
        }
      }).pipe(Effect.uninterruptible);

    /** Writes batches until nothing is queued. */
    const drain = Effect.gen(function* () {
      while (queued.length > 0) {
        const taken = queued;
        queued = [];
        yield* writeBatch(taken);
      }
    }).pipe(
      Effect.ensuring(
        Effect.sync(() => {
          writing = false;
        })
      ),
      Effect.uninterruptible
    );

    return <E extends Rejection>(options: CommitOptions<E>) =>
      Effect.suspend(() => {
        const pending: Pending = {
          options,
          deferred: Deferred.makeUnsafe(),
          abandoned: false,
        };

        queued.push(pending);

        if (!writing) {
          // A microtask: the fibers running now queue their commits first (docs/adr/0002-group-commit.md).
          writing = true;
          queueMicrotask(() => Effect.runForkWith(context)(drain));
        }

        // SAFETY: a command id names one command, so a rejection replayed from its receipt is one its `decide` failed with.
        return Deferred.await(pending.deferred).pipe(
          Effect.onInterrupt(() =>
            Effect.sync(() => {
              pending.abandoned = true;
            })
          )
        ) as Effect.Effect<CommitResult, E | ServiceError>;
      });
  });

import { Schema } from "effect";
import { LanguageError, LanguageInstallProgress } from "@polaris/protocol";
import { preflight } from "../catalog/selection.ts";
import { artifactIdentity } from "./identity.ts";
import { createVersionStorage } from "./storage.ts";
import {
  abortable,
  checkAbort,
  collect,
  failure,
  verifyIntegrity,
  verifyPayload,
} from "./validation.ts";
import {
  defaultLimits,
  upstreamRuntimeLimits,
  descriptor,
  validateHost,
  validatePlatform,
  type ExactArtifact,
  type InstallHandle,
  type InstalledVersion,
  type InstallerOptions,
  type InstallRequest,
  type Progress,
  type InstallLimits,
} from "./types.ts";

interface Waiter {
  resolve: (value: InstalledVersion) => void;
  reject: (error: LanguageError) => void;
}

interface Job {
  readonly exact: ExactArtifact;
  readonly id: string;
  readonly controller: AbortController;
  readonly waiters: Set<Waiter>;
  readonly rollback: boolean;
  done: Promise<void>;
  progress: Progress;
}

const normalizedError = (cause: unknown) =>
  Schema.is(LanguageError)(cause)
    ? cause
    : failure("install-failed", "Installation failed; working version retained", true);

const validateLimits = (limits: InstallLimits, caps = defaultLimits) => {
  for (const value of Object.values(limits)) {
    if (!Number.isSafeInteger(value) || value <= 0)
      throw failure("invalid-input", "Installer limits must be positive integers");
  }

  for (const key of Object.keys(defaultLimits)) {
    // SAFETY: keys originate from the complete InstallLimits defaults, never from untrusted input.
    const field = key as keyof InstallLimits;

    if (limits[field] > defaultLimits[field])
      throw failure("invalid-input", "Installer limits may only lower safety caps");
  }

  return limits;
};

/** Detached construction seam. Caller supplies transport/decoder; exact-artifact approval defaults deny. */
export async function createInstaller(options: InstallerOptions) {
  const hostId = validateHost(options.hostId);
  const platform = validatePlatform(options.platform);
  const caps = options.sizeProfile === "upstream-runtime" ? upstreamRuntimeLimits : defaultLimits;
  const limits = validateLimits({ ...caps, ...options.limits }, caps);
  const storage = await createVersionStorage(options.root, limits, { hostId, platform });
  const jobs = new Map<string, Job>();
  const latest = new Map<string, Progress>();
  const listeners = new Set<(progress: Progress) => void>();
  let disposed = false;
  let waiterCount = 0;
  const cleanupFailures: string[] = [];

  function exactFor(request: InstallRequest): ExactArtifact {
    const { tool, raw } = descriptor(request.tool, limits.metadataBytes);

    if (!request.connected) throw failure("not-connected", "Host is unavailable", true);

    if (tool.disposition !== "offered") throw failure("not-offered", "Tool is not offered");
    const checked = preflight({ tool, platform, probes: request.probes, phase: "install" });

    if (checked.status !== "eligible") throw failure(checked.status, checked.reason, true);

    if (!checked.artifact) throw failure("unsupported-platform", "No matching artifact");

    const identity = artifactIdentity({
      hostId,
      platform,
      descriptor: raw,
      artifact: checked.artifact,
    });

    return { hostId, platform, tool, descriptor: raw, artifact: checked.artifact, identity };
  }

  function emit(
    job: Job,
    phase: Progress["phase"],
    message = "",
    downloadedBytes = job.progress.downloadedBytes
  ) {
    job.progress = LanguageInstallProgress.make({
      ...job.progress,
      phase,
      message,
      downloadedBytes,
      sequence: job.progress.sequence + 1,
    });
    latest.delete(job.exact.tool.id);

    while (latest.size >= 256) latest.delete(latest.keys().next().value!);
    latest.set(job.exact.tool.id, job.progress);

    for (const listener of listeners) {
      try {
        listener(structuredClone(job.progress));
      } catch {
        /* Observer errors do not alter installation outcomes. */
      }
    }
  }

  async function approve(exact: ExactArtifact, signal: AbortSignal) {
    checkAbort(signal);

    if (!options.adapters.approve)
      throw failure("audit-required", "Exact artifact approval required");

    const decision = await abortable(
      options.adapters.approve(structuredClone(exact), signal),
      signal
    );

    if (decision.approved !== true || decision.identity !== exact.identity)
      throw failure("audit-required", "Exact artifact approval denied");
    checkAbort(signal);
  }

  async function beforeSelect(job: Job) {
    const signal = job.controller.signal;
    await approve(job.exact, signal);

    if (options.adapters.beforeSelect)
      await abortable(options.adapters.beforeSelect(structuredClone(job.exact), signal), signal);
    await approve(job.exact, signal);
    checkAbort(signal);
    emit(job, "activating");
    checkAbort(signal);
  }

  async function install(job: Job) {
    const { exact, controller } = job;
    const signal = controller.signal;
    const retained = await storage.current(exact.tool.id);
    job.progress = LanguageInstallProgress.make({
      ...job.progress,
      activeVersion: retained?.version ?? null,
    });
    emit(job, "preflight");
    await approve(exact, signal);

    if (retained?.identity === exact.identity) return retained;

    if (job.rollback) {
      await storage.load(exact.tool.id, exact.identity);
      await beforeSelect(job);

      return storage.select(exact.tool.id, exact.identity, signal);
    }

    emit(job, "downloading");

    const bytes = await collect(
      options.adapters.download(structuredClone(exact), signal),
      signal,
      limits,
      (size) => emit(job, "downloading", "", size)
    );

    emit(job, "verifying");

    if (!verifyIntegrity(bytes, exact.artifact.integrity))
      throw failure("audit-required", "Artifact integrity failed");

    checkAbort(signal);

    const payload = await abortable(
      options.adapters.decode(bytes, structuredClone(exact), signal),
      signal
    );

    const entries = verifyPayload(bytes, payload, exact, limits).map((entry) => ({
      ...entry,
      bytes: Uint8Array.from(entry.bytes),
    }));

    checkAbort(signal);
    emit(job, "staging");

    return storage.stage(exact, entries, signal, () => beforeSelect(job));
  }

  async function run(job: Job, intent: InstallRequest["intent"]) {
    const timer = setTimeout(
      () => job.controller.abort(failure("timeout", "Installation deadline exceeded", true)),
      limits.timeoutMs
    );

    let release: (() => Promise<void>) | undefined;
    let result: InstalledVersion | undefined;
    let problem: LanguageError | undefined;

    try {
      checkAbort(job.controller.signal);
      release = await storage.lock(job.exact.tool.id);
      const retained = await storage.current(job.exact.tool.id);
      job.progress = LanguageInstallProgress.make({
        ...job.progress,
        activeVersion: retained?.version ?? null,
      });

      if (
        retained &&
        retained.identity !== job.exact.identity &&
        intent !== "update" &&
        !job.rollback
      )
        throw failure("conflict", "Version updates require an explicit update request", true);
      result = await install(job);
    } catch (error) {
      problem = normalizedError(error);

      if (!job.controller.signal.aborted) job.controller.abort(problem);
    } finally {
      clearTimeout(timer);

      if (release)
        await release().catch(() => {
          cleanupFailures.push(job.id);

          if (cleanupFailures.length > 64) cleanupFailures.shift();
        });

      if (options.adapters.afterSelection)
        await options.adapters.afterSelection(structuredClone(job.exact)).catch(() => {
          cleanupFailures.push(job.id);

          if (cleanupFailures.length > 64) cleanupFailures.shift();
        });
      jobs.delete(job.exact.tool.id);
    }

    if (result) {
      job.progress = LanguageInstallProgress.make({
        ...job.progress,
        activeVersion: result.version,
      });
      emit(job, "completed");

      for (const waiter of job.waiters) waiter.resolve(structuredClone(result));
    } else {
      const error = problem ?? failure("install-failed", "Installation failed", true);
      emit(
        job,
        error.reason === "cancelled" || error.reason === "timeout" ? "cancelled" : "failed",
        error.message
      );

      for (const waiter of job.waiters) waiter.reject(error);
    }

    waiterCount -= job.waiters.size;
    job.waiters.clear();
  }

  function attach(job: Job): InstallHandle {
    if (waiterCount >= limits.waiters)
      throw failure("queue-full", "Installer consumer limit reached", true);
    let waiter: Waiter;

    const result = new Promise<InstalledVersion>((resolve, reject) => {
      waiter = { resolve, reject };
    });

    // SAFETY: the Promise executor runs synchronously and initializes waiter before it is used.
    const consumer = waiter!;
    job.waiters.add(consumer);
    waiterCount++;

    return {
      jobId: job.id,
      result,
      cancel: () => {
        if (!job.waiters.delete(consumer)) return;
        waiterCount--;
        consumer.reject(failure("cancelled", "Installation consumer cancelled", true));

        if (job.waiters.size === 0) job.controller.abort();
      },
    };
  }

  function start(request: InstallRequest, rollback = false): InstallHandle {
    if (disposed) throw failure("cancelled", "Installer is disposed");
    let exact: ExactArtifact;

    try {
      exact = exactFor(request);
    } catch (cause) {
      if (Schema.is(LanguageError)(cause)) throw cause;
      throw failure("invalid-input", "Invalid catalog descriptor");
    }

    const existing = jobs.get(exact.tool.id);

    if (existing) {
      if (
        existing.exact.identity !== exact.identity ||
        existing.rollback !== rollback ||
        existing.controller.signal.aborted
      )
        throw failure("conflict", "Another version or operation is pending", true);

      return attach(existing);
    }

    if (jobs.size >= limits.jobs) throw failure("queue-full", "Installer job limit reached", true);
    const id = `install-${crypto.randomUUID()}`;

    const job: Job = {
      exact,
      id,
      controller: new AbortController(),
      waiters: new Set(),
      rollback,
      done: Promise.resolve(),
      progress: LanguageInstallProgress.make({
        hostId,
        toolId: exact.tool.id,
        version: exact.tool.version,
        jobId: id,
        sequence: 0,
        phase: "queued",
        downloadedBytes: 0,
        totalBytes: null,
        message: "",
        activeVersion: null,
      }),
    };

    const handle = attach(job);
    jobs.set(exact.tool.id, job);
    job.done = Promise.resolve().then(() => run(job, request.intent));
    emit(job, "queued");

    return handle;
  }

  return {
    install: (request: InstallRequest) => start(request),
    rollback: (request: Omit<InstallRequest, "intent">) =>
      start({ ...request, intent: "update" }, true),
    current: (toolId: string) =>
      storage.current(toolId).catch((cause: unknown) => {
        throw Schema.is(LanguageError)(cause)
          ? cause
          : failure("install-failed", "Private installation could not be verified", true);
      }),
    versions: (toolId: string) =>
      storage.versions(toolId).catch((cause: unknown) => {
        throw Schema.is(LanguageError)(cause)
          ? cause
          : failure("install-failed", "Private installations could not be verified", true);
      }),
    recoveryFacts: (toolId: string) =>
      jobs.has(toolId) ? Promise.resolve([]) : storage.recoveryFacts(toolId),
    progress: (toolId: string) => {
      const value = latest.get(toolId);

      return value ? structuredClone(value) : null;
    },
    subscribe(listener: (progress: Progress) => void) {
      if (disposed) throw failure("cancelled", "Installer is disposed");

      if (listeners.size >= limits.listeners)
        throw failure("queue-full", "Installer observer limit reached");
      listeners.add(listener);

      return () => {
        listeners.delete(listener);
      };
    },
    stats: () => ({
      jobs: jobs.size,
      waiters: waiterCount,
      listeners: listeners.size,
      retainedProgress: latest.size,
      cleanupFailures: [...cleanupFailures],
      disposed,
    }),
    async dispose() {
      disposed = true;
      listeners.clear();

      for (const job of jobs.values()) job.controller.abort();
      await Promise.all([...jobs.values()].map((job) => job.done));
      latest.clear();
    },
  };
}

export type Installer = Awaited<ReturnType<typeof createInstaller>>;

export type {
  InstallHandle,
  InstallRequest,
  InstallerOptions,
  InstalledVersion,
  ExactArtifact,
  InstallerAdapters,
  ApprovalDecision,
  ArtifactPayload,
  InstallLimits,
  Progress,
} from "./types.ts";

export { defaultLimits } from "./types.ts";

import { sqlShellLaunch } from "../sql/launch.ts";
import { webLaunch, webProviders, webTools } from "../web/index.ts";
import { Match } from "effect";
import { pythonLaunch } from "../python/launch.ts";
import { createHostPrerequisiteProbe } from "../install/hostStateProbes.ts";
import { interpreterEntry } from "../python/environment.ts";
import { join } from "node:path";
import type { LanguageEffectiveSettings } from "@polaris/protocol";
import { runtimeProbeAdapter } from "../availability/probes.ts";
import { prerequisiteVersions } from "../availability/prerequisiteVersions.ts";
import { runHostVersion } from "../availability/version-process.ts";
import type { VerifiedLaunchPlan } from "../availability/launch.ts";
import type { Tool } from "../catalog/model.ts";
import type { DiscoveryFacts } from "../discovery/index.ts";
import type { HostInstallation, ObservationAdmission } from "../install/host.ts";
import { descriptor, defaultLimits, type InstalledVersion } from "../install/types.ts";
import { checkAbort, failure } from "../install/validation.ts";

export interface ManagedDelivery {
  bind: (host: HostInstallation) => void;
  ensure: (
    settings: typeof LanguageEffectiveSettings.Type,
    admission: ObservationAdmission,
    signal: AbortSignal,
    providerId?: string
  ) => Promise<void>;
  plan: (facts: DiscoveryFacts, installed: InstalledVersion) => Promise<VerifiedLaunchPlan>;
}

function matchesPin(current: InstalledVersion | null, pinned: Tool) {
  if (current === null || current.version !== pinned.version) return false;
  const installed = descriptor(current.descriptor, defaultLimits.metadataBytes).tool;
  const selected = installed.artifacts.find((artifact) => artifact.id === current.artifactId);

  return (
    installed.id === pinned.id &&
    selected !== undefined &&
    pinned.artifacts.some(
      (artifact) =>
        artifact.id === current.artifactId &&
        artifact.integrity === current.integrity &&
        artifact.auditRoot === selected?.auditRoot &&
        artifact.audit === selected.audit
    )
  );
}

export function createManagedDelivery(
  pythonHost?: Parameters<typeof createHostPrerequisiteProbe>[0]
) {
  let host: HostInstallation | undefined;
  const hostPrerequisites = createHostPrerequisiteProbe(pythonHost);

  const installation = () => {
    if (host === undefined) throw failure("not-ready", "Private runtime is unavailable");

    return host;
  };

  const developerProbes = runtimeProbeAdapter({
    configured: {},
    searchPath: (process.env.PATH ?? "").split(":"),
    versions: prerequisiteVersions,
    run: runHostVersion,
  });

  const privateNode = async () => {
    const installed = await installation().current("node");

    return installed === null
      ? null
      : { executable: join(installed.directory, "bin/node"), version: installed.version };
  };

  const delivery: ManagedDelivery = {
    bind: (value) => {
      host = value;
    },
    async ensure(settings, admission, signal, providerId = "typescript-language-server") {
      const tools =
        webTools.includes(providerId) || providerId in webProviders
          ? ["node", webProviders[providerId] ?? providerId]
          : Match.value(providerId).pipe(
              Match.when("basedpyright", () => ["node", "basedpyright"]),
              Match.when("ruff", () => ["ruff"]),
              Match.when("bash-language-server", () => ["node", "shfmt", "bash-language-server"]),
              Match.when("sqllens-language-server", () => [
                "node",
                "sql-formatter",
                "sqllens-language-server",
              ]),
              Match.orElse(() => ["node", "typescript", "typescript-language-server"])
            );

      for (const toolId of tools) {
        checkAbort(signal);
        await admission.requireCurrent(signal);

        const current = await installation().current(toolId);
        const pinned = installation().tool(toolId);

        if (matchesPin(current, pinned)) continue;

        if (settings.settings.downloadLanguageToolsAutomatically === false)
          throw failure(
            "not-installed",
            "Download language tools automatically is off; this Host needs the selected language tools"
          );

        const handle = await installation().install(
          toolId,
          current === null ? "encounter" : "update",
          admission.requireCurrent,
          signal,
          admission
        );

        await handle.result;
        await admission.requireCurrent(signal);
      }
    },
    async plan(facts, installed) {
      const node = facts.providerId === "ruff" ? null : await privateNode();

      if (["basedpyright", "ruff"].includes(facts.providerId))
        return pythonLaunch(facts, installed, node);

      if (["bash-language-server", "sqllens-language-server"].includes(facts.providerId))
        return sqlShellLaunch(facts, installed, node, installation(), pythonHost);

      if (facts.providerId in webProviders) return webLaunch(facts, installed, node);
      const typescript = await installation().current("typescript");

      if (node === null || typescript === null)
        throw failure("not-installed", "Private Node and bundled TypeScript are not installed");
      const entry = join(installed.directory, "lib/cli.mjs");
      const project = !facts.bundledTypeScript && (facts.sdk !== null || facts.plugins.length > 0);

      if (project && facts.sdkVersion?.startsWith("7.")) {
        if (facts.nativeServer === null)
          throw failure(
            "missing-prerequisite",
            "The project's native TypeScript platform package is missing"
          );

        return {
          identity: installed.identity,
          entry: facts.nativeServer,
          launch: {
            executable: facts.nativeServer,
            args: ["--lsp", "--stdio"],
            cwd: facts.projectRoot,
            environment: { NODE_OPTIONS: "", NODE_PATH: "" },
          },
        };
      }

      return {
        identity: installed.identity,
        entry,
        runtimeExecutable: node.executable,
        launch: {
          executable: node.executable,
          args: [entry, "--stdio"],
          cwd: facts.projectRoot,
          environment: {
            NODE_OPTIONS: project
              ? ""
              : `--require ${JSON.stringify(join(typescript.directory, "plugin-guard.cjs"))}`,
            NODE_PATH: "",
            PATH: join(node.executable, ".."),
          },
          initializationOptions: {
            tsserver: {
              path:
                project && facts.tsserver !== null
                  ? facts.tsserver
                  : join(typescript.directory, "lib/tsserver.js"),
              useSyntaxServer: "never",
            },
            disableAutomaticTypingAcquisition: true,
            plugins: [],
          },
        },
      };
    },
  };

  return {
    delivery,
    async observe(
      tool: Tool,
      _phase: "install" | "feature",
      trusted: boolean,
      signal: AbortSignal,
      admission?: ObservationAdmission
    ) {
      const nodeRequirements = tool.requirements.filter((requirement) => requirement.id === "node");

      const others = tool.requirements.filter(
        (requirement) => !["node", "python-interpreter", "shellcheck"].includes(requirement.id)
      );

      const node = nodeRequirements.length ? await privateNode() : null;

      const probes = nodeRequirements.map(({ id }) => ({
        id,
        executable: node?.executable ?? null,
        version: node?.version ?? null,
      }));

      const python = tool.requirements.find(
        (requirement) => requirement.id === "python-interpreter"
      );

      if (python !== undefined) {
        const entry = admission?.pythonInterpreter;

        const presence =
          entry === undefined ? await hostPrerequisites().probe(python, signal) : null;

        const executable = entry === undefined ? (presence?.path ?? null) : entry;

        if (executable !== null) await interpreterEntry(executable);
        probes.push({ id: python.id, executable, version: executable === null ? null : "present" });
      }

      const shellcheck = tool.requirements.find((requirement) => requirement.id === "shellcheck");

      if (shellcheck !== undefined) {
        const present = await hostPrerequisites().probe(shellcheck, signal);
        probes.push({
          id: shellcheck.id,
          executable: present.path,
          version: present.path === null ? null : "present",
        });
      }

      probes.push(...(await developerProbes(others, trusted, signal, admission)));

      return { connected: true, probes };
    },
    dispose: () => developerProbes.dispose(),
  };
}

/**
 * One Rules run over a change: secrets (Betterleaks) and patterns (ast-grep)
 * side by side, on the lines the change adds only.
 *
 * - `history` (a pull request): Betterleaks reads the commits `base..head`
 *   itself (`git log -p -U0`, added lines only), so a secret added and then
 *   removed inside the PR is still reported.
 * - `snapshot` (Agent Session Turns): `base` and `head` are checkpoint
 *   commits or trees; both scanners read the changed files at `head` and keep
 *   what overlaps the added lines of `git diff -U0`.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { RiskFinding } from "@polaris/protocol";
import { type AddedLines, addedLines, overlapsAdded } from "./addedLines.ts";
import { patternFinding, secretFinding } from "./findings.ts";
import { materialize, removeMaterialized } from "./materialize.ts";
import { runPatternScan } from "./patterns/client.ts";
import { builtinPack, languageOf, type PackLanguage } from "./patterns/pack.ts";
import { locateBetterleaks, scanSecrets } from "./secrets/betterleaks.ts";

export type RulesMode = "history" | "snapshot";

export interface RulesRequest {
  /** A checkout of the repository holding `base` and `head`. */
  readonly cwd: string;
  readonly base: string;
  readonly head: string;
  readonly mode: RulesMode;
}

export interface RulesOutcome {
  /** Ranked by nothing yet: in the order found, deduplicated by id. */
  readonly findings: ReadonlyArray<RiskFinding>;
  /** What a user should know about the run (a scanner unavailable, files skipped); empty when clean. */
  readonly notes: ReadonlyArray<string>;
  /** False when both scanners failed: there is nothing to show. */
  readonly ok: boolean;
}

const secretsPart = async (
  request: RulesRequest,
  added: AddedLines,
  dir: string,
  signal: AbortSignal
): Promise<ReadonlyArray<RiskFinding>> => {
  const binary = locateBetterleaks();

  if (binary === null) throw new Error("Betterleaks is not installed beside the Daemon");
  const history = request.mode === "history";

  const scan = history
    ? await scanSecrets(
        binary,
        request.cwd,
        { kind: "history", base: request.base, head: request.head },
        signal
      )
    : await scanSecrets(binary, dir, { kind: "files" }, signal);

  if (scan.state !== "complete") throw new Error(`Betterleaks stopped early (${scan.state})`);

  return scan.hits
    .filter((hit) => history || overlapsAdded(added, hit.path, hit.start, hit.end))
    .map((hit) => secretFinding(hit, history));
};

const patternsPart = async (
  added: AddedLines,
  dir: string,
  paths: ReadonlyArray<string>,
  signal: AbortSignal
): Promise<{ findings: ReadonlyArray<RiskFinding>; skipped: number }> => {
  const files = paths.flatMap((path) => {
    const language = languageOf(path);

    return language === null
      ? []
      : [{ path, language } satisfies { path: string; language: PackLanguage }];
  });

  const reply = await runPatternScan({ root: dir, files }, signal);
  const rules = new Map(builtinPack().map((rule) => [rule.id, rule]));
  const lines = new Map<string, ReadonlyArray<string>>();

  const linesOf = (path: string) => {
    const cached = lines.get(path);

    if (cached !== undefined) return cached;
    const read = readFileSync(join(dir, path), "utf8").split("\n");
    lines.set(path, read);

    return read;
  };

  const findings = reply.matches.flatMap((match) => {
    const rule = rules.get(match.ruleId);

    if (rule === undefined || !overlapsAdded(added, match.path, match.start, match.end)) return [];

    return [patternFinding(rule, match, linesOf(match.path))];
  });

  return { findings, skipped: reply.skipped.length };
};

const dedupe = (findings: ReadonlyArray<RiskFinding>) => [
  ...new Map(findings.map((finding) => [finding.id, finding])).values(),
];

/** Why a scanner failed, as a note: a settled promise's reason is whatever was thrown. */
const failureNote = (label: string, settled: PromiseRejectedResult) =>
  `${label} were not checked: ${settled.reason instanceof Error ? settled.reason.message : String(settled.reason)}`;

export const runRules = async (
  request: RulesRequest,
  signal: AbortSignal = new AbortController().signal
): Promise<RulesOutcome> => {
  const added = await addedLines(request.cwd, request.base, request.head);
  const materialized = await materialize(request.cwd, request.head, [...added.keys()]);
  const { dir, paths } = materialized;

  try {
    const [secrets, patterns] = await Promise.allSettled([
      secretsPart(request, added, dir, signal),
      patternsPart(added, dir, paths, signal),
    ]);

    const notes: Array<string> = [];

    if (secrets.status === "rejected") notes.push(failureNote("Secrets", secrets));

    if (patterns.status === "rejected") {
      notes.push(failureNote("Code patterns", patterns));
    } else if (patterns.value.skipped > 0) {
      notes.push(
        `${patterns.value.skipped} files were too large or unreadable for the pattern rules`
      );
    }

    return {
      findings: dedupe([
        ...(secrets.status === "fulfilled" ? secrets.value : []),
        ...(patterns.status === "fulfilled" ? patterns.value.findings : []),
      ]),
      notes,
      ok: secrets.status === "fulfilled" || patterns.status === "fulfilled",
    };
  } finally {
    removeMaterialized(dir);
  }
};

import { Schema } from "effect";
import {
  LanguageContextIdentity,
  LanguageCounter,
  LanguageDeadline,
  LanguageJson,
  LanguageJsonObject,
  LanguageKey,
  LanguageServerIdentifier,
  LanguageText,
  LanguageUri,
} from "./base.ts";
import {
  LanguageDiagnostics,
  LanguageProviderCapabilities,
  LanguageRequestFence,
  LanguageRuntime,
  LanguageSyncAck,
} from "./documents.ts";
import { LanguageEditProposal } from "./edits.ts";

export const LanguageMethod = Schema.String.check(
  Schema.isMinLength(1),
  Schema.isMaxLength(256),
  Schema.makeFilter((value) => !value.includes(String.fromCharCode(0)))
);

export const LanguageRpcId = Schema.Union([
  Schema.String.check(Schema.isMaxLength(256)),
  Schema.Int.check(
    Schema.isBetween({ minimum: -Number.MAX_SAFE_INTEGER, maximum: Number.MAX_SAFE_INTEGER })
  ),
]);

const NoField = Schema.optionalKey(Schema.Never);

const Parameters = Schema.optionalKey(
  Schema.Union([LanguageJsonObject, Schema.Array(LanguageJson).check(Schema.isMaxLength(4096))])
);

export const LanguageJsonRpcRequest = Schema.Struct({
  jsonrpc: Schema.Literal("2.0"),
  id: LanguageRpcId,
  method: LanguageMethod,
  params: Parameters,
  result: NoField,
  error: NoField,
});

export const LanguageJsonRpcNotification = Schema.Struct({
  jsonrpc: Schema.Literal("2.0"),
  method: LanguageMethod,
  params: Parameters,
  id: NoField,
  result: NoField,
  error: NoField,
});

export const LanguageJsonRpcResponse = Schema.Union([
  Schema.Struct({
    jsonrpc: Schema.Literal("2.0"),
    id: LanguageRpcId,
    result: LanguageJson,
    error: NoField,
    method: NoField,
    params: NoField,
  }),
  Schema.Struct({
    jsonrpc: Schema.Literal("2.0"),
    id: Schema.NullOr(LanguageRpcId),
    error: Schema.Struct({
      code: Schema.Int,
      message: LanguageText,
      data: Schema.optionalKey(LanguageJson),
    }),
    result: NoField,
    method: NoField,
    params: NoField,
  }),
]);

export const LanguageJsonRpcEnvelope = Schema.Union([
  LanguageJsonRpcRequest,
  LanguageJsonRpcNotification,
  LanguageJsonRpcResponse,
]);

export type LanguageJsonRpcEnvelope = typeof LanguageJsonRpcEnvelope.Type;

export const LanguageFeatureMethod = Schema.Literals([
  "textDocument/completion",
  "completionItem/resolve",
  "textDocument/hover",
  "textDocument/signatureHelp",
  "textDocument/definition",
  "textDocument/typeDefinition",
  "textDocument/implementation",
  "textDocument/references",
  "textDocument/prepareRename",
  "textDocument/rename",
  "textDocument/codeAction",
  "codeAction/resolve",
  "workspace/executeCommand",
  "textDocument/documentSymbol",
  "workspace/symbol",
  "workspaceSymbol/resolve",
  "textDocument/diagnostic",
  "workspace/diagnostic",
]);
/** LSP payloads remain bounded JSON; feature adapters decode method-specific data before use. */

export const LanguageFeatureRequest = Schema.Struct({
  requestId: LanguageKey,
  fence: LanguageRequestFence,
  method: LanguageFeatureMethod,
  params: LanguageJsonObject,
  deadline: LanguageDeadline,
});

export type LanguageFeatureRequest = typeof LanguageFeatureRequest.Type;

export const LanguageFeatureResult = Schema.Struct({
  requestId: LanguageKey,
  fence: LanguageRequestFence,
  result: LanguageJson,
  proposals: Schema.optionalKey(Schema.Array(LanguageEditProposal).check(Schema.isMaxLength(128))),
});

export type LanguageFeatureResult = typeof LanguageFeatureResult.Type;

export const LanguageConfigurationItem = Schema.Struct({
  scopeUri: Schema.optionalKey(LanguageUri),
  section: Schema.optionalKey(LanguageText),
});

export const LanguageRegistration = Schema.Struct({
  id: LanguageKey,
  method: LanguageMethod,
  registerOptions: Schema.optionalKey(LanguageJsonObject),
});

export const LanguageServerRequest = Schema.Struct({
  context: LanguageContextIdentity,
  request: LanguageJsonRpcRequest,
  deadline: LanguageDeadline,
});

export type LanguageServerRequest = typeof LanguageServerRequest.Type;

export const LanguageServerResponse = Schema.Struct({
  context: LanguageContextIdentity,
  response: LanguageJsonRpcResponse,
});

export const LanguageServerRequestPayload = Schema.TaggedUnion({
  Configuration: { items: Schema.Array(LanguageConfigurationItem).check(Schema.isMaxLength(256)) },
  Register: { registrations: Schema.Array(LanguageRegistration).check(Schema.isMaxLength(256)) },
  Unregister: {
    unregistrations: Schema.Array(
      Schema.Struct({ id: LanguageServerIdentifier, method: LanguageMethod })
    ).check(Schema.isMaxLength(256)),
  },
  ProgressCreate: { token: LanguageRpcId },
  WorkspaceFolders: {},
  ShowMessage: {
    type: Schema.Literals([1, 2, 3, 4]),
    message: LanguageText,
    actions: Schema.Array(Schema.Struct({ title: LanguageText })).check(Schema.isMaxLength(32)),
  },
  ApplyEdit: { proposal: LanguageEditProposal },
  Unsupported: { method: LanguageMethod },
});

/** Every configuration item has a corresponding result, in request order; null means no value. */

export const LanguageConfigurationResponse = Schema.Struct({
  values: Schema.Array(LanguageJson).check(Schema.isMaxLength(256)),
});

export const LanguageProgress = Schema.Struct({
  context: LanguageContextIdentity,
  token: LanguageRpcId,
  value: Schema.TaggedUnion({
    Begin: {
      title: LanguageText,
      message: Schema.optionalKey(LanguageText),
      percentage: Schema.optionalKey(
        Schema.Finite.check(Schema.isBetween({ minimum: 0, maximum: 100 }))
      ),
      cancellable: Schema.optionalKey(Schema.Boolean),
    },
    Report: {
      message: Schema.optionalKey(LanguageText),
      percentage: Schema.optionalKey(
        Schema.Finite.check(Schema.isBetween({ minimum: 0, maximum: 100 }))
      ),
      cancellable: Schema.optionalKey(Schema.Boolean),
    },
    End: { message: Schema.optionalKey(LanguageText) },
  }),
});

export const LanguageContextEvent = Schema.TaggedUnion({
  Snapshot: { context: LanguageContextIdentity, runtime: LanguageRuntime, ack: LanguageSyncAck },
  RuntimeChanged: { context: LanguageContextIdentity, runtime: LanguageRuntime },
  Synchronized: { ack: LanguageSyncAck },
  CapabilitiesChanged: {
    context: LanguageContextIdentity,
    capabilities: LanguageProviderCapabilities,
    registrations: Schema.Array(LanguageRegistration).check(Schema.isMaxLength(256)),
  },
  Diagnostics: { diagnostics: LanguageDiagnostics },
  ServerRequest: { request: LanguageServerRequest, payload: LanguageServerRequestPayload },
  Progress: { progress: LanguageProgress },
  Log: {
    context: LanguageContextIdentity,
    level: Schema.Literals(["error", "warning", "info", "debug"]),
    message: LanguageText,
  },
  Invalidated: {
    context: LanguageContextIdentity,
    reason: Schema.Literals(["connection-lost", "restart", "settings-changed", "closed"]),
  },
});

export type LanguageContextEvent = typeof LanguageContextEvent.Type;

export const LanguageLimits = Schema.Struct({
  messageBytes: LanguageCounter,
  queuedMessages: LanguageCounter,
  outstandingRequests: LanguageCounter,
  documents: LanguageCounter,
  diagnosticsPerDocument: LanguageCounter,
  logBytes: LanguageCounter,
  requestTimeoutMs: LanguageCounter,
});

history.before:
unregistrations: Schema.Array(Schema.Struct({ id: LanguageKey, method: LanguageMethod })).check(
  Schema.isMaxLength(256)
),

history.after:
unregistrations: Schema.Array(
  Schema.Struct({ id: LanguageServerIdentifier, method: LanguageMethod })
).check(Schema.isMaxLength(256)),

