/**
 * The open session's composer: sends a Turn, steers the one in flight, stops
 * it (esc), attaches files, and switches Model between Turns (or forks when
 * the Harness can't switch).
 */
import { fastToggle } from "../../harness/model/fast.ts";
import type { SessionId } from "@polaris/protocol";
import { useState } from "react";
import { type Harness, harnessHue } from "@polaris/ui";
import { Commands, newSessionId } from "../../../commands.ts";
import type { SessionData } from "../../../store/plain.ts";
import type { SessionModel } from "../../../store/sessionModel.ts";
import { useUploads } from "../../attachments/index.ts";
import { send } from "../dispatch.ts";
import {
  HarnessChip,
  type HarnessOption,
  type ModelChange,
  modelChange,
  type ModelChoice,
  useHarnessModels,
  useSignIn,
} from "../../harness/index.ts";
import { hasCapability, useElapsed, useHost } from "../hooks.ts";
import { formatElapsed, tildePath } from "../model/format.ts";
import {
  canQueue,
  type ComposerMode,
  composerMode,
  forkCommand,
  interruptCommand,
  openQuestion,
  placeholderFor,
  submitCommand,
} from "../model/intent.ts";
import { patchSessionUi, useSessionUi } from "../state.ts";
import type { OutboxActions } from "../outbox.ts";
import { promptFor } from "../../composer/index.ts";
import { RotatingVerb, useWorkingVerbs } from "../verbs/index.ts";
import { type ComposerCommands, DraftComposer } from "./DraftComposer.tsx";
import { useComposerCommands } from "./useComposerCommands.ts";
import { useSessionChrome } from "../chrome.ts";

export interface SessionComposerProps {
  readonly hostKey: string;
  readonly uiKey: string;
  readonly harness: Harness;
  readonly session: SessionData;
  readonly model: SessionModel;
  readonly branch: string | undefined;
  readonly onOpenSession?: ((sessionId: SessionId) => void) | undefined;
  /** Steers and follow-ups go through the session's outbox, which shows them until they land. */
  readonly outbox: OutboxActions;
}

const CHANGE_NOTES: Readonly<Record<ModelChange["kind"], string | undefined>> = {
  fork: "This harness can't switch model in a session; picking one forks a new session",
  set: "Applies from the next turn",
  blocked: undefined,
};

/** Picking a Model: `SetModel` between Turns, else a Fork on it; another Harness forks too. */
const useModelChange = ({ hostKey, session, model, onOpenSession }: SessionComposerProps) => {
  const host = useHost(hostKey);
  const { switchesModel } = useHarnessModels(hostKey, session.harness);
  const lastDone = model.turns.findLast((t) => t.turn.status !== "working")?.turn;
  const signIn = useSignIn(hostKey);

  const change = modelChange({
    switchesModel,
    canSetModel: hasCapability(host, "session.set-model"),
    canFork: hasCapability(host, "session.fork"),
    turnInFlight: model.turns.at(-1)?.turn.status === "working",
    hasFinishedTurn: lastDone !== undefined,
  });

  const fork = (harness: string, choice: ModelChoice | null) => {
    if (lastDone === undefined) return;
    const sessionId = newSessionId();

    const command = forkCommand({
      sessionId,
      fromSessionId: session.id,
      fromTurnId: lastDone.id,
      harness,
      model: choice?.model ?? null,
      effort: choice?.effort ?? null,
      serviceTier: choice?.serviceTier ?? null,
    });

    void send(hostKey, command, "Couldn't fork").then((ok) => {
      if (ok) onOpenSession?.(sessionId);
    });
  };

  const onModel = (choice: ModelChoice) => {
    if (change.kind === "set")
      void send(
        hostKey,
        Commands.SetModel({ sessionId: session.id, ...choice }),
        "Couldn't switch"
      );
    else if (change.kind === "fork") fork(session.harness, choice);
  };

  const onPick = (option: HarnessOption) =>
    option.status === "needs-sign-in" ? signIn.begin(option) : fork(option.kind, null);

  const note = CHANGE_NOTES[change.kind];

  return {
    onModel,
    note,
    blocked: change.kind === "blocked" ? change.reason : undefined,
    harnesses:
      lastDone !== undefined && hasCapability(host, "session.fork")
        ? {
            onPick,
            verb: (o: HarnessOption) =>
              o.status === "needs-sign-in" ? `Sign in to ${o.name}` : `Fork on ${o.name}`,
          }
        : undefined,
    dialog: signIn.dialog,
  };
};

const SEND_FAILURES: Readonly<Record<ComposerMode["kind"], string>> = {
  send: "Couldn't send",
  steer: "Couldn't steer",
  queue: "Couldn't queue",
  answer: "Couldn't answer",
  blocked: "Couldn't send",
};

export const SessionComposer = (props: SessionComposerProps) => {
  const { hostKey, uiKey, harness, session, model, branch } = props;
  const host = useHost(hostKey);
  const ui = useSessionUi(uiKey);
  const lastTurn = model.turns.at(-1)?.turn ?? null;
  const isWorking = lastTurn?.status === "working";
  const elapsed = useElapsed(lastTurn?.startedAt ?? null, isWorking);

  const verbs = useWorkingVerbs({
    hostKey,
    harness,
    cwd: session.cwd,
    turnId: isWorking ? (lastTurn?.id ?? null) : null,
  });

  const mode = composerMode({
    state: session.state,
    lastTurn: lastTurn?.status ?? null,
    pendingApprovals: model.pendingApprovals.length,
    question: openQuestion(model.pendingApprovals),
    canSteer: hasCapability(host, "session.steer"),
  });

  const [pickerOpen, setPickerOpen] = useState(false);
  const chrome = useSessionChrome();

  const change = useModelChange(props);
  const fastAvailable = session.harness === "codex" && hasCapability(host, "session.service-tier");

  const commands: ComposerCommands = useComposerCommands({
    hostKey,
    workspaceId: session.workspaceId,
    harness: session.harness,
    cwd: session.cwd,
    openModels: () => setPickerOpen(true),
    toggleFast: fastToggle(fastAvailable, change.blocked, session, change.onModel),
  });
  // What the Turn sends: a Codex custom prompt goes expanded (`promptFor`).

  const text = promptFor(ui.draft, commands.options);
  const draft = { text, attachments: ui.attachments.map((a) => a.id) };
  const command = submitCommand(mode, session.id, draft);

  const shownCwd = tildePath(session.cwd, host?.status.host?.homeDir ?? null);

  const { upload, uploads } = useUploads(
    {
      hostKey,
      workspaceId: session.workspaceId,
      sessionId: session.id,
      copyTo: { path: session.cwd, shown: shownCwd },
    },
    (staged) => patchSessionUi(uiKey, (u) => ({ attachments: [...u.attachments, staged] }))
  );

  const change = useModelChange(props);

  const queue = () => {
    if (!canQueue(mode) || (ui.draft.trim() === "" && ui.attachments.length === 0)) return;

    props.outbox.queue(text, ui.attachments);
    patchSessionUi(uiKey, () => ({ draft: "", attachments: [] }));
  };

  const submit = () => {
    if (chrome.composer !== undefined) return submitElsewhere(chrome.composer.onSubmit);

    if (mode.kind === "queue") return queue();

    if (command === null) return;

    if (mode.kind === "steer") {
      props.outbox.steer(text);
      patchSessionUi(uiKey, () => ({ draft: "" }));

      return;
    }

    const kept = ui;

    patchSessionUi(uiKey, () => ({ draft: "", attachments: [] }));
    void send(hostKey, command, SEND_FAILURES[mode.kind]).then((ok) => {
      if (!ok) patchSessionUi(uiKey, () => ({ draft: kept.draft, attachments: kept.attachments }));
    });
  };

  const submitElsewhere = (onSubmit: (text: string) => Promise<boolean>) => {
    const kept = ui.draft;

    if (kept.trim() === "") return;
    patchSessionUi(uiKey, () => ({ draft: "" }));
    void onSubmit(kept).then((ok) => {
      if (!ok) patchSessionUi(uiKey, () => ({ draft: kept }));
    });
  };

  const stop = () => {
    const interrupt = interruptCommand(session.id, lastTurn?.status ?? null);

    if (interrupt !== null) void send(hostKey, interrupt, "Couldn't stop");
  };

  return (
    <DraftComposer
      className="px-panel pb-panel"
      harness={harness}
      picker={
        <>
          <HarnessChip
            hostKey={hostKey}
            harness={harness}
            model={session.model}
            effort={session.effort}
            serviceTier={session.serviceTier}
            fastAvailable={fastAvailable}
            working={isWorking && session.state === "working"}
            modelNote={change.note}
            modelBlocked={change.blocked}
            onModel={change.onModel}
            open={pickerOpen}
            onOpenChange={setPickerOpen}
            {...(change.harnesses === undefined ? {} : { harnesses: change.harnesses })}
          />
          {change.dialog}
        </>
      }
      value={ui.draft}
      onChange={(text) => patchSessionUi(uiKey, () => ({ draft: text }))}
      onSubmit={submit}
      onQueue={canQueue(mode) ? queue : undefined}
      canSubmit={
        chrome.composer === undefined
          ? command !== null || (mode.kind === "queue" && ui.draft.trim() !== "")
          : ui.draft.trim() !== ""
      }
      placeholder={chrome.composer?.placeholder ?? placeholderFor(mode)}
      working={
        isWorking && session.state === "working"
          ? {
              elapsed: formatElapsed(elapsed),
              onStop: stop,
              label: (
                <RotatingVerb verbs={verbs} spoken={`${harnessHue(harness).name} is working`} />
              ),
            }
          : undefined
      }
      onEscape={isWorking ? stop : undefined}
      attachments={ui.attachments}
      uploads={uploads}
      copyTo={shownCwd}
      onFiles={hasCapability(host, "attachments.stage") ? upload : undefined}
      onRemoveAttachment={(a) =>
        patchSessionUi(uiKey, (u) => ({ attachments: u.attachments.filter((x) => x !== a) }))
      }
      branch={branch}
      commands={commands}
    />
  );
};

import { modelServerResources } from "@polaris/client/prediction/probe";
import type { MainPredictionPlacement } from "../prediction/placement.ts";
import type { PredictionSettings } from "../prediction/preferences.ts";
/**
 * The handlers behind `window.polaris.request`: one per method, each taking the
 * decoded input and returning a structured-clone-friendly output. Blobs the
 * Daemon sends (file contents, diffs) are taken here and cross IPC as bytes.
 */
import { clientCopy } from "../../shared/clientCopy.ts";
import type { HostConnection, LiveSession } from "@polaris/client";
import { FileContent, FileVersion } from "@polaris/protocol";
import { Effect, flow, Match, Schema } from "effect";
import type {
  FileVersionView,
  FileWriteView,
  Appearance,
  FileContentView,
  SessionDefault,
  IpcError,
  RequestOutput,
} from "../../shared/api.ts";
import {
  RequestInputs,
  type RequestInput,
  type RequestMethod,
  type SessionPrefsPatch,
} from "../../shared/contract.ts";
import { type ClientServices, HostDirectory, LOCAL_HOST_KEY, toIpcError } from "../hosts.ts";
import { githubHandlers } from "../github/ipc.ts";
import { gitHandlers } from "./git.ts";
import { constellationHandlers, resourceHandlers } from "./constellation.ts";
import { Machines } from "../machines/service.ts";
import type { NeedsYouSummary } from "../../shared/needsYou.ts";
import { appearanceOf, sessionPrefsOf, type Settings } from "../settings.ts";
import { estimate, type Prices } from "../prices.ts";
import { pricedStats } from "./constellationStats.ts";
import type { SnapshotCache } from "../snapshotCache.ts";
import { publishDirty, savedAll } from "../editorDirty.ts";
import type { AppUpdates } from "../updates/index.ts";
import type { PredictionBridge } from "../prediction/bridge.ts";

/** What the handlers need from the app outside the Client runtime. */
export interface RequestContext {
  readonly predictionBridge?: PredictionBridge;
  readonly predictionSettings?: PredictionSettings;
  readonly predictionPlacement?: MainPredictionPlacement;
  readonly updates: Pick<AppUpdates, "get" | "check" | "setAutomatic">;
  readonly restartToUpdate: () => void;
  readonly showAppInFinder: () => void;
  readonly settings: () => Settings;
  readonly cache: SnapshotCache;
  /** The price table for Usage estimates. */
  readonly prices: Prices;
  readonly setAppearance: (patch: Partial<Appearance>) => void;
  readonly setSessionDefault: (harness: string, value: SessionDefault | null) => void;
  readonly setSessions: (patch: SessionPrefsPatch) => void;
  readonly openExternal: (url: string) => Promise<void>;
  /** Finder, selecting the item at an absolute path on this Mac. */
  readonly revealInFinder: (path: string) => void;
  /** A fresh temp directory, or null when the local Daemon doesn't run the bench Harness. */
  readonly proofWorkspace: () => string | null;
  /** The literal Host aliases in `~/.ssh/config`. */
  readonly sshHosts: () => ReadonlyArray<string>;
  readonly setWelcomeSeen: () => void;
  readonly appVersion: string;
  /** The native folder picker on the focused window; null when cancelled. */
  readonly pickFolder: () => Promise<string | null>;
  readonly writeClipboard: (text: string) => Promise<void>;
  /** Cut, Copy, Paste or Select All in the focused window, as its Edit menu would. */
  readonly editAction: (action: "cut" | "copy" | "paste" | "selectAll") => void;
  /** Windows: the app menu under the title bar's lockup. */
  readonly showAppMenu: () => void;
  /** The renderer's Needs You summary, for the menu bar star, Dock badge and notifications. */
  readonly needsYou: (summary: NeedsYouSummary) => void;
}

export type Handler<M extends RequestMethod> = (
  input: RequestInput<M>
) => Effect.Effect<RequestOutput<M>, IpcError, ClientServices>;

export type Handlers = { readonly [M in RequestMethod]: Handler<M> };

type Failure = { readonly _tag: string; readonly message: string };

const connection = (hostKey: string) => HostDirectory.use((dir) => dir.connection(hostKey));

const onHost = <A, E extends Failure>(
  hostKey: string,
  use: (connection: HostConnection) => Effect.Effect<A, E>
) => Effect.flatMap(connection(hostKey), use).pipe(Effect.mapError(toIpcError));

const onLive = <A, E extends Failure>(
  hostKey: string,
  use: (session: LiveSession) => Effect.Effect<A, E>
) => onHost(hostKey, (c) => Effect.flatMap(c.session, use));

const machines = <A, E extends Failure>(use: (m: Machines["Service"]) => Effect.Effect<A, E>) =>
  Machines.use(use).pipe(Effect.mapError(toIpcError));

const done = <E, R>(effect: Effect.Effect<unknown, E, R>) => Effect.as(effect, null);

const fileContent = (session: LiveSession, content: FileContent) =>
  Match.value(content).pipe(
    Match.tagsExhaustive({
      Inline: ({ text }) => Effect.succeed<FileContentView>({ kind: "text", text }),
      Blob: ({ blobId }) =>
        Effect.map(session.blobs.take(blobId), (bytes): FileContentView => ({
          kind: "bytes",
          bytes,
        })),
    })
  );

const plainVersion = (v: FileVersion): FileVersionView => ({
  mtimeMs: v.mtimeMs,
  size: v.size,
  hash: v.hash,
});

const local = (): InstallView => ({
  result: "Local",
  platform: null,
  version: null,
  sha256: null,
  command: null,
});

export const requestHandlers = (ctx: RequestContext): Handlers => ({
  "prediction.discoveryShown": () =>
    Effect.sync(() => {
      ctx.predictionBridge?.discoveryShown();

      return null;
    }),
  "prediction.enabled.get": () =>
    Effect.sync(() => ctx.predictionBridge?.enabled() ?? { enabled: false, configured: false }),
  "prediction.enabled.set": ({ enabled }) =>
    ctx.predictionBridge
      ? Effect.sync(() => ctx.predictionBridge!.setEnabled(enabled))
      : Effect.fail({ code: "Unavailable", message: "Tab completion unavailable" }),
  "prediction.inspect": ({ hostKey }) =>
    Effect.tryPromise({
      try: async () => {
        if (!ctx.predictionBridge) throw new Error("Tab completion unavailable");

        return ctx.predictionBridge.inspect(hostKey);
      },
      catch: (error): IpcError => ({ code: "PredictionUnavailable", message: String(error) }),
    }),
  "prediction.server": (input) =>
    Effect.tryPromise({
      try: async () => {
        if (!ctx.predictionBridge) throw new Error("Tab completion unavailable");

        return ctx.predictionBridge.server(input);
      },
      catch: (error): IpcError => ({
        code: "PredictionUnavailable",
        message: error instanceof Error ? error.message : String(error),
      }),
    }),
  "prediction.release": ({ hostKey, workspaceId }) =>
    Effect.sync(() => {
      ctx.predictionBridge?.release(hostKey, workspaceId);

      return null;
    }),
  "prediction.clientEndpoints.get": () =>
    ctx.predictionSettings
      ? Effect.sync(() => ctx.predictionSettings!.getClientEndpoints())
      : Effect.fail({ code: "Unavailable", message: "Prediction settings unavailable" }),
  "prediction.clientEndpoints.set": ({ endpoints }) =>
    ctx.predictionSettings
      ? Effect.sync(() => {
          const saved = ctx.predictionSettings!.setClientEndpoints(endpoints);
          ctx.predictionPlacement?.invalidateAll();

          return saved;
        })
      : Effect.fail({ code: "Unavailable", message: "Prediction settings unavailable" }),
  "prediction.resources.get": () =>
    Effect.tryPromise({
      try: modelServerResources,
      catch: () => ({ code: "Unavailable", message: "Model server memory unavailable" }),
    }),
  "prediction.settings.get": ({ hostKey }) =>
    ctx.predictionSettings
      ? Effect.sync(() => ctx.predictionSettings!.get(hostKey))
      : Effect.fail({ code: "Unavailable", message: "Prediction settings unavailable" }),
  "prediction.settings.set": ({ hostKey, preferences }) =>
    ctx.predictionSettings
      ? Effect.sync(() => {
          const saved = ctx.predictionSettings!.set(hostKey, preferences);
