import {
  CommandId,
  CommandRejected,
  DomainEvent,
  type Attempt,
  type Constellation,
  type ResourceError,
  type ConstellationTransferError,
} from "@polaris/protocol";
import { Effect, Predicate, Stream } from "effect";
import type { ServiceError } from "../../services.ts";
import { Engine } from "../../engine/Engine.ts";
import { decideSession } from "../../engine/session.ts";
import { workerBrief } from "../../harness/constellation/index.ts";
import { EventStore } from "../../store/EventStore.ts";
import { ConstellationSessionEffects } from "../delivery/inputs.ts";
import { newTurn, startedTurn, waitForDeliveryReady } from "../delivery/turns.ts";
import { acceptedDependencyClaims, effectiveDeps } from "../parents.ts";
import { recoverAttempt } from "../recovery.ts";
import { mergeFirst, reviewFeedback } from "./feedback.ts";

export const startAttempt = Effect.fn("Constellation.startAttempt")(function* (
  graph: Constellation,
  attempt: Attempt
) {
  const store = yield* EventStore;
  const effects = yield* ConstellationSessionEffects;
  const task = graph.tasks.find((t) => t.id === attempt.taskId);

  if (task === undefined) return;

  if (!(yield* waitForDeliveryReady(attempt.sessionId))) return;
  // Reopen at the boundary so Existing and Gate Sessions retain their Lead attachment and gain Worker tools.
  yield* effects.retire(attempt.sessionId);
  const model = yield* store.model;
  const session = model.sessions.get(attempt.sessionId)?.session;

  if (session === undefined) return;

  const brief = workerBrief({
    constellationId: graph.id,
    workspaceId: graph.workspaceId,
    task,
    attempt,
    selection: session,
    permissionMode: session.permissionMode,
    ...reviewFeedback(graph, attempt),
    acceptedDeps: acceptedDependencyClaims(graph, effectiveDeps(graph.tasks, task.id)),
  });

  const prompt = [mergeFirst(attempt), brief].filter((text) => text !== "").join("\n\n");

  while (true) {
    const done = yield* Effect.scoped(
      Effect.uninterruptibleMask((restore) =>
        Effect.gen(function* () {
          const feed = yield* store.subscribe({ sessionId: attempt.sessionId });

          const result = yield* store
            .commit({
              recordRejection: false,
              commandId: CommandId.make(`${attempt.id}:start`),
              decide: (current) => {
                const record = current.sessions.get(attempt.sessionId);

                if (record === undefined) return Effect.succeed([]);
                const local = current.constellations.get(graph.id);

                if (
                  local !== undefined &&
                  !local.graph.attempts.some((a) => a.id === attempt.id && a.state === "working")
                )
                  return Effect.succeed([]);

                const decision = decideSession(record, {
                  type: "turn.send",
                  turn: newTurn(
                    record.session,
                    prompt,
                    new Date().toISOString(),
                    `${attempt.id}:start`
                  ),
                });

                if (decision.rejection !== null)
                  return Effect.fail(
                    new CommandRejected({
                      commandId: CommandId.make(`${attempt.id}:start`),
                      reason: "Worker startup is queued",
                    })
                  );

                return Effect.succeed([
                  DomainEvent.cases.SessionRenamed.make({
                    sessionId: attempt.sessionId,
                    title: `${task.id} · ${task.title}`,
                  }),
                  ...decision.events,
                ]);
              },
            })
            .pipe(
              Effect.catchTag("CommandRejected", () => Effect.succeed(null)),
              Effect.orDie
            );

          if (result === null) {
            yield* restore(feed.pipe(Stream.take(1), Stream.runDrain));

            return false;
          }

          if (Predicate.isTagged(result, "Committed")) {
            const turn = startedTurn(result.envelopes.map((e) => e.event));

            if (turn !== undefined) yield* effects.runTurn(turn, prompt);
          }

          return true;
        })
      )
    );

    if (done) return;
  }
});

export const resumeAttempt = Effect.fn("Constellation.resumeAttempt")(function* (attempt: Attempt) {
  const store = yield* EventStore;
  const model = yield* store.model;

  const graph = [...model.constellations.values()].find((r) =>
    r.graph.attempts.some((a) => a.id === attempt.id)
  )?.graph;

  if (graph !== undefined && (yield* startPendingAttempt(graph, attempt))) return;

  const engine = yield* Engine;
  const candidate = engine.recoveredTurns.find((c) => c.sessionId === attempt.sessionId);

  if (candidate !== undefined) yield* recoverAttempt(candidate);
});

/** A committed Attempt with no startup receipt must still start after a Daemon restart. */
export const startPendingAttempt = Effect.fn("Constellation.startPendingAttempt")(function* (
  graph: Constellation,
  attempt: Attempt
) {
  const store = yield* EventStore;
  const record = (yield* store.model).sessions.get(attempt.sessionId);

  if (yield* store.hasCommandReceipt(CommandId.make(`${attempt.id}:start`)).pipe(Effect.orDie))
    return false;

  if (!(yield* store.model).sessions.has(attempt.sessionId)) return false;

  yield* startAttempt(graph, attempt);

  return true;
});

export const workerFailed = (
  attempt: Attempt,
  error: ResourceError | ConstellationTransferError | ServiceError
) => Effect.logError(`Constellation worker ${attempt.id} startup needs attention`, error);

/**
 * The 32px breadcrumb row (DESIGN.md, Editor: breadcrumbs; Paper E1): the
 * path from the Workspace's root in `caption` `text-subtle`, the file and the
 * symbol at the cursor in `text-default`, and the "Ask about this file ⌘I" hint.
 */
import { Kbd } from "@polaris/ui";
import { Fragment, useMemo } from "react";
import { symbolAt } from "../cm/symbol.ts";
import { fileKey } from "../model/drafts.ts";
import { crumbs } from "../model/paths.ts";
import { useEditor } from "../runtime/store.ts";

export interface BreadcrumbsProps {
  readonly path: string;
  readonly root: string;
}

/** Inside the root: its relative segments; elsewhere (a Worktree, a checkout): from `~` or `/`. */
export const crumbs = (path: string, root: string): ReadonlyArray<string> => {
  const base = root.endsWith("/") ? root : `${root}/`;
  const relative = path.startsWith(base) ? path.slice(base.length) : path.replace(/^\/+/, "");

  return relative.split("/").filter((s) => s.length > 0);
};

const useSymbol = (path: string) => {
  const view = useEditor((s) => (s.active?.path === path ? s.active.view : null));
  const head = useEditor((s) => (s.active?.path === path ? s.cursor : null));

  const grammar = useEditor((s) =>
    s.active === null ? false : (s.buffers[fileKey(s.active.hostKey, path)]?.grammar ?? false)
  );

  return useMemo(
    () =>
      view === null || head === null || !grammar
        ? null
        : symbolAt(view.state, view.state.selection.main.head),
    [view, head, grammar]
  );
};

export const Breadcrumbs = ({ path, root }: BreadcrumbsProps) => {
  const parts = crumbs(path, root);
  const symbol = useSymbol(path);

  return (
    <div className="text-caption text-text-subtle flex h-8 shrink-0 items-center gap-1.5 pr-4 pl-5">
      <nav
        aria-label="Path"
        className="flex min-w-0 items-center gap-1.5 overflow-hidden whitespace-nowrap"
      >
        {parts.map((part, i) => (
          <Fragment key={`${i}-${part}`}>
            {i > 0 ? <span aria-hidden="true">/</span> : null}
            <span className={i === parts.length - 1 ? "text-text-default" : "truncate"}>
              {part}
            </span>
          </Fragment>
        ))}
        {symbol === null ? null : (
          <>
            <span aria-hidden="true">›</span>
            <span className="text-text-default truncate">{symbol}</span>
          </>
        )}
      </nav>
      <span className="flex-1" />
      <span className="flex shrink-0 items-center gap-1.5">
        Ask about this file
        <Kbd>⌘I</Kbd>
      </span>
    </div>
  );
};

/**
 * The explorer's state per Workspace: listings, open folders, Files or Changes,
 * git marks, and the row being created or renamed. Open folders and the view
 * persist per Workspace in localStorage; listings and git refetch on launch.
 */
import { useStore } from "zustand";
import { createStore } from "zustand/vanilla";
import type { GitMarks, StatusEntry } from "../model/git.ts";
import type { Listing } from "../model/tree.ts";

export type ExplorerView = "files" | "changes";

export interface GitFacts {
  /** The repository's top level: where git's paths start. */
  readonly toplevel: string;
  /** The top level is a linked worktree (its `.git` is a file). */
  readonly worktree: boolean;
  /** HEAD's commit; null before the first commit. The gutter's base. */
  readonly head: string | null;
  readonly branch: string | null;
  readonly ahead: number;
  readonly behind: number;
  /** The upstream and where Publish would push; null from a Daemon without `git.sync`. */
  readonly tracking: GitTracking | null;
  readonly marks: GitMarks;
  /** The raw entries, relative to `toplevel`: the Changes tab's Staged and Changes lists. */
  readonly entries: ReadonlyArray<StatusEntry>;
}

/** A row being typed into: a new file or folder in `dir`, or a rename of `path`. */
export type Draft =
  | { readonly kind: "create"; readonly dir: string; readonly entry: "file" | "directory" }
  | { readonly kind: "rename"; readonly path: string };

export interface WorkspaceExplorer {
  readonly view: ExplorerView;
  readonly expanded: ReadonlySet<string>;
  readonly listings: ReadonlyMap<string, Listing>;
  /** Null until known; "none" outside a git repository. */
  readonly git: GitFacts | "none" | null;
  readonly draft: Draft | null;
  /** The row with keyboard focus (a path), for ↑/↓ and the context actions. */
  readonly focused: string | null;
  /** A Worktree or Review Checkout the explorer shows instead of the Workspace's folder. */
  readonly root: string | null;
  /** A path asked to be shown (revealInExplorer), until the explorer has opened its way to it. */
  readonly reveal: string | null;
}

export const emptyExplorer: WorkspaceExplorer = {
  view: "files",
  expanded: new Set(),
  listings: new Map(),
  git: null,
  draft: null,
  focused: null,
  root: null,
  reveal: null,
};

export const explorerKey = (hostKey: string, workspaceId: string) =>
  `${hostKey}\u0000${workspaceId}`;

const STORAGE_KEY = "polaris.explorer.v1";

/** Workspaces whose open folders are remembered, most recent last. */
const KEPT = 40;

interface Saved {
  readonly view: ExplorerView;
  readonly expanded: ReadonlyArray<string>;
}

const storage = (): Storage | null => {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
};

const readSaved = (): Record<string, Saved> => {
  try {
    const raw = storage()?.getItem(STORAGE_KEY);

    // SAFETY: only this module writes the key, always as a record of Saved.
    return raw === null || raw === undefined ? {} : (JSON.parse(raw) as Record<string, Saved>);
  } catch {
    return {};
  }
};

const save = (key: string, value: WorkspaceExplorer) => {
  const saved = readSaved();

  delete saved[key];
  saved[key] = { view: value.view, expanded: [...value.expanded] };
  const kept = Object.entries(saved).slice(-KEPT);

  try {
    storage()?.setItem(STORAGE_KEY, JSON.stringify(Object.fromEntries(kept)));
  } catch {
    // Storage full or unavailable: the tree just opens closed next time.
  }
};

const explorers = createStore<Readonly<Record<string, WorkspaceExplorer>>>(() => ({}));

/** What a Workspace starts from, read once, so a render's snapshot is stable. */
const initial = new Map<string, WorkspaceExplorer>();

export const explorerOf = (key: string): WorkspaceExplorer => {
  const current = explorers.getState()[key] ?? initial.get(key);

  if (current !== undefined) return current;
  const saved = readSaved()[key];

  const first =
    saved === undefined
      ? emptyExplorer
      : { ...emptyExplorer, view: saved.view, expanded: new Set(saved.expanded) };

  initial.set(key, first);

  return first;
};

export const patchExplorer = (
  key: string,
  change: (current: WorkspaceExplorer) => Partial<WorkspaceExplorer>
) => {
  const current = explorerOf(key);
  const patch = change(current);
  const next = { ...current, ...patch };

  explorers.setState({ ...explorers.getState(), [key]: next });

  if (patch.view !== undefined || patch.expanded !== undefined) save(key, next);
};

export const setListing = (key: string, dir: string, listing: Listing) =>
  patchExplorer(key, (s) => ({ listings: new Map(s.listings).set(dir, listing) }));

export const toggleFolder = (key: string, dir: string, open?: boolean) =>
  patchExplorer(key, (s) => {
    const expanded = new Set(s.expanded);

    if (open ?? !expanded.has(dir)) expanded.add(dir);
    else expanded.delete(dir);

    return { expanded };
  });

/** Calls `listener` on every change to any Workspace's explorer (the gutter follows HEAD). */
export const subscribeExplorers = (listener: () => void) => explorers.subscribe(listener);

export const useExplorerState = (key: string): WorkspaceExplorer =>
  useStore(explorers, (all) => all[key] ?? explorerOf(key));

/** Tests only: forget every Workspace's state. */
export const resetExplorers = () => {
  initial.clear();
  explorers.setState({});
};

