/** The dialog's rows for what is typed: recent folders, the folder listed and its subfolders. */
import { useMemo } from "react";
import type { HostView } from "../../../shared/api.ts";
import { useApp } from "../../shell/hooks.ts";
import { browseOf, folderRows, listError, START, tilde } from "./model.ts";
import { readRecent } from "./recent.ts";
import { type Listing, useListing } from "./useListing.ts";

/** What a row does: open a folder as a Workspace, step into one, or ask the OS folder picker (the local Host). */
export type Target =
  | { readonly kind: "open"; readonly path: string }
  | { readonly kind: "folder"; readonly path: string }
  | { readonly kind: "finder" };

export interface Row {
  readonly id: string;
  readonly title: string;
  readonly meta: string | undefined;
  readonly target: Target;
  readonly testId: string;
}

export interface Group {
  readonly heading: string;
  readonly rows: ReadonlyArray<Row>;
}

interface RowsInput {
  readonly host: HostView;
  readonly typed: string;
  readonly listing: Listing;
  readonly workspaces: ReadonlyArray<{ readonly path: string; readonly name: string }>;
  readonly recent: ReadonlyArray<string>;
}

const listedGroup = ({ host, typed, listing, workspaces }: RowsInput): Group | null => {
  const homeDir = host.status.host?.homeDir ?? null;
  const { absolute, filter } = browseOf(typed, homeDir);

  if (absolute === null || listing.kind !== "listed") return null;

  const here = tilde(absolute, homeDir);
  const known = workspaces.find((w) => w.path === absolute);

  const open: Row = {
    id: `open\u0000${absolute}`,
    title: `Open ${here}`,
    target: { kind: "open", path: absolute },
    testId: "folder-open",
    meta: known === undefined ? undefined : `workspace ${known.name}`,
  };

  const folders = folderRows(listing.entries, filter, workspaces).map((row): Row => ({
    id: `dir\u0000${row.path}`,
    title: row.name,
    target: { kind: "folder", path: row.path },
    testId: "folder-row",
    meta: row.workspace === null ? undefined : "workspace",
  }));

  return { heading: here, rows: filter === "" ? [open, ...folders] : folders };
};

/** Pure: the groups for one state of the dialog. */
export const buildGroups = (input: RowsInput): ReadonlyArray<Group> => {
  const homeDir = input.host.status.host?.homeDir ?? null;

  const recent: Group | null =
    input.typed === START && input.recent.length > 0
      ? {
          heading: "Recent",
          rows: input.recent.map((path) => ({
            id: `recent\u0000${path}`,
            title: tilde(path, homeDir),
            target: { kind: "open", path },
            testId: "folder-recent",
            meta: undefined,
          })),
        }
      : null;

  const finder: Group | null =
    input.host.kind === "local"
      ? {
          heading: input.host.label,
          rows: [
            {
              id: "finder",
              title: clientCopy().chooseFolder,
              target: { kind: "finder" },
              testId: "folder-finder",
              meta: undefined,
            },
          ],
        }
      : null;

  return [recent, listedGroup(input), finder].filter((g): g is Group => g !== null);
};

/** The line when nothing is listed: still listing, can't list, or nothing matches. */
export const emptyLine = (typed: string, listing: Listing, homeDir: string | null): string => {
  const { dir, filter } = browseOf(typed, homeDir);

  if (listing.kind === "failed") return listError(listing.message, dir);

  if (listing.kind !== "listed") return "";

  return filter === "" ? `No folders in ${dir}` : `No folder in ${dir} matches ${filter}`;
};

export const useFolderRows = (host: HostView, typed: string) => {
  const homeDir = host.status.host?.homeDir ?? null;
  const listing = useListing(host.key, browseOf(typed, homeDir).absolute);
  const model = useApp((s) => s.hostModels[host.key]);

  return useMemo(() => {
    const workspaces = model === undefined ? [] : [...model.workspaces.values()];
    const recent = readRecent()[host.key] ?? [];
    const groups = buildGroups({ host, typed, listing, workspaces, recent });

    return {
      groups,
      empty: emptyLine(typed, listing, homeDir),
      byId: new Map(groups.flatMap((g) => g.rows.map((r) => [r.id, r.target]))),
    };
  }, [host, typed, listing, model, homeDir]);
};

/**
 * The explorer (Paper E1, DESIGN.md Editor): 264px on surface-sunken. The
 * Workspace header, Files / Changes, the tree, "Agents in {workspace}", and the
 * jump hint with the Workspace's counts.
 */
import type { Workspace } from "@polaris/protocol";
import {
  ChevronLeftIcon,
  cn,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  IconButton,
  Kbd,
  PlusIcon,
  SegmentedControl,
} from "@polaris/ui";
import { useEffect } from "react";
import type { HostView } from "../../../../../shared/api.ts";
import { homePath, plural } from "../../../../shell/copy.ts";
import { useApp, useShellActions } from "../../../../shell/hooks.ts";
import { activeSessions } from "../../../../routes/topBar.ts";
import { type Place, startDraft } from "../data/actions.ts";
import { type ExplorerView, patchExplorer } from "../data/store.ts";
import { useExplorer } from "../data/useExplorer.ts";
import { openFile, setAgentEdits, setAgentFiles, useEditorTabs } from "../../index.ts";
import { basename } from "../model/paths.ts";
import { AgentsIn } from "./AgentsIn.tsx";
import { ChangesList } from "./ChangesList.tsx";
import { GitPanel } from "./GitPanel.tsx";
import { Tree } from "./Tree.tsx";

export interface ExplorerProps {
  readonly host: HostView;
  readonly workspace: Workspace;
}

const canWriteGit = (host: HostView) =>
  host.status.state === "connected" && host.status.capabilities.includes("git.write");

const canManage = (host: HostView) =>
  host.status.state === "connected" && host.status.capabilities.includes("files.manage");

interface HeaderProps {
  readonly host: HostView;
  readonly workspace: Workspace;
  readonly place: Place;
  readonly override: boolean;
}

const Header = ({ host, workspace, place, override }: HeaderProps) => (
  <div className="flex min-w-0 flex-col gap-0.5">
    <div className="flex items-start justify-between gap-2">
      <h1 className="text-heading text-text-strong min-w-0 truncate" title={workspace.name}>
        {workspace.name}
      </h1>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <IconButton
            label="New file or folder"
            size="sm"
            disabled={!canManage(host)}
            icon={<PlusIcon size={16} />}
            className="text-text-subtle -mt-1 -mr-1.5"
            data-testid="explorer-new"
          />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem
            onSelect={() =>
              startDraft(place.key, { kind: "create", dir: place.root, entry: "file" })
            }
          >
            New file
          </DropdownMenuItem>
          <DropdownMenuItem
            onSelect={() =>
              startDraft(place.key, { kind: "create", dir: place.root, entry: "directory" })
            }
          >
            New folder
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
    <p
      className="text-caption text-text-subtle truncate"
      title={place.root}
      data-testid="explorer-where"
    >
      {/* A checkout's own folder name is what tells it apart; its full path is the tooltip. */}
      {host.label} ·{" "}
      {override ? basename(place.root) : homePath(place.root, host.status.host?.homeDir ?? null)}
    </p>
    {override ? (
      <button
        type="button"
        data-testid="explorer-back"
        onClick={() => patchExplorer(place.key, () => ({ root: null }))}
        className="text-caption text-text-subtle hover:text-text-default flex cursor-default items-center gap-1 self-start"
      >
        <ChevronLeftIcon size={12} />
        Back to {basename(workspace.path)}
      </button>
    ) : null}
  </div>
);

const Footer = ({ host, workspace }: ExplorerProps) => {
  const { openJump } = useShellActions();
  const model = useApp((s) => s.hostModels[host.key]);
  const sessions = model === undefined ? 0 : activeSessions(model, workspace.id).length;

  const worktrees =
    model === undefined
      ? 0
      : [...model.worktrees.values()].filter((w) => w.workspaceId === workspace.id && !w.isMain)
          .length;

  const counts = [
    sessions > 0 ? plural(sessions, "agent") : null,
    worktrees > 0 ? plural(worktrees, "worktree") : null,
  ]
    .filter((part) => part !== null)
    .join(" · ");

  return (
    <div className="border-hairline px-panel flex h-10 shrink-0 items-center gap-2 border-t">
      <button type="button" onClick={openJump} className="flex cursor-default items-center gap-2">
        <Kbd>K</Kbd>
        <span className="text-caption text-text-subtle">Jump</span>
      </button>
      <span className="flex-1" />
      <span className="text-caption text-text-subtle min-w-0 truncate">{counts}</span>
    </div>
  );
};

const gitState = (git: ReturnType<typeof useExplorer>["state"]["git"]) => {
  if (git === null) return "loading";

  return git === "none" ? "none" : "ready";
};

export const Explorer = ({ host, workspace }: ExplorerProps) => {
  const data = useExplorer(host.key, workspace.id, workspace.path);
  const tabs = useEditorTabs(host.key, workspace.id);

  const place: Place = {
    key: data.key,
    hostKey: host.key,
    workspaceId: workspace.id,
    root: data.root,
  };

  const changed = data.changes.length;

  // The tabs' dither and the Working strip (E3) both follow the agents' file changes.
  useEffect(() => {
    setAgentFiles(host.key, workspace.id, data.agents.editing);
    setAgentEdits(host.key, workspace.id, data.agents.edits);
  }, [host.key, workspace.id, data.agents]);

  const open = (path: string, pin: boolean) =>
    openFile({ hostKey: host.key, workspaceId: workspace.id, path, preview: !pin });

  const openChanges = useChangeOpener(place, data.state.git, open);
  const shownDiff = useShownDiff(host.key, workspace.id);

  return (
    <aside
      aria-label="Explorer"
      data-testid="explorer"
      className="border-hairline bg-surface-sunken flex w-[264px] shrink-0 flex-col border-r"
    >
      {/* E1's 12px at calm, stepping with the panel padding (rule/density-through-tokens). */}
      <div className="px-panel pt-panel flex flex-col gap-[calc(var(--spacing-panel)*0.75)] pb-[calc(var(--spacing-panel)*0.75)]">
        <Header
          host={host}
          workspace={workspace}
          place={place}
          override={data.state.root !== null}
        />
        <SegmentedControl<ExplorerView>
          aria-label="Files or changes"
          variant="fill"
          value={data.state.view}
          onValueChange={(view) => patchExplorer(data.key, () => ({ view }))}
          options={[
            { value: "files", label: "Files" },
            {
              value: "changes",
              label: "Changes",
              badge:
                changed === 0 ? undefined : (
                  <span className="text-micro text-text-subtle font-normal tabular-nums">
                    {changed}
                  </span>
                ),
            },
          ]}
        />
      </div>
      {/* Reconnecting or offline: the last known tree, dimmed (rule/remote-is-normal). */}
      <div
        className={cn(
          "flex min-h-0 flex-1 flex-col",
          host.status.state !== "connected" && "opacity-(--opacity-dimmed)"
        )}
      >
        {data.state.view === "files" ? (
          <Tree
            place={place}
            rows={data.rows}
            draft={data.state.draft}
            focused={data.state.focused}
            tabs={tabs}
            hostLabel={host.label}
            canManage={canManage(host)}
            onOpen={open}
          />
        ) : canWriteGit(host) && data.state.git !== null && data.state.git !== "none" ? (
          <GitPanel
            place={place}
            git={data.state.git}
            agents={data.agents}
            tabs={tabs}
            hostLabel={host.label}
            onOpen={open}
            onOpenChanges={openChanges}
            shownDiff={shownDiff}
          />
        ) : (
          <ChangesList
            rows={data.changes}
            active={selectedPath("head", shownDiff, tabs.active)}
            git={gitState(data.state.git)}
            onOpen={open}
            onOpenChanges={
              openChanges === null ? null : (path, pin) => openChanges("head", path, pin)
            }
          />
        )}
      </div>
      <AgentsIn hostKey={host.key} workspaceId={workspace.id} name={workspace.name} />
      <Footer host={host} workspace={workspace} />
    </aside>
  );
};

