/**
 * Handlers for `git.*`: status, diff, show, and the Changes tab's writes. The
 * transport mounts this layer next to the other partial handler layers.
 */
import {
  DiffFile,
  GitCommit,
  GitCommitItem,
  GitDiff,
  GitDiscard,
  GitError,
  GitShow,
  GitStage,
  GitStatus,
  GitStatusEntry,
  GitUnstage,
  GitWatch,
  NotFound,
} from "@polaris/protocol";
import { Cause, Effect, Queue, Stream } from "effect";
import { RpcGroup } from "effect/rpc";
import { BlobChannel } from "../services.ts";
import { ReadContent, toContent } from "../files/fs.ts";
import { generatedPaths } from "../reviewer/generated.ts";
import { computeDiff, DiffNotFound, type DiffResult } from "./diff.ts";
import { indexDiff } from "./diffIndex.ts";
import { showFile } from "./show.ts";
import { gitStatus } from "./status.ts";
import { commit, type CommitEvent, discardPaths, stagePaths, unstagePaths } from "./write.ts";

export class GitRpcs extends RpcGroup.make(
  GitStatus,
  GitDiff,
  GitShow,
  GitStage,
  GitUnstage,
  GitDiscard,
  GitCommit,
  GitWatch
) {}

const gitError = (cwd: string) => (cause: unknown) =>
  new GitError({ cwd, message: cause instanceof Error ? cause.message : String(cause) });

export const handleGitStatus = Effect.fn("git.status")(function* ({
  cwd,
  ignored,
}: typeof GitStatus.payloadSchema.Type) {
  const status = yield* Effect.tryPromise({
    try: () => gitStatus(cwd, { ignored: ignored === true }),
    catch: gitError(cwd),
  });

  return {
    ...status,
    entries: status.entries.map((entry) => new GitStatusEntry(entry)),
  };
});

/** The file index with each file's `generated` verdict; null where it couldn't be read. */
const indexWithGenerated = async (diff: DiffResult): Promise<ReadonlyArray<DiffFile>> => {
  const index = indexDiff(diff.bytes);

  const generated = await generatedPaths({
    root: diff.root,
    at: diff.rulesAt,
    repo: diff.root,
    paths: index.map((file) => file.path),
  }).catch(() => null);

  return index.map(
    (file) =>
      new DiffFile({
        path: file.path,
        oldPath: file.oldPath,
        status: file.status,
        offset: file.offset,
        length: file.length,
        additions: file.additions,
        deletions: file.deletions,
        binary: file.binary,
        generated: generated?.has(file.path) ?? null,
      })
  );
};

const notFoundOr = (cwd: string) => (cause: unknown) =>
  cause instanceof DiffNotFound
    ? new NotFound({ what: cause.what, id: cause.id })
    : gitError(cwd)(cause);

export const handleGitDiff = Effect.fn("git.diff")(function* ({
  cwd,
  spec,
}: typeof GitDiff.payloadSchema.Type) {
  const diff = yield* Effect.tryPromise({
    try: () => computeDiff(cwd, spec),
    catch: notFoundOr(cwd),
  });

  const fileIndex = yield* Effect.promise(() => indexWithGenerated(diff));
  const blobs = yield* BlobChannel;
  const blobId = yield* blobs.offer(diff.bytes);

  return { blobId, size: diff.bytes.byteLength, files: diff.files, fileIndex };
});

export const handleGitShow = Effect.fn("git.show")(function* ({
  cwd,
  revision,
  path,
}: typeof GitShow.payloadSchema.Type) {
  const file = yield* Effect.tryPromise({
    try: () => showFile(cwd, revision, path),
    catch: notFoundOr(cwd),
  });

  const content = toContent(file.mimeType, file.bytes);

  if (ReadContent.$is("Inline")(content)) {
    return { size: file.size, mimeType: file.mimeType, content };
  }

  const blobs = yield* BlobChannel;
  const blobId = yield* blobs.offer(file.bytes);

  return { size: file.size, mimeType: file.mimeType, content: { _tag: "Blob" as const, blobId } };
});

const pathsWith =
  (name: string, write: (cwd: string, paths: ReadonlyArray<string>) => Promise<void>) =>
  ({ cwd, paths }: typeof GitStage.payloadSchema.Type) =>
    Effect.tryPromise({ try: () => write(cwd, paths), catch: gitError(cwd) }).pipe(
      Effect.withSpan(name)
    );

export const handleGitStage = pathsWith("git.stage", stagePaths);

export const handleGitUnstage = pathsWith("git.unstage", unstagePaths);

export const handleGitDiscard = pathsWith("git.discard", discardPaths);

const commitItem = (event: CommitEvent): GitCommitItem => {
  if (event.kind === "output") return GitCommitItem.cases.Output.make({ text: event.text });

  if (event.kind === "committed") return GitCommitItem.cases.Committed.make({ head: event.head });

  return GitCommitItem.cases.Failed.make({ exitCode: event.exitCode });
};

/** The commit runs in a promise of its own, so closing the stream never stops git midway. */
export const handleGitCommit = ({ cwd, message }: typeof GitCommit.payloadSchema.Type) =>
  Stream.callback<GitCommitItem, GitError>((queue) =>
    Effect.sync(() => {
      commit(cwd, message, (event) => Queue.offerUnsafe(queue, commitItem(event))).then(
        () => Queue.endUnsafe(queue),
        (cause: unknown) => Queue.failCauseUnsafe(queue, Cause.fail(gitError(cwd)(cause)))
      );
    })
  );

/**
 * Requires `BlobChannel` per request: when the transport provides it per
 * connection through an RpcMiddleware, the handler picks that one up.
 */
export const GitRpcsLive = GitRpcs.toLayer({
  "git.status": handleGitStatus,
  "git.diff": handleGitDiff,
  "git.show": handleGitShow,
  "git.stage": handleGitStage,
  "git.unstage": handleGitUnstage,
  "git.discard": handleGitDiscard,
  "git.commit": handleGitCommit,
  "git.watch": ({ cwd }) => watchGit(cwd),
});

/**
 * The Reviewer's prompts (ENG-222): what it may do, the change and why it was
 * made, the repo's instructions, the Rules' Findings (so it neither repeats
 * them nor misses them), the diff, and the output contract.
 */
import type { RiskFinding } from "@polaris/protocol";
import { changedFilesSection, diffSection } from "./changedFiles.ts";
import type { ChangeDiff } from "./diff.ts";
import { reviewerOutputJsonSchema } from "./output.ts";
import type { ReviewerShell } from "./policy.ts";

export { REVIEWER_MARKER } from "./markers.ts";

export interface ReviewPromptInput {
  /** "Pull request #12: Title", or the Agent Session's title. */
  readonly subject: string;
  /** The PR description, or the session's prompts in order. */
  readonly why: string | null;
  readonly instructions: string | null;
  readonly ruleFindings: ReadonlyArray<RiskFinding>;
  readonly diff: ChangeDiff;
  /** Generated files and lockfiles: listed, their patches left out. */
  readonly generated: ReadonlySet<string>;
  readonly base: string;
  readonly head: string;
  /** Set for "only the new changes": the head the previous Risk Summary covered. */
  readonly since: string | null;
  /** Findings already open on this Review (an incremental run), so they aren't repeated. */
  readonly earlierFindings: ReadonlyArray<RiskFinding>;
  /** What the Reviewer may run here (see `reviewerShell`). */
  readonly shell: ReviewerShell;
}

const lines = (finding: RiskFinding) =>
  finding.lines.start === finding.lines.end
    ? `${finding.lines.start}`
    : `${finding.lines.start}-${finding.lines.end}`;

const findingLine = (finding: RiskFinding) =>
  `- [${finding.id}] ${finding.severity} · ${finding.path}:${lines(finding)}${
    finding.lines.side === "old" ? " (removed)" : ""
  } · ${finding.title}`;

const CONTRACT = (schema: string) =>
  [
    "## Your reply",
    "End your final message with exactly one fenced ```json block holding a document that matches this JSON Schema; nothing after it. Polaris reads only that block.",
    "",
    "```json",
    schema,
    "```",
    "",
    '- `startLine`/`endLine` are 1-based line numbers in the file at head (`side: "new"`), or at base for removed lines (`side: "old"`), and must fall inside a hunk of the diff. Findings elsewhere are dropped.',
    "- Severity: critical = secrets, security, data loss; high = likely bug or breaking change; medium = worth a look; low = nits.",
    "- `confidence` is 0 to 1: how sure you are this is a real problem.",
    "- Report risks, not praise or summaries. An empty `findings` array is a fine answer.",
  ].join("\n");

const NO_CHECKS =
  "On this Host the repo's tests, lint and typecheck can't be kept off the network, so they are refused too: judge from reading the code.";

const NO_SHELL =
  "On this Host you have no shell: no git, tests, lint or typecheck. Read and search the files in this checkout (they are at head); where the diff below is cut short, read the changed files whole.";

const RULES = [
  "You are Polaris's Reviewer: a careful senior engineer reviewing a change for risks.",
  "You are read-only. You may read and search files, run `git diff`, `git log`, `git show` and similar read-only git commands, and run the repo's tests, lint and typecheck. You can't edit files, and you have no network. Anything else is refused.",
  "Work in this checkout; read whole files where the diff alone doesn't show enough.",
].join("\n");

export const reviewPrompt = (input: ReviewPromptInput): string => {
  const rules = { checks: RULES, git: `${RULES}\n${NO_CHECKS}`, none: `${RULES}\n${NO_SHELL}` };
  const sections = [REVIEWER_MARKER, rules[input.shell]];

  if (input.diff.files.length > 0) sections.push(changedFilesSection(input.diff, input.generated));

  sections.push(`## The change\n\n${input.subject}`);

  if (input.why !== null && input.why.trim() !== "") {
    sections.push(`## Why it was made\n\n${input.why.trim()}`);
  }

  if (input.instructions !== null) {
    sections.push(`## The repo's review instructions\n\n${input.instructions}`);
  }

  if (input.since !== null) {
    sections.push(
      `## Only the new changes\n\nYou reviewed this change before, at ${input.since}. The diff below holds only what changed since then.` +
        (input.earlierFindings.length > 0
          ? ` Your earlier Findings, still open (don't report them again):\n\n${input.earlierFindings.map(findingLine).join("\n")}`
          : "")
    );
  }

  if (input.ruleFindings.length > 0) {
    sections.push(
      `## Already reported by the rules (don't repeat these)\n\n${input.ruleFindings.map(findingLine).join("\n")}`
    );
  }

  sections.push(
    input.diff.files.length > 0
      ? diffSection(input.diff, input.generated, input.base, input.head)
      : "## The diff\n\nNo file changed.",
    CONTRACT(reviewerOutputJsonSchema())
  );

  return sections.join("\n\n");
};

export interface FollowUpInput {
  readonly question: string;
  /** The Finding asked about; null for a question about the whole change. */
  readonly finding: RiskFinding | null;
}

/** A follow-up in the Reviewer's own session, which already holds the review. */
export const followUpPrompt = (input: FollowUpInput): string =>
  [
    REVIEWER_MARKER,
    input.finding === null
      ? "A question about this change:"
      : `A question about your Finding:\n\n${findingLine(input.finding)}\n\n${input.finding.reason}`,
    "",
    input.question.trim(),
    "",
    "Answer in `answer`. If the answer changes your review, add Findings in `findings`, correct earlier ones in `revised` (by `findingId`), or withdraw wrong ones in `withdrawn`; otherwise leave those empty.",
    "",
    CONTRACT(reviewerOutputJsonSchema()),
  ].join("\n");

/** Sent once when a reply doesn't decode. */
export const repairPrompt = (problem: string): string =>
  [
    REVIEWER_MARKER,
    "Your last reply couldn't be read:",
    "",
    problem,
    "",
    "Send the same review again as exactly one fenced ```json block matching the schema, and nothing else.",
  ].join("\n");

import { hostname } from "node:os";
import { CapabilityProbe } from "@polaris/client/prediction/probe";
import type { PredictionTarget } from "@polaris/client/prediction";
import { countTokens } from "@polaris/predict";
import {
  PredictionError,
  PredictionRequest,
  PredictionFormat,
  PredictionStreamItem,
  type PredictionContext,
  type PredictionServerReport,
} from "@polaris/protocol";
import { Effect, ManagedRuntime, Predicate, Queue, Schema, Stream, type Layer } from "effect";
import { HostDirectory, LOCAL_HOST_KEY, type ClientRuntime } from "../hosts.ts";
import type { Settings } from "../settings.ts";
import {
  PredictionFeedItem,
  type PredictionCompletionInput,
  type PredictionContextSummary,
  type PredictionInspection,
  type PredictionUiInputs,
} from "../../shared/predictionContract.ts";
import type { IpcError } from "../../shared/api.ts";
import type { MainPredictionPlacement } from "./placement.ts";
import type { PredictionSettings } from "./preferences.ts";
import { LocalPredictor } from "./localPredictor.ts";

export interface PredictionBridgePorts {
  readonly localLayer?: Layer.Layer<LocalPredictor>;
  readonly probe?: Pick<CapabilityProbe, "get">;
  readonly runtime: ClientRuntime;
  readonly placement: MainPredictionPlacement;
  readonly preferences: PredictionSettings;
  readonly read: () => Settings;
  readonly commit: (settings: Settings) => void;
}

type Final = typeof PredictionFeedItem.cases.Final.Type;

type PredictionServerInput = (typeof PredictionUiInputs)["prediction.server"]["Type"];

/** An older Daemon can't say which server it reaches, so it offers no recovery. */
const UNKNOWN_SERVER: PredictionServerReport = { kind: "unknown", actions: [], outcome: null };

const contextSummary = (context: PredictionContext): PredictionContextSummary => ({
  pieces: context.length,
  languageServer: context.filter(
    (piece) => piece.kind === "definition" || piece.kind === "diagnostic"
  ).length,
  tokens: context.reduce((sum, piece) => sum + countTokens(`${piece.source}\n${piece.text}\n`), 0),
});

/** One LocalPredictor Layer per main process, shared by all completion subscriptions. */
export const createPredictionBridge = (ports: PredictionBridgePorts) => {
  const local = ManagedRuntime.make(ports.localLayer ?? LocalPredictor.layer);
  const probe = ports.probe ?? new CapabilityProbe();

  const enabled = () => ({
    enabled: ports.read().predictionEnabled ?? false,
    configured: ports.read().predictionConfigured ?? false,
  });

  const setEnabled = (value: boolean) => {
    ports.placement.invalidateAll();
    ports.commit({ ...ports.read(), predictionEnabled: value, predictionConfigured: true });

    return enabled();
  };

  const hostSession = Effect.fn("prediction.hostSession")(function* (hostKey: string) {
    const directory = yield* HostDirectory;
    const connection = yield* directory.connection(hostKey);

    return yield* connection.session;
  });

  const labels = (hostKey: string) =>
    ports.runtime.runPromise(
      Effect.gen(function* () {
        const directory = yield* HostDirectory;
        // The local Host's own name ("This Mac"), never the network hostname.
        const clientLabel = directory.entry(LOCAL_HOST_KEY)?.label ?? hostname();

        return {
          clientLabel,
          hostLabel:
            directory.entry(hostKey)?.label ?? (hostKey === LOCAL_HOST_KEY ? clientLabel : hostKey),
        };
      })
    );

  const inspect = async (hostKey: string): Promise<PredictionInspection> => {
    const [names, client, host] = await Promise.all([
      labels(hostKey),
      probe.get(
        ports.preferences.getClientEndpoints().map((endpoint) => ({ ...endpoint, models: [] }))
      ),
      ports.runtime
        .runPromise(
          Effect.flatMap(hostSession(hostKey), (session) =>
            session.capabilities.includes("prediction.capability")
              ? session.client["prediction.capability"]({
                  endpoints: ports.preferences
                    .get(hostKey)
                    .hostEndpoints.map((endpoint) => endpoint.url),
                })
              : Effect.succeed(null)
          )
        )
        .catch(() => null),
    ]);

    const found = [...client.endpoints, ...(host?.endpoints ?? [])].some(
      (endpoint) => endpoint.models.length > 0
    );

    const offer = found && !enabled().configured && !ports.read().predictionDiscoveryShown;

    return { ...names, client, host, offer };
  };

  const withLatency = (hostKey: string, result: Final): Final =>
    result.side === undefined || result.endpoint === undefined
      ? result
      : { ...result, latency: ports.placement.latency(hostKey, result.side, result.endpoint) };

  /** The model server behind an endpoint, asked on the side that owns it. */
  const server = async (input: PredictionServerInput): Promise<PredictionServerReport> => {
    const request = { endpoint: input.endpoint, model: input.model, action: input.action };

    if (input.side === "client") {
      const module = await import("@polaris/client/prediction/server");

      return module.runServerAction(request);
    }

    return ports.runtime.runPromise(
      Effect.flatMap(hostSession(input.hostKey), (session) =>
        session.capabilities.includes("prediction.server")
          ? session.client["prediction.server"](request)
          : Effect.succeed(UNKNOWN_SERVER)
      )
    );
  };

  const complete = (input: PredictionCompletionInput) =>
    Stream.callback<PredictionFeedItem, IpcError>(
      Effect.fn("prediction.bridge.complete")(function* (queue) {
        const started = performance.now();
        const timings: Record<string, number> = {};

        if (input.dispatchedAt !== undefined)
          timings.ipc = Math.max(0, performance.timeOrigin + started - input.dispatchedAt);

        const mark = (stage: string) => {
          timings[stage] = performance.now() - started;
        };

        const controller = new AbortController();
        yield* Effect.addFinalizer(() => Effect.sync(() => controller.abort()));

        const serve = async (target: PredictionTarget, signal: AbortSignal) => {
          delete timings.firstToken;
          delete timings.prompt;
          delete timings.final;
          mark("placement");
          Queue.offerUnsafe(queue, PredictionFeedItem.cases.Reset.make({}));

          if (input.cursor > input.buffer.length)
            throw new PredictionError({
              reason: "invalid-request",
              message: "Cursor is outside the buffer",
            });

          const session = await ports.runtime.runPromise(hostSession(input.hostKey), { signal });

          const context = session.capabilities.includes("prediction.context")
            ? await ports.runtime.runPromise(session.client["prediction.context"](input), {
                signal,
              })
            : [];

          mark("context");

          const summary = session.capabilities.includes("prediction.context")
            ? contextSummary(context)
            : null;

          const request = PredictionRequest.make({
            context,
            path: input.path,
            prefix: input.buffer.slice(0, input.cursor).split("\n").slice(-121).join("\n"),
            suffix: input.buffer.slice(input.cursor).split("\n").slice(0, 41).join("\n"),
            model: target.model,
            format: Schema.decodeUnknownSync(PredictionFormat)(target.format),
            endpoint: target.endpoint,
            budgetTokens: input.budgetTokens,
            maxTokens: 128,
            maxLines: 8,
          });

          const names = await labels(input.hostKey);
          const predictorStart = performance.now() - started;
          let final: typeof PredictionStreamItem.cases.Final.Type | null = null;

          const receive = (item: PredictionStreamItem) => {
            if (Predicate.isTagged(item, "Final")) {
              final = item;
              mark("final");
            } else {
              if (timings.firstToken === undefined) mark("firstToken");
              Queue.offerUnsafe(queue, PredictionFeedItem.cases.Delta.make({ text: item.text }));
            }
          };

          if (target.side === "client") {
            await local.runPromise(
              LocalPredictor.use((predictor) =>
                predictor
                  .complete(request, {
                    signal,
                    onTiming: (stage, elapsed) => {
                      timings[stage] = predictorStart + elapsed;
                    },
                  })
                  .pipe(Stream.runForEach((item) => Effect.sync(() => receive(item))))
              ),
              { signal }
            );
          } else {
            if (!session.capabilities.includes("prediction.complete"))
              throw new PredictionError({
                reason: "unavailable",
                message: "Host cannot serve completion",
              });
            await ports.runtime.runPromise(
              session.client["prediction.complete"](request).pipe(
                Stream.runForEach((item) => Effect.sync(() => receive(item)))
              ),
              { signal }
            );
          }
          // SAFETY: receive runs synchronously for every consumed stream item before runPromise resolves.

          const result = final as typeof PredictionStreamItem.cases.Final.Type | null;

          if (result === null)
            throw new PredictionError({
              reason: "invalid-response",
              message: "Prediction ended without a final result",
            });

          return PredictionFeedItem.cases.Final.make({
            text: result.text,
            timings: { ...timings },
            elapsedMs: result.elapsedMs,
            model: target.model,
            machine: target.side === "client" ? names.clientLabel : names.hostLabel,
            side: target.side,
            endpoint: { kind: target.endpoint.kind, url: target.endpoint.url },
            context: summary,
          });
        };

        const run = Effect.tryPromise({
          try: async () => {
            if (!enabled().enabled) throw new Error("Tab completion is off");

            const result = await ports.placement.run(
              input.hostKey,
              input.workspaceId,
              serve,
              controller.signal
            );

            // Placement records this round trip after serve returns, so latency is read here.
            Queue.offerUnsafe(queue, withLatency(input.hostKey, result));
            Queue.endUnsafe(queue);
          },
          catch: (error): IpcError => ({ code: "PredictionUnavailable", message: String(error) }),
        });

        yield* Effect.forkScoped(run.pipe(Effect.catch((error) => Queue.fail(queue, error))));
      })
    );

  const edits = createEditBridge({ ports, local, hostSession, labels, enabled, contextSummary });

  return {
    ...edits,
    enabled,
    setEnabled,
    inspect,
    complete,
    server,
    discoveryShown: () => ports.commit({ ...ports.read(), predictionDiscoveryShown: true }),
    release: (hostKey: string, workspaceId: string) =>
      ports.placement.release(hostKey, workspaceId),
    dispose: () => {
      ports.placement.invalidateAll();

      return local.dispose();
    },
  };
};

export type PredictionBridge = ReturnType<typeof createPredictionBridge>;

import { PredictionCapabilityLive } from "../prediction/capability.ts";
/**
 * `polaris serve`: run the Daemon until SIGINT / SIGTERM.
 *
 * Handler layers from other Daemon modules are added to `daemonHandlers`
 * below as they land; `startServer` falls back to placeholders for the rest.
 */
import * as BunRuntime from "@effect/platform-bun/BunRuntime";
import { supportsTrash } from "../files/trash.ts";
import { type Capability, HARNESS_CATALOGUE } from "@polaris/protocol";
import { Effect, Layer } from "effect";
import { AcceptRpcsLive } from "../accept/AcceptRpcs.ts";
import { AttachmentRpcsLive } from "../attachments/AttachmentRpcs.ts";
import { AttachmentStoreLive } from "../attachments/AttachmentStore.ts";
import { ConstellationLiveness } from "../constellation/liveness.ts";
import { ConstellationHarness } from "../constellation/composition/attachments.ts";
import { lazyConstellationHandlers, lazyHostResources } from "./lazy.ts";
import { installDebugHooks } from "../debug.ts";
import { Engine } from "../engine/Engine.ts";
