export const serveProgram = Effect.scoped(
  Effect.gen(function* () {
    const startup = yield* Effect.acquireRelease(
      Effect.sync(() =>
        deadline("taking the upgrade hand-off", {
          ms: STARTUP_DEADLINE_MS,
          onExpire: exitStuck("startup"),
        })
      ),
      (armed) => Effect.sync(armed.clear)
    );

    yield* takeHandoff();

    // Adopt descriptors before the login-shell PATH probe or any handler starts a child.
    startup.phase("probing the login shell's PATH");

    if (!bench) process.env.PATH = userPath({ env: process.env });

    const server = yield* startServer({
      handlers: daemonHandlers,
      capabilities: daemonCapabilities,
      upgrades: true,
      onPhase: startup.phase,
    });

    startup.clear();

    // Return temporary startup allocations once every handler and listener is installed.
    yield* releaseMemory;

    yield* Effect.logInfo(`polaris Daemon listening on ${server.socketPath}`);

    return yield* Effect.never;
  })
).pipe(
  Effect.catchTag("DaemonAlreadyRunning", (error) =>
    Effect.sync(() => {
      process.stderr.write(`polaris serve: ${error.message}\n`);
      process.exit(SERVE_EXIT_ALREADY_RUNNING);
    })
  )
);

export const runServe = () => {
  installDebugHooks();
  armShutdownGrace();
  BunRuntime.runMain(serveProgram);
};

/**
 * A pull request in Review: its detail from GitHub, its diff from the Review Checkout
 * (checked out on first open where a Workspace holds the repository), and Viewed synced
 * with GitHub.
 */
import type { ReviewCheckoutBlocker } from "@polaris/protocol";
import { Match } from "effect";
import { useEffect } from "react";
import type { HostView } from "../../../../shared/api.ts";
import type { PullSubject } from "../../../routes/review.ts";
import { useApp } from "../../../shell/hooks.ts";
import { placeToOpen } from "../checkout/model/hosts.ts";
import { usePlaces } from "../checkout/useCheckout.ts";
import { checkoutMemory, repoName, useCheckoutMemory } from "../checkout/store.ts";
import { checkOutOnce } from "../data/autoCheckout.ts";
import { usePullDetail } from "../data/pullDetail.ts";
import { type CheckoutWait, pullSource, scopeSource } from "../data/source.ts";
import { useCommitScope } from "../overview/model/scope.ts";
import { useReviewDiff } from "../data/useReviewDiff.ts";
import { reviewSlots, subjectKey } from "../surface.ts";
import { type Placeholder, ReviewBody } from "./ReviewBody.tsx";
import { PullHeader } from "./SubjectHeader.tsx";

const labelOf = (hosts: ReadonlyArray<HostView>, hostKey: string) =>
  hosts.find((h) => h.key === hostKey)?.label ?? hostKey;

const blockerText = (blocker: ReviewCheckoutBlocker | undefined) =>
  blocker === undefined
    ? "Its host couldn’t fetch the pull request"
    : Match.value(blocker).pipe(
        Match.tagsExhaustive({
          FetchFailed: ({ message }) => message,
          ShallowClone: () => "This host’s clone is shallow: fetch its full history to review here",
          Dirty: () => "The checkout has local edits",
          LocalCommits: () => "The checkout has local commits",
          InUse: () => "A session or terminal is working in the checkout",
        })
      );

const placeholderOf = (wait: CheckoutWait, hosts: ReadonlyArray<HostView>): Placeholder => {
  if (wait.kind === "fetching") {
    return {
      title: `Checking out on ${labelOf(hosts, wait.hostKey)}`,
      fact: "Fetching the pull request with this host’s git credentials",
    };
  }

  if (wait.kind === "failed") {
    return {
      title: "The review checkout is blocked",
      fact: blockerText(wait.checkout.blocked?.blocker),
    };
  }

  return wait.hosts.length === 0
    ? {
        title: "No workspace has this repository",
        fact: "Open a folder with it on a host to check it out there",
      }
    : {
        title: "Waiting for a host",
        fact: `${labelOf(hosts, wait.hosts[0]?.hostKey ?? "")} checks it out once it’s connected`,
      };
};

export const PullReview = ({ subject }: { readonly subject: PullSubject }) => {
  const { pull } = subject;
  const detail = usePullDetail(pull);
  const models = useApp((s) => s.hostModels);
  const hosts = useApp((s) => s.hosts);
  const places = usePlaces(pull);
  const lastHost = useCheckoutMemory((s) => s.lastHost[repoName(pull.repo)] ?? null);
  const state = pullSource(pull, models, places, lastHost);
  const scope = useCommitScope(subjectKey(subject));
  const ready = state.kind === "ready" ? state.source : null;
  const diff = useReviewDiff(ready === null || scope === null ? ready : scopeSource(ready, scope));
  const loaded = detail.kind === "ok" ? detail.detail : null;
  const waitingForNone = state.kind === "waiting" && state.wait.kind === "none";

  useEffect(() => {
    // A merged or closed pull request, or one whose checkout was just removed, isn't checked out again.
    if (!waitingForNone || loaded === null || loaded.state !== "open") return;

    const connected = (key: string) =>
      hosts.some((h) => h.key === key && h.status.state === "connected");

    const place = placeToOpen(
      places,
      checkoutMemory.getState().lastHost[repoName(pull.repo)] ?? null,
      connected
    );

    if (place !== null) checkOutOnce(place, pull, loaded);
  }, [waitingForNone, loaded, places, hosts, pull]);

  const key = subjectKey(subject);

  const slotProps = {
    subject,
    checkout:
      state.kind === "ready" ? { hostKey: state.source.hostKey, checkout: state.checkout } : null,
  };

  const { CheckoutChip, PrimaryAction } = reviewSlots.current;
  const name = `${pull.repo.owner}/${pull.repo.name}`;
  const url = loaded?.url ?? pullUrlOf(pull);

  usePullCommands(pull.number, url);

  return (
    <section
      data-testid="pull-review"
      data-pull={pull.pullId ?? ""}
      className="flex min-h-0 flex-1 flex-col"
    >
      <PullHeader
        name={name}
        number={pull.number}
        detail={loaded}
        url={url}
        actions={
          <>
            <CheckoutChip {...slotProps} />
            <PrimaryAction {...slotProps} />
          </>
        }
      />
      <ReviewBody
        subjectKey={key}
        slotProps={slotProps}
        place={
          slotProps.checkout === null
            ? null
            : {
                hostKey: slotProps.checkout.hostKey,
                root: slotProps.checkout.checkout.path,
                workspaceId: slotProps.checkout.checkout.workspaceId,
              }
        }
        diff={diff}
        session={null}
        mergeBase={state.kind === "ready" ? state.checkout.mergeBase : null}
        pullViewed={
          scope !== null
            ? null
            : {
                pull: { repo: pull.repo, number: pull.number },
                pullId: loaded?.id ?? pull.pullId ?? "",
                files: loaded?.files ?? [],
              }
        }
        placeholder={state.kind === "waiting" ? placeholderOf(state.wait, hosts) : null}
      />
    </section>
  );
};

/**
 * The Reviewer's prompts (ENG-222): what it may do, the change and why it was
 * made, the repo's instructions, the Rules' Findings (so it neither repeats
 * them nor misses them), the diff, and the output contract.
 */
import type { RiskFinding } from "@polaris/protocol";
import { changedFilesSection, diffSection } from "./changedFiles.ts";
import type { ChangeDiff } from "./diff.ts";
import { reviewerOutputJsonSchema } from "./output.ts";

/** Marks a Reviewer prompt; the bench Harness answers it with schema output. */
export const REVIEWER_MARKER = "<!-- polaris:reviewer -->";

export interface ReviewPromptInput {
  /** "Pull request #12: Title", or the Agent Session's title. */
  readonly subject: string;
  /** The PR description, or the session's prompts in order. */
  readonly why: string | null;
  readonly instructions: string | null;
  readonly ruleFindings: ReadonlyArray<RiskFinding>;
  readonly diff: ChangeDiff;
  /** Generated files and lockfiles: listed, their patches left out. */
  readonly generated: ReadonlySet<string>;
  readonly base: string;
  readonly head: string;
  /** Set for "only the new changes": the head the previous Risk Summary covered. */
  readonly since: string | null;
  /** Findings already open on this Review (an incremental run), so they aren't repeated. */
  readonly earlierFindings: ReadonlyArray<RiskFinding>;
  /** What the Reviewer may run here (see `reviewerShell`). */
  readonly shell: ReviewerShell;
}

const lines = (finding: RiskFinding) =>
  finding.lines.start === finding.lines.end
    ? `${finding.lines.start}`
    : `${finding.lines.start}-${finding.lines.end}`;

const findingLine = (finding: RiskFinding) =>
  `- [${finding.id}] ${finding.severity} · ${finding.path}:${lines(finding)}${
    finding.lines.side === "old" ? " (removed)" : ""
  } · ${finding.title}`;

const CONTRACT = (schema: string) =>
  [
    "## Your reply",
    "End your final message with exactly one fenced ```json block holding a document that matches this JSON Schema; nothing after it. Polaris reads only that block.",
    "",
    "```json",
    schema,
    "```",
    "",
    '- `startLine`/`endLine` are 1-based line numbers in the file at head (`side: "new"`), or at base for removed lines (`side: "old"`), and must fall inside a hunk of the diff. Findings elsewhere are dropped.',
    "- Severity: critical = secrets, security, data loss; high = likely bug or breaking change; medium = worth a look; low = nits.",
    "- `confidence` is 0 to 1: how sure you are this is a real problem.",
    "- Report risks, not praise or summaries. An empty `findings` array is a fine answer.",
  ].join("\n");

const NO_CHECKS =
  "On this Host the repo's tests, lint and typecheck can't be kept off the network, so they are refused too: judge from reading the code.";

const NO_SHELL =
  "On this Host you have no shell: no git, tests, lint or typecheck. Read and search the files in this checkout (they are at head); where the diff below is cut short, read the changed files whole.";

const RULES = [
  "You are Polaris's Reviewer: a careful senior engineer reviewing a change for risks.",
  "You are read-only. You may read and search files, run `git diff`, `git log`, `git show` and similar read-only git commands, and run the repo's tests, lint and typecheck. You can't edit files, and you have no network. Anything else is refused.",
  "Work in this checkout; read whole files where the diff alone doesn't show enough.",
].join("\n");

export const reviewPrompt = (input: ReviewPromptInput): string => {
  const rules = { checks: RULES, git: `${RULES}\n${NO_CHECKS}`, none: `${RULES}\n${NO_SHELL}` };
  const sections = [REVIEWER_MARKER, rules[input.shell]];

  if (input.diff.files.length > 0) sections.push(changedFilesSection(input.diff, input.generated));

  sections.push(`## The change\n\n${input.subject}`);

  if (input.why !== null && input.why.trim() !== "") {
    sections.push(`## Why it was made\n\n${input.why.trim()}`);
  }

  if (input.instructions !== null) {
    sections.push(`## The repo's review instructions\n\n${input.instructions}`);
  }

  if (input.since !== null) {
    sections.push(
      `## Only the new changes\n\nYou reviewed this change before, at ${input.since}. The diff below holds only what changed since then.` +
        (input.earlierFindings.length > 0
          ? ` Your earlier Findings, still open (don't report them again):\n\n${input.earlierFindings.map(findingLine).join("\n")}`
          : "")
    );
  }

  if (input.ruleFindings.length > 0) {
    sections.push(
      `## Already reported by the rules (don't repeat these)\n\n${input.ruleFindings.map(findingLine).join("\n")}`
    );
  }

  sections.push(
    input.diff.files.length > 0
      ? diffSection(input.diff, input.generated, input.base, input.head)
      : "## The diff\n\nNo file changed.",
    CONTRACT(reviewerOutputJsonSchema())
  );

  return sections.join("\n\n");
};

export interface FollowUpInput {
  readonly question: string;
  /** The Finding asked about; null for a question about the whole change. */
  readonly finding: RiskFinding | null;
}

/** A follow-up in the Reviewer's own session, which already holds the review. */
export const followUpPrompt = (input: FollowUpInput): string =>
  [
    REVIEWER_MARKER,
    input.finding === null
      ? "A question about this change:"
      : `A question about your Finding:\n\n${findingLine(input.finding)}\n\n${input.finding.reason}`,
    "",
    input.question.trim(),
    "",
    "Answer in `answer`. If the answer changes your review, add Findings in `findings`, correct earlier ones in `revised` (by `findingId`), or withdraw wrong ones in `withdrawn`; otherwise leave those empty.",
    "",
    CONTRACT(reviewerOutputJsonSchema()),
  ].join("\n");

/** Sent once when a reply doesn't decode. */
export const repairPrompt = (problem: string): string =>
  [
    REVIEWER_MARKER,
    "Your last reply couldn't be read:",
    "",
    problem,
    "",
    "Send the same review again as exactly one fenced ```json block matching the schema, and nothing else.",
  ].join("\n");

/**
 * Byte transports a Client connects over: a child process's stdio (normally
 * `ssh <alias> polaris bridge`) or the local Daemon's Unix socket.
 *
 * Each transport can explain, after it failed, why: `diagnose` classifies the
 * exit status and stderr into a ConnectFailure the Connection State uses.
 */
import { spawn } from "node:child_process";
import { connect, type Socket } from "node:net";
import { type ByteTransport, readEvents, writeEvents } from "@polaris/protocol";
import { Deferred, Effect, Exit, Option, type Scope } from "effect";
import { ConnectFailure, classifyExit, type NeedsAttentionReason } from "./failures.ts";

export interface ClientTransport extends ByteTransport {
  /** Why the transport closed or failed; waits briefly for the process to exit. */
  readonly diagnose: Effect.Effect<ConnectFailure>;
}

/** How a HostConnection opens its transport. Injectable, so tests can replace `ssh`. */
export type Connector = Effect.Effect<ClientTransport, ConnectFailure, Scope.Scope>;

const STDERR_LIMIT = 16 * 1024;

const decoder = new TextDecoder();

export interface SpawnOptions {
  readonly env?: Record<string, string | undefined>;
  /** Grace period after stdin closes before the process is killed. */
  readonly killAfterMs?: number;
  /** Decodes stderr chunks; UTF-8 by default (wsl.exe mixes in UTF-16LE). */
  readonly stderrDecoder?: () => (chunk: Uint8Array) => string;
  /** Classifies the exit; `classifyExit` (ssh's messages) by default. */
  readonly classify?: (exit: {
    readonly code: number | null;
    readonly signal: string | null;
    readonly stderr: string;
  }) => ConnectFailure;
  /** The reason when the command itself can't be spawned; default by the command's name. */
  readonly spawnFailureReason?: NeedsAttentionReason;
}

/** Runs `argv` and speaks the wire over its stdin/stdout. */
export const spawnTransport = (
  argv: ReadonlyArray<string>,
  options: SpawnOptions = {}
): Connector =>
  Effect.gen(function* () {
    const [command, ...args] = argv;

    if (command === undefined) {
      return yield* new ConnectFailure({
        kind: "needs-attention",
        reason: "command-missing",
        detail: "empty command",
      });
    }

    const exited = yield* Deferred.make<{ code: number | null; signal: string | null }>();
    const decode = options.stderrDecoder?.() ?? ((chunk: Uint8Array) => decoder.decode(chunk));
    const classify = options.classify ?? classifyExit;
    let stderr = "";
    let spawnError: NodeJS.ErrnoException | null = null;
    // Set from the child's `error` event; read through a call so TypeScript doesn't narrow it.
    const startError = () => spawnError;

    const { child, incoming } = yield* Effect.acquireRelease(
      Effect.sync(() => {
        const child = spawn(command, args, {
          stdio: ["pipe", "pipe", "pipe"],
          env: options.env ?? process.env,
        });

        child.on("error", (error: NodeJS.ErrnoException) => {
          spawnError = error;
          Deferred.doneUnsafe(exited, Exit.succeed({ code: null, signal: null }));
        });
        // `exit`, not `close`: an SSH ControlPersist master may keep stderr open for minutes.
        child.on("exit", (code, signal) =>
          Deferred.doneUnsafe(exited, Exit.succeed({ code, signal }))
        );
        child.stderr?.on("data", (chunk: Uint8Array) => {
          stderr = (stderr + decode(chunk)).slice(-STDERR_LIMIT);
        });
        child.stdin?.on("error", () => {});

        // Attach the reader now, before any output can arrive.
        const incoming = child.stdout === null ? null : readEvents(child.stdout);

        return { child, incoming };
      }),
      ({ child }) =>
        Effect.gen(function* () {
          child.stdin?.end();

          const done = yield* Deferred.await(exited).pipe(
            Effect.timeoutOption(options.killAfterMs ?? 2000)
          );

          if (Option.isNone(done)) child.kill("SIGTERM");
          child.stderr?.destroy();
          child.stdout?.destroy();
        })
    );

    const stdin = child.stdin;

    if (stdin === null || incoming === null) {
      return yield* new ConnectFailure({
        kind: "transient",
        reason: "spawn-failed",
        detail: "no stdio pipes",
      });
    }

    const missingReason =
      options.spawnFailureReason ?? (command === "ssh" ? "ssh-missing" : "command-missing");

    // A spawn failure arrives on the next tick; wait for it so the attempt fails outright.
    yield* Effect.callback<void>((resume) => {
      setImmediate(() => resume(Effect.void));
    });

    const notStarted = startError();

    if (notStarted !== null) {
      return yield* new ConnectFailure({
        kind: "needs-attention",
        reason: missingReason,
        detail: `${command}: ${notStarted.code ?? notStarted.message}`,
      });
    }

    const diagnose = Deferred.await(exited).pipe(
      Effect.timeoutOption(3000),
      Effect.map((exit) => {
        const failed = startError();

        return failed !== null
          ? new ConnectFailure({
              kind: "needs-attention",
              reason: missingReason,
              detail: `${command}: ${failed.code ?? failed.message}`,
            })
          : classify({
              code: Option.isSome(exit) ? exit.value.code : null,
              signal: Option.isSome(exit) ? exit.value.signal : null,
              stderr,
            });
      })
    );

    return {
      incoming,
      write: writeEvents(stdin),
      close: Effect.sync(() => {
        stdin.end();
      }),
      diagnose,
    } satisfies ClientTransport;
  });

/**
 * Connects straight to a Daemon's Unix socket (the local Host). With
 * `installedHome`, a refusal says whether a Daemon is installed there and what its log says.
 */
export const socketTransport = (path: string, installedHome?: string): Connector =>
  Effect.gen(function* () {
    const { socket, incoming } = yield* Effect.acquireRelease(
      Effect.callback<
        { readonly socket: Socket; readonly incoming: ByteTransport["incoming"] },
        ConnectFailure
      >((resume) => {
        const socket = connect(path);

        const onError = (error: NodeJS.ErrnoException) =>
          resume(
            Effect.fail(
              error.code === "ENOENT" || error.code === "ECONNREFUSED"
                ? localDaemonFailure(path, installedHome)
                : new ConnectFailure({
                    kind: "transient",
                    reason: "connection-failed",
                    detail: `${path}: ${error.code ?? error.message}`,
                  })
            )
          );

        socket.once("error", onError);
        socket.once("connect", () => {
          socket.off("error", onError);
          socket.on("error", () => {});
          resume(Effect.succeed({ socket, incoming: readEvents(socket) }));
        });
      }),
      ({ socket }) => Effect.sync(() => socket.destroy())
    );

    return {
      incoming,
      write: writeEvents(socket),
      close: Effect.sync(() => {
        socket.end();
      }),
      diagnose: Effect.succeed(
        new ConnectFailure({
          kind: "transient",
          reason: "connection-lost",
          detail: `the Daemon closed ${path}`,
        })
      ),
    } satisfies ClientTransport;
  });

history.before:
? new ConnectFailure({
    kind: "needs-attention",
    reason: "daemon-not-running",
    detail: `no Daemon is listening on ${path}`,
  })

buffer:
/**
 * `Machines`: the Hosts in Settings. Adds and removes remote Hosts by
 * `~/.ssh/config` alias, runs each one's install flow (probe, one-time
 * approval, install or upgrade), switches the local Host, and publishes the
 * Settings rows. A background check (a reconnect) never installs.
 */
import { existsSync } from "node:fs";
import { installedPaths } from "@polaris/client";
import { HostAccess, type HostChannel } from "@polaris/client/access";
import {
  buildPlatformOf,
  type DownloadBuild,
  InstallPlan,
  type InstallTrigger,
} from "@polaris/client/install";
import { WslDiscovery } from "@polaris/client/wsl";
import {
  Context,
  Effect,
  Fiber,
  Layer,
  Option,
  Predicate,
  Queue,
  Schema,
  Stream,
  SubscriptionRef,
} from "effect";
import type { MachineView, SshAliasView, WslDistrosView } from "../../shared/api.ts";
import { clientCopy } from "../../shared/clientCopy.ts";
import { HostDirectory, LOCAL_HOST_KEY, localEntry, remoteEntry } from "../hosts.ts";
import { LocalHost, localTarget } from "../local/index.ts";
import type { RemoteHostSetting, Settings } from "../settings.ts";
import type { Approvals } from "./approvals.ts";
import type { DaemonBuilds } from "./builds.ts";
import { deliveryActivity } from "./delivery.ts";
import { type InstallEvent, initialInstall, stepInstall } from "./installFlow.ts";
import { channelActivity, unmanagedLocal, unsupportedMessage } from "./channels.ts";
import { applyWork, failureMessage, planFor, startDaemon } from "./remote.ts";
import { backgroundCheckKey, type InstallRecord, localUpgradeKey, machineViews } from "./views.ts";
import { type UpdateFacts, updatePolicy } from "./updateFacts.ts";
import { wslDistrosView } from "./wsl.ts";
import type { DaemonUpdateProgress, DaemonUpdateResult } from "../../shared/daemonUpdates.ts";

export class MachineError extends Schema.TaggedError<MachineError>()("MachineError", {
  message: Schema.String,
}) {}

export interface SettingsStore {
  readonly get: () => Settings;
  readonly update: (change: (settings: Settings) => Settings) => void;
}

export interface MachinesInput {
  readonly platform?: NodeJS.Platform | undefined;
  readonly settings: SettingsStore;
  readonly approvals: Approvals;
  readonly builds: DaemonBuilds;
  /** Downloads a build this app doesn't bundle, for a Host that can't download it itself. */
  readonly download?: DownloadBuild | undefined;
  /** Sent with downloads for the site's telemetry. */
  readonly clientVersion?: string | undefined;
  readonly aliases: () => ReadonlyArray<SshAliasView>;
  /** Opens a terminal window on this Client running `argv`. */
  readonly openTerminal: (argv: ReadonlyArray<string>) => Promise<void>;
  /** The WSL distros on this machine (Windows), for "Add a host". */
  readonly discoverWsl?: Effect.Effect<WslDiscovery>;
}

export interface AddMachine {
  /** Absent means ssh; "wsl" adds the distro named by `alias`. */
  readonly kind?: "ssh" | "wsl";
  readonly alias: string;
  readonly label: string;
  readonly colour: string | null;
  readonly forwardAgent: boolean;
}

export interface MachinePatch {
  readonly label?: string;
  readonly colour?: string | null;
  readonly forwardAgent?: boolean;
  readonly remoteCommand?: string | null;
}

type Failure = { readonly message: string };

const installsAnew = (plan: InstallPlan) =>
  Predicate.isTagged(plan, "NeedsApproval") || Predicate.isTagged(plan, "Install");

/** The build a connected Host runs (`linux-arm64-musl`), from its `hello`; null before one. */
const helloBuildPlatform = (host: HostInfo | null | undefined) =>
  host === null || host === undefined ? null : buildPlatformOf(host);

const fail = (message: string) => Effect.fail(new MachineError({ message }));

const asMachineError = (error: Failure) => new MachineError({ message: failureMessage(error) });

type MutableSetting = { -readonly [K in keyof RemoteHostSetting]: RemoteHostSetting[K] };

/** Applies a patch; a null colour or an empty remote command removes the setting. */
const patched = (remote: RemoteHostSetting, patch: MachinePatch): RemoteHostSetting => {
  const { remoteCommand, colour, ...rest } = { ...remote, ...patch };
  const next: MutableSetting = rest;
  const line = remoteCommand?.trim() ?? "";

  if (colour !== null && colour !== undefined) next.colour = colour;

  if (line !== "") next.remoteCommand = line;

  return next;
};

export class Machines extends Context.Service<
  Machines,
  {
    readonly views: SubscriptionRef.SubscriptionRef<ReadonlyArray<MachineView>>;
    readonly sshAliases: Effect.Effect<ReadonlyArray<SshAliasView>>;
    /** The WSL distros on this machine; `unsupported` off Windows. */
    readonly wslDistros: Effect.Effect<WslDistrosView>;
    readonly add: (input: AddMachine) => Effect.Effect<string, MachineError>;
    readonly update: (key: string, patch: MachinePatch) => Effect.Effect<void, MachineError>;
    readonly remove: (key: string) => Effect.Effect<void, MachineError>;
    /** The user asked: probe and plan, and install an approved build. */
    readonly check: (key: string) => Effect.Effect<void, MachineError>;
    readonly updateDaemon: (key: string) => Effect.Effect<void, MachineError>;
    readonly setKeepDaemonsUpToDate: (enabled: boolean) => Effect.Effect<void>;
    readonly setDaemonUpdateOverride: (
      key: string,
      enabled: boolean | null
    ) => Effect.Effect<void, MachineError>;
    readonly approve: (key: string, sha256: string) => Effect.Effect<void, MachineError>;
    readonly dismiss: (key: string) => Effect.Effect<void, MachineError>;
    readonly startDaemon: (key: string) => Effect.Effect<void, MachineError>;
    readonly setLocalEnabled: (enabled: boolean) => Effect.Effect<void, MachineError>;
    readonly openSsh: (key: string) => Effect.Effect<void, MachineError>;
  }
>()("polaris/desktop/Machines") {
  static readonly layer = (input: MachinesInput) => Layer.effect(Machines, makeMachines(input));
}

const makeMachines = Effect.fnUntraced(function* (input: MachinesInput) {
  const local = yield* LocalHost;

  /** The home of the installed Daemon serving the local Host, so it upgrades like a remote one. */
  const localHome = Effect.map(local.current, (daemon) =>
    Option.match(daemon, { onNone: () => null, onSome: (found) => found.installedHome })
  );

  const copy = clientCopy(input.platform);
  const dir = yield* HostDirectory;
  const access = yield* HostAccess;
  const scope = yield* Effect.scope;
  const installs = new Map<string, InstallRecord>();
  const work = new Map<string, Fiber.Fiber<void>>();
  const updates = new Map<string, UpdateFacts>();
  const progressChanges = yield* Queue.unbounded<void>();
  const views = yield* SubscriptionRef.make<ReadonlyArray<MachineView>>([]);
  let aliases = input.aliases();

  let bundledBuilds = yield* input.builds
    .forPlatform(null, { build: false, onBuild: Effect.void })
    .pipe(Effect.orElseSucceed(() => []));

  let bundled = bundledBuilds[0]?.version ?? null;

  const publish = Effect.gen(function* () {
    const hosts = yield* SubscriptionRef.get(dir.views);
    const home = yield* localHome;

    yield* SubscriptionRef.set(
      views,
      machineViews({
        settings: input.settings.get(),
        hosts,
        installs,
        aliases,
        updates,
        bundledVersion: bundled,
        bundledVersions: new Map(bundledBuilds.map((b) => [b.platform, b.version])),
        localManaged: home !== null,
        localSupported: local.supported,
        localLabel: local.label,
      })
    );
  });

  const remoteSetting = (key: string) =>
    (input.settings.get().hosts ?? []).find((h) => h.alias === key);

  const requireRemote = (key: string) => {
    const remote = remoteSetting(key);

    return remote === undefined ? fail(`no remote host "${key}"`) : Effect.succeed(remote);
  };

  /** The Host a key names: the local Host's Daemon, or a remote one from the settings. */
  const targetOf = (key: string) => {
    if (key !== LOCAL_HOST_KEY) return Effect.map(requireRemote(key), (r) => remoteEntry(r).target);

    if (!local.supported) return fail(copy.localHostUnsupported);

    return Effect.flatMap(local.current, (daemon) =>
      Option.match(daemon, {
        onNone: () => fail(unmanagedLocal(copy)),
        onSome: (found) => Effect.succeed(localTarget(found)),
      })
    );
  };

  /** How the Client acts on the Host: ssh, wsl.exe, or a local shell for this Mac's installed Daemon. */
  const channelFor = (key: string) =>
    targetOf(key).pipe(
      Effect.flatMap(access.channel),
      Effect.catchTag("HostActionUnsupported", (error) => fail(unsupportedMessage(error, copy)))
    );

  /** Waits for this Mac's Daemon to listen after an install or start. */
  const localListening = (home: string | null) =>
    home === null
      ? Effect.void
      : local
          .listening(home)
          .pipe(Effect.mapError((error) => new MachineError({ message: error.message })));

  const record = (key: string): InstallRecord =>
    installs.get(key) ?? { snapshot: initialInstall(), activity: null, offerSize: null };

  const step = (key: string, event: InstallEvent, activity: string | null = null) =>
    Effect.suspend(() => {
      const previous = record(key);
      const snapshot = stepInstall(previous.snapshot, event);

      if (snapshot === previous.snapshot) return Effect.succeed(snapshot);
      installs.set(key, { ...previous, snapshot, activity });

      return Effect.as(publish, snapshot);
    });

  const setRecord = (key: string, patch: Partial<InstallRecord>) =>
    Effect.suspend(() => {
      installs.set(key, { ...record(key), ...patch });

      return publish;
    });

  const updateFacts = (key: string, patch: Partial<UpdateFacts>) =>
    Effect.gen(function* () {
      const hosts = yield* SubscriptionRef.get(dir.views);
      const host = hosts.find((h) => h.key === key);
      const previous = updates.get(key);
      updates.set(key, {
        platform: helloBuildPlatform(host?.status.host),
        installedVersion: host?.status.host?.daemonVersion ?? null,
        bundledVersion: bundled,
        epoch: host?.status.epoch ?? 0,
        progress: null,
        lastUpdate: input.settings.get().daemonUpdates?.[key] ?? null,
        ...previous,
        ...patch,
      });
      yield* publish;
    });

  const finishUpdate = (key: string, result: DaemonUpdateResult) =>
    Effect.gen(function* () {
      input.settings.update((s) => ({
        ...s,
        daemonUpdates: { ...s.daemonUpdates, [key]: result },
      }));
      const progress = updates.get(key)?.progress;
      yield* updateFacts(key, {
        lastUpdate: result,
        installedVersion:
          result.problem === null ? result.version : (updates.get(key)?.installedVersion ?? null),
        progress: {
          stage: result.problem === null ? "done" : "failed",
          bytes: progress?.bytes ?? 0,
          total: progress?.total ?? 0,
        },
      });
    });

  const progress = (key: string) => (value: DaemonUpdateProgress) => {
    const previous = updates.get(key);

    if (previous === undefined) return;
    updates.set(key, { ...previous, progress: value });
    Queue.offerUnsafe(progressChanges, undefined);
  };

  yield* Stream.fromQueue(progressChanges).pipe(
    Stream.runForEach(() => publish),
    Effect.forkIn(scope)
  );

  const retryConnection = (key: string) =>
    dir.connection(key).pipe(
      Effect.flatMap((connection) => connection.retryNow),
      Effect.ignore
    );

  /** Runs `effect` as the Host's one piece of background work, replacing any before it. */
  const launch = (key: string, effect: Effect.Effect<void>) =>
    Effect.gen(function* () {
      const previous = work.get(key);

      if (previous !== undefined) yield* Fiber.interrupt(previous);
      work.set(key, yield* Effect.forkIn(effect, scope));
    });

  const finishCheck = (
    key: string,
    snapshot: import("./installFlow.ts").InstallSnapshot,
    installedVersion: string | null,
    bundledVersion: string | null,
    skipped: boolean
  ) =>
    Effect.gen(function* () {
      const problem = snapshot.context.problem;

      if (problem !== null) {
        yield* finishUpdate(key, {
          at: Date.now(),
          result: "failed",
          from: installedVersion,
          version: bundledVersion,
          problem: { ...problem, sshFailure: null },
        });
      } else if (snapshot.context.outcome !== null && !skipped) {
        yield* finishUpdate(key, {
          at: Date.now(),
          result: snapshot.context.outcome.kind === "newer" ? "newer" : "current",
          from: installedVersion,
          version: installedVersion,
          problem: null,
        });
      } else {
        yield* updateFacts(key, { progress: null });
      }
    });

  /** The flow after `check` moved to checking: plan, then maybe install. */
  const checkBody = (key: string, to: HostChannel, trigger: InstallTrigger, updateOnly = false) =>
    Effect.gen(function* () {
      const {
        platform,
        plan: proposed,
        size,
        installedVersion,
        bundledVersion,
      } = yield* planFor(to, {
        trigger,
        approved: to.trusted ? new Set<string>() : input.approvals.approved(key),
        builds: input.builds,
        onBuild: setRecord(key, { activity: "Building the daemon for this host from source" }),
      });

      bundledBuilds = yield* input.builds
        .forPlatform(null, { build: false, onBuild: Effect.void })
        .pipe(Effect.orElseSucceed(() => []));
      bundled = bundledBuilds[0]?.version ?? null;
      const hosts = yield* SubscriptionRef.get(dir.views);
      yield* updateFacts(key, {
        platform,
        installedVersion,
        bundledVersion,
        epoch: hosts.find((h) => h.key === key)?.status.epoch ?? 0,
      });

      const plan =
        trigger === "background" &&
        !updatePolicy(input.settings.get(), key).keepUpToDate &&
        Predicate.isTagged(proposed, "Upgrade")
          ? InstallPlan.UpToDate({ version: proposed.from })
          : proposed;

      if (updateOnly && installsAnew(plan)) {
        const message = to.trusted
          ? `${copy.localHost} has no daemon Polaris installed yet. Use Install first.`
          : "No daemon is installed. Use Install daemon first.";

        yield* step(key, { type: "failed", problem: { kind: "failed", message, command: null } });
        yield* finishUpdate(key, {
          at: Date.now(),
          result: "failed",
          from: installedVersion,
          version: bundledVersion,
          problem: { kind: "failed", message, command: null, sshFailure: null },
        });

        return;
      }

      yield* setRecord(key, { offerSize: size });

      const activity = deliveryActivity(plan, {
        host: to.alias,
        copying: channelActivity(to, copy).copying,
        platform: input.platform ?? process.platform,
      });

      const planned = yield* step(key, { type: "planned", plan, trusted: to.trusted }, activity);

      const pending = planned.value === "installing" ? planned.context.work : null;

      if (pending === null) {
        yield* finishCheck(key, planned, installedVersion, bundledVersion, proposed !== plan);

        return;
      }

      const outcome = yield* applyWork(to, pending, {
        progress: progress(key),
        download: input.download,
        clientVersion: input.clientVersion,
      });

      yield* localListening(to.home);

      yield* step(key, { type: "applied", outcome });
      yield* finishUpdate(key, {
        at: Date.now(),
        result: "updated",
        from: outcome.from,
        version: outcome.version,
        problem: null,
      });
      yield* retryConnection(key);
    }).pipe(
      Effect.catchTag("SshError", (error) =>
        step(key, {
          type: "failed",
          problem: { kind: "ssh", message: failureMessage(error), command: null },
        }).pipe(
          Effect.andThen(
            finishUpdate(key, {
              at: Date.now(),
              result: "failed",
              from: updates.get(key)?.installedVersion ?? null,
              version: updates.get(key)?.bundledVersion ?? bundled,
              problem: {
                kind: "ssh",
                message: failureMessage(error),
                command: null,
                sshFailure: error.failure,
              },
            })
          )
        )
      ),
      Effect.catch((error) =>
        step(key, {
          type: "failed",
          problem: { kind: "failed", message: failureMessage(error), command: null },
        }).pipe(
          Effect.andThen(
            finishUpdate(key, {
              at: Date.now(),
              result: "failed",
              from: updates.get(key)?.installedVersion ?? null,
              version: bundled,
              problem: {
                kind: "failed",
                message: failureMessage(error),
                command: null,
                sshFailure: null,
              },
            })
          )
        )
      ),
      Effect.asVoid
    );

  const runCheck = (key: string, to: HostChannel, trigger: InstallTrigger, updateOnly = false) =>
    Effect.gen(function* () {
      const previous = record(key).snapshot;

      const started = yield* step(
        key,
        { type: "check", trigger },
        channelActivity(to, copy).probing
      );

      if (started !== previous && started.value === "checking") {
        yield* updateFacts(key, { progress: { stage: "checking", bytes: 0, total: 0 } });
        yield* launch(key, checkBody(key, to, trigger, updateOnly));
      }
    });

  /** The user asked for a check (or an update only) of the Host `key`. */
  const userCheck = (key: string, updateOnly = false) =>
    Effect.flatMap(channelFor(key), (to) => runCheck(key, to, "user", updateOnly));

  // Background checks: once per occasion a Host's Connection State calls for one.
  const occasions = new Map<string, string>();
  let buildsOccasion = "";

  const background = (hosts: ReadonlyArray<import("../../shared/api.ts").HostView>) =>
    Effect.gen(function* () {
      const nextOccasion = hosts
        .map((h) => `${h.key}:${h.status.state}:${h.status.epoch}:${h.status.since}`)
        .join("|");

      if (buildsOccasion !== nextOccasion) {
        buildsOccasion = nextOccasion;
        bundledBuilds = yield* input.builds
          .forPlatform(null, { build: false, onBuild: Effect.void })
          .pipe(Effect.orElseSucceed(() => []));
        bundled = bundledBuilds[0]?.version ?? null;
      }

      yield* publish;

      for (const host of hosts) {
        if (host.key === LOCAL_HOST_KEY && !local.supported) continue;
        const policy = updatePolicy(input.settings.get(), host.key);
        const missing = host.status.failure?.reason === "polaris-not-installed";

        if (!policy.keepUpToDate && !missing) continue;

        const occasion =
          host.key === LOCAL_HOST_KEY
            ? localUpgradeKey(host, bundled, yield* localHome)
            : backgroundCheckKey(host, bundled);

        if (occasion === null) continue;
        const key = `${occasion}:${bundled}`;

        if (occasions.get(host.key) === key) continue;
        occasions.set(host.key, key);
        // A Host with no channel (a test socket Host) is never checked.
        yield* channelFor(host.key).pipe(
          Effect.flatMap((to) => runCheck(host.key, to, "background")),
          Effect.ignore
        );
      }
    });

  yield* SubscriptionRef.changes(dir.views).pipe(
    Stream.runForEach(background),
    Effect.forkIn(scope)
  );

  const add = (machine: AddMachine) =>
    Effect.gen(function* () {
      if (machine.alias === LOCAL_HOST_KEY) {
        return yield* fail(`Polaris names ${copy.machine} "local"; rename the alias to add it`);
      }

      if (remoteSetting(machine.alias) !== undefined) {
        return yield* fail(`${machine.alias} is already a host`);
      }

      const base: RemoteHostSetting = { alias: machine.alias, forwardAgent: machine.forwardAgent };

      const setting: RemoteHostSetting = patched(
        machine.kind === "wsl" ? { ...base, kind: "wsl" } : base,
        { label: machine.label.trim() || machine.alias, colour: machine.colour }
      );

      input.settings.update((s) => ({ ...s, hosts: [...(s.hosts ?? []), setting] }));
      // The user's check starts before the connection can ask for a background one.
      yield* userCheck(machine.alias);
      yield* dir.add(remoteEntry(setting));
      yield* publish;

      return machine.alias;
    });

  const update = (key: string, patch: MachinePatch) =>
    Effect.gen(function* () {
      const next = patched(yield* requireRemote(key), patch);
      input.settings.update((s) => ({
        ...s,
        hosts: (s.hosts ?? []).map((h) => (h.alias === key ? next : h)),
      }));
      yield* dir.add(remoteEntry(next));
      yield* publish;
    });

  const remove = (key: string) =>
    Effect.gen(function* () {
      yield* requireRemote(key);
      input.settings.update((s) => ({
        ...s,
        hosts: (s.hosts ?? []).filter((h) => h.alias !== key),
        daemonUpdates: Object.fromEntries(
          Object.entries(s.daemonUpdates ?? {}).filter(([alias]) => alias !== key)
        ),
      }));
      input.approvals.forget(key);
      const running = work.get(key);
      work.delete(key);

      if (running !== undefined) yield* Fiber.interrupt(running);
      installs.delete(key);
      updates.delete(key);
      occasions.delete(key);
      buildsOccasion = "";
      yield* dir.remove(key);
      yield* publish;
    });

  const approve = (key: string, sha256: string) =>
    Effect.gen(function* () {
      const offer = record(key).snapshot.context.offer;

      if (offer === null || offer.sha256 !== sha256) {
        return yield* fail("that build is no longer the one offered; check again");
      }

      const to = yield* channelFor(key);
      input.approvals.approve(key, { ...offer, approvedAt: Date.now() });
      const approved = yield* step(key, { type: "approve" }, channelActivity(to, copy).probing);

      if (approved.value === "checking") {
        yield* updateFacts(key, { progress: { stage: "checking", bytes: 0, total: 0 } });
        yield* launch(key, checkBody(key, to, "user"));
      }
    });

  /** Start daemon: `polaris install` with the installed build; on this Mac with none, install it. */
  const restart = (key: string) =>
    Effect.gen(function* () {
      const to = yield* channelFor(key);

      if (to.home !== null && !existsSync(installedPaths(to.home).binary)) {
        return yield* runCheck(key, to, "user");
      }

      yield* startDaemon(to).pipe(Effect.mapError(asMachineError));
      yield* localListening(to.home).pipe(Effect.ensuring(retryConnection(key)));
    });

  const setLocalEnabled = (enabled: boolean) =>
    Effect.gen(function* () {
      if (!local.supported) return yield* fail(copy.localHostUnsupported);
      input.settings.update((s) => ({ ...s, local: { ...s.local, enabled } }));

      if (!enabled) {
        yield* dir.remove(LOCAL_HOST_KEY);
      } else if (dir.entry(LOCAL_HOST_KEY) === undefined) {
        const daemon = yield* local.resolve.pipe(
          Effect.mapError(
            (error) =>
              new MachineError({ message: `the local daemon didn't start: ${error.message}` })
          )
        );

        yield* dir.add(localEntry(daemon, local.label));
      }

      occasions.delete(LOCAL_HOST_KEY);
      yield* Effect.flatMap(SubscriptionRef.get(dir.views), background);
      yield* publish;
    });

  const terminal = (argv: ReadonlyArray<string>) =>
    Effect.tryPromise({
      try: () => input.openTerminal(argv),
      catch: (cause) => new MachineError({ message: `Terminal didn't open: ${String(cause)}` }),
    });

  yield* publish;

  const setDaemonUpdateOverride = (key: string, enabled: boolean | null) =>
    Effect.gen(function* () {
      if (key === LOCAL_HOST_KEY && !local.supported) return yield* fail(copy.localHostUnsupported);

      if (key !== LOCAL_HOST_KEY) yield* requireRemote(key);
      input.settings.update((s) => {
        const override = <T extends { readonly keepDaemonUpToDate?: boolean }>(host: T) => {
          const { keepDaemonUpToDate: _previous, ...rest } = host;

          return enabled === null ? rest : { ...rest, keepDaemonUpToDate: enabled };
        };

        return key === LOCAL_HOST_KEY
          ? { ...s, local: override(s.local ?? { enabled: true }) }
          : { ...s, hosts: (s.hosts ?? []).map((h) => (h.alias === key ? override(h) : h)) };
      });
      occasions.delete(key);
      buildsOccasion = "";
      yield* Effect.flatMap(SubscriptionRef.get(dir.views), background);
      yield* publish;
    });

  return Machines.of({
    views,
    sshAliases: Effect.sync(() => {
      aliases = input.aliases();

      return aliases;
    }).pipe(Effect.tap(() => publish)),
    add,
    update,
    remove,
    check: (key) => userCheck(key),
    updateDaemon: (key) => userCheck(key, true),
    setKeepDaemonsUpToDate: (enabled) =>
      Effect.sync(() =>
        input.settings.update((s) => ({ ...s, keepDaemonsUpToDate: enabled }))
      ).pipe(
        Effect.andThen(
          Effect.sync(() => {
            occasions.clear();
            buildsOccasion = "";
          })
        ),
        Effect.andThen(Effect.flatMap(SubscriptionRef.get(dir.views), background)),
        Effect.andThen(publish)
      ),
    setDaemonUpdateOverride,
    approve,
    dismiss: (key) => Effect.asVoid(step(key, { type: "dismiss" })),
    startDaemon: restart,
    setLocalEnabled,
    wslDistros:
      input.discoverWsl === undefined
