    return { ok: true, value: { bytes: new TextEncoder().encode(PATCH), files: 3 } };

  if (method === "dispatch") return { ok: true, value: { sequence: null } };

  if (method === "usage.query") {
    const forSession = "sessionId" in input && input.sessionId !== null;

    return {
