};

/** Back and Forward run only with somewhere to go, so ⌃o/⌃i fall back to vim's own jumps. */
const canRun = (action: NavigationAction) => {
  if (action === "back") return editorLanguageQueries?.canGoBack() ?? false;

  if (action === "forward") return editorLanguageQueries?.canGoForward() ?? false;

  return true;
};

export const navigationContributions = (): readonly ContributedCommand[] =>
  LANGUAGE_NAVIGATION.map((command) => ({
    id: command.id,
    title: command.title,
    palette: {
      group: "file",
      detail: command.shortcut ?? "",
      keywords: ["language", command.action],
      followUp: command.followUp === true,
    },
    when: { all: command.anyFile === true ? ["editor.file"] : ["editor.file", "language.server"] },
    handler: {
      enabled: () => activeKey() !== null && canRun(command.action),
      run: () => {
        const key = activeKey();

        if (key !== null) runNavigation(key, command.action, editorLanguageQueries);
      },
    },
  }));

export const useLanguageNavigationCommands = () => {
  const registry = useCommands();

  useEffect(() => {
    const removeCommands = registry.contribute(navigationContributions());
    const unbindVim = bindVimCommands(registry.runAny);

    return () => {
      removeCommands();
      unbindVim();
    };
  }, [registry]);
};

#!/usr/bin/env bun
/**
 * The lint ratchet: oxlint with a committed baseline of existing violations.
 *
 *   bun tooling/lint/ratchet.ts [files…]                   fail on new or increased violations
 *   bun tooling/lint/ratchet.ts --update-baseline [files…]  also lower the baseline to what's left
 *   bun tooling/lint/ratchet.ts --rebaseline                record every current violation (new rules only)
 *
 * Without files it lints the whole repo. See packages/lint-config/README.md for the policy.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { isAbsolute, join, relative, resolve } from "node:path";
import { Schema } from "effect";
import {
  BaselineFile,
  type Counts,
  compare,
  countViolations,
  type Delta,
  tighten,
  type Violation,
} from "./baseline.ts";
import { LINTABLE, ROOT, runOxlint, toPosix } from "./oxlint.ts";

const BASELINE = join(ROOT, "tooling/lint/baseline.json");

const COMMENT =
  "Existing lint violations, per file and rule. `bun run lint` fails when a count goes up; `bun run lint:baseline` lowers them. Never raise a count by hand: fix the code. See packages/lint-config/README.md.";

const decodeBaseline = Schema.decodeUnknownSync(Schema.fromJsonString(BaselineFile));

const readBaseline = (): Counts =>
  existsSync(BASELINE) ? decodeBaseline(readFileSync(BASELINE, "utf8")).violations : {};

const writeBaseline = (violations: Counts) => {
  const file: BaselineFile = { $comment: COMMENT, violations };

  writeFileSync(BASELINE, `${JSON.stringify(file, null, 2)}\n`);
};

const toRepoPath = (file: string) =>
  relative(ROOT, isAbsolute(file) ? file : resolve(process.cwd(), file));

const describeDelta = (d: Delta, violations: ReadonlyArray<Violation>) => {
  const where = violations.flatMap((v) =>
    v.file === d.file && v.rule === d.rule
      ? [`    ${v.file}:${v.line}:${v.column}  ${v.message}`]
      : []
  );

  return [`  ${d.file}  ${d.rule}: ${d.current} (baseline ${d.baseline})`, ...where].join("\n");
};

const report = (regressions: ReadonlyArray<Delta>, violations: ReadonlyArray<Violation>) => {
  console.error(
    `Lint: ${regressions.length} new or increased violation(s). Fix them; don't raise the baseline.\n`
  );
  console.error(regressions.map((d) => describeDelta(d, violations)).join("\n\n"));
};

const main = () => {
  const args = process.argv.slice(2);
  const update = args.includes("--update-baseline");
  const requested = args.filter((a) => !a.startsWith("--")).map(toRepoPath);
  const files = requested.filter((f) => LINTABLE.test(f) && existsSync(join(ROOT, f)));

  if (requested.length > 0 && files.length === 0) return 0;

  const violations = runOxlint(files);
  const current = countViolations(violations);

  if (args.includes("--rebaseline")) {
    writeBaseline(current);
    console.log(`Recorded ${violations.length} violations in ${relative(ROOT, BASELINE)}.`);

    return 0;
  }

  const scope = files.length > 0 ? new Set(files) : null;
  const baseline = readBaseline();
  const { regressions, improvements } = compare(baseline, current, scope);

  if (update && improvements.length > 0) writeBaseline(tighten(baseline, current, scope));

  if (improvements.length > 0) {
    const fixed = improvements.reduce((n, d) => n + d.baseline - d.current, 0);

    const hint = update
      ? "Baseline lowered; commit it."
      : "Run `bun run lint:baseline` to lock it in.";

    console.log(`Lint: ${fixed} baselined violation(s) fixed. ${hint}`);
  }

  if (regressions.length === 0) return 0;

  report(regressions, violations);

  return 1;
};

process.exit(main());

import { sameProcessCohort } from "./keys.ts";
import { LanguageError } from "@polaris/protocol";
import { Schema } from "effect";
import { failure } from "../transport/framing.ts";
import { bounded } from "../transport/deadline.ts";
import { abortable } from "../install/validation.ts";
import { ProcessBudget, type ProcessReservation } from "./process-budget.ts";
import { deriveProcessLimit, hostProcessResources } from "./process-capacity.ts";
import type { BrokerOptions, Entry } from "./types.ts";
import type { LifecycleEvent } from "./lifecycle.ts";
import type { LaunchAdmissionRequest } from "./launchAdmission.ts";

/** One serialized Host admission lane; process teardown alone releases reservations. */
export function processAdmission(
  options: BrokerOptions,
  entries: Map<string, Entry>,
  move: (entry: Entry, event: LifecycleEvent) => void,
  shutdown: (entry: Entry, reason?: "no-demand" | "process-budget") => Promise<void>
) {
  const budget = new ProcessBudget(
    options.processLimit ?? deriveProcessLimit(hostProcessResources())
  );

  const recency = new WeakMap<Entry, number>();
  const waiting = new Map<Entry, AbortController>();
  const deadline = options.retirementDeadlineMs ?? 10000;
  let clock = 0;
  let tail: Promise<unknown> = Promise.resolve();

  const touch = (entry: Entry) => recency.set(entry, ++clock);
  const cancel = (entry: Entry) => waiting.get(entry)?.abort();

  const retire = (entry: Entry) => {
    cancel(entry);
    budget.retire(entry);
  };

  function idle(entry: Entry) {
    if (!budget.owns(entry) || !entry.lifecycle.can({ type: "evict" }) || entry.operations.size > 0)
      return false;

    return ![...entries.values()].some(
      (peer) => sameProcessCohort(peer, entry) && peer.documents.open.size > 0
    );
  }

  async function admit(entry: Entry, request: LaunchAdmissionRequest, signal: AbortSignal) {
    while (true) {
      if (signal.aborted || !request.isCurrent())
        throw failure("stale-generation", "Language process demand changed");

      if (budget.used < budget.limit) return budget.reserve(entry);

      const victim = [...entries.values()]
        .filter(idle)
        .toSorted((one, two) => (recency.get(one) ?? 0) - (recency.get(two) ?? 0))[0];

      if (victim !== undefined) {
        move(victim, { type: "evict" });
        await abortable(bounded(shutdown(victim, "process-budget"), 10000), signal);
      } else if (budget.retiring) {
        const controller = new AbortController();

        try {
          await bounded(budget.wait(AbortSignal.any([signal, controller.signal])), deadline);
        } finally {
          controller.abort();
        }
      } else return budget.reserve(entry);
    }
  }

  function reserve(entry: Entry, request: LaunchAdmissionRequest) {
    const controller = new AbortController();
    const signal = AbortSignal.any([request.signal, controller.signal]);
    waiting.set(entry, controller);
    touch(entry);
    let reservation: ProcessReservation | undefined;

    const task = tail
      .then(() => admit(entry, request, signal))
      .then((value) => {
        reservation = value;

        if (signal.aborted || !request.isCurrent()) {
          value.releaseUnstarted();
          throw failure("stale-generation", "Language process demand changed");
        }

        return value;
      })
      .finally(() => {
        if (waiting.get(entry) === controller) waiting.delete(entry);
      });

    tail = task.catch(() => undefined);

    return abortable(task, signal).catch((cause: unknown) => {
      reservation?.releaseUnstarted();

      if (signal.aborted) throw failure("stale-generation", "Language process demand changed");

      if (Schema.is(LanguageError)(cause) && cause.reason === "timeout")
        throw failure(
          "process-retiring",
          "Language server cleanup has not finished. Try again in a moment."
        );
      throw cause;
    });
  }

  return { budget, reserve, touch, cancel, retire };
}

import { InlineError } from "@polaris/protocol";
import { Effect } from "effect";
import { which } from "../service/userPath.ts";
