}

const ESTIMATE = 30;

/** The row the Intent column shows, which keeps a translucent fill. */
const focusKey = ({ focus }: LeadUi) => {
  if (focus === null) return null;

  return focus.kind === "task" ? `task:${focus.taskId}` : `handover:${focus.revision}`;
};

const MESSAGE_LEAD: RowKeys = [["m", "message lead"]];

const REVIEW_KEYS: RowKeys = [
  ["a", "accept"],
  ["s", "send back"],
];

const lastHint = (row: RailRow | undefined): RowKeys =>
  row?.kind === "task" && row.projection.state === "review" ? REVIEW_KEYS : MESSAGE_LEAD;

/** Scrolls a row into view once the virtualizer knows where it is. */
const indexOf = (rows: ReadonlyArray<RailRow>, key: string) => rows.findIndex((r) => r.key === key);

const useTabActions = (
  props: ConstellationTabProps,
  setDraft: (d: MessageDraft | null) => void
) => {
  const { hostKey, record } = props;
  const c = record.constellation;
  const key = leadKey(hostKey, c.leadSessionId);
  const shell = useShellActions();
  const hosts = useApp((s) => s.hosts);
  const commands = useCommands();
  const leadBranch = useLeadBranch(hostKey, c.leadSessionId);

  const focus = (row: TaskRow) =>
    patchLeadUi(key, () => ({ focus: { kind: "task", taskId: row.task.id }, selected: row.key }));

  const menu: MenuActions = {
    onFocus: focus,
    onReview: (row, mode) => {
      if (row.attempt === null) return;
      patchLeadUi(key, () => ({
        focus: { kind: "task", taskId: row.task.id },
        selected: row.key,
        review: { attemptId: row.attempt?.id ?? "", mode },
      }));
    },
    onOpenInReview: (row) => {
      const worker = row.attempt === null ? null : hostKeyOf(hosts, row.attempt.hostId);

      if (worker !== null && row.attempt !== null)
        openSessionReview(shell, worker, row.attempt.sessionId);
    },
    onApprove: (row) => {
      if (row.attempt === null) return;
      void approveClaim(hostKey, record, row.attempt, placeOf(row.attempt, leadBranch));
    },
    onMessageLead: (row, authority) =>
      setDraft({
        title: `Message the lead about ${row.task.id}`,
        authority,
        text: `About ${row.task.id} (${row.task.title}): `,
      }),
  };

  const answer = (proposalId: string, accept: boolean) =>
    void constellationCommands.answer(
      hostKey,
      {
        constellationId: c.id,
        action: AnswerAction.cases.Proposal.make({ proposalId, accept, reason: "" }),
      },
      accept ? "Couldn't accept the proposal" : "Couldn't decline the proposal"
    );

  const retry = (row: TaskRow) => {
    if (row.setup === null) return;
    void constellationCommands.dispatch(
      hostKey,
      retrySetup(row.setup, c.hostId),
      `Couldn't retry ${row.task.id}`
    );
  };

  const toggle = (group: string, open: boolean) =>
    patchLeadUi(key, (ui) => ({ folds: new Map(ui.folds).set(group, open) }));

  const messageLead = () => {
    patchLeadUi(key, () => ({ focus: null }));
    commands.run("session.focusComposer");
  };

  return { key, menu, answer, retry, toggle, focus, messageLead };
};

type Actions = ReturnType<typeof useTabActions>;

const runKey = (
  action: KeyAction,
  ctx: {
    readonly actions: Actions;
    readonly ui: LeadUi;
    readonly items: ReadonlyArray<AttentionItem>;
    readonly jump: (taskId: string) => void;
    readonly filter: () => void;
  }
) => {
  const { actions } = ctx;

  switch (action.kind) {
    case "select":
      return patchLeadUi(actions.key, () => ({ selected: action.key }));
    case "focus":
      return actions.focus(action.row);
    case "toggle":
      return actions.toggle(action.group, action.open);
    case "handover":
      return patchLeadUi(actions.key, () => ({
        focus: { kind: "handover", revision: action.revision },
      }));
    case "review":
      return actions.menu.onReview(action.row, action.mode);
    case "next-needs-you": {
      const selected = ctx.ui.selected?.replace(/^task:/, "") ?? null;
      const next = nextNeedingYou(ctx.items, selected);

      return next === null ? undefined : ctx.jump(next);
    }

    case "message-lead":
      return actions.messageLead();
    case "filter":
      return ctx.filter();
    case "back":
      return patchLeadUi(actions.key, () => ({ focus: null, review: null }));
  }
};

const Empty = ({ onAdd }: { readonly onAdd: () => void }) => (
  <div className="grid flex-1 place-items-center" data-testid="constellation-empty">
    <EmptyState
      icon={<ConstellationMark size={24} />}
      title="No tasks yet"
      fact="The lead is drafting a plan. Tasks appear here as it adds them."
      action={
        <Button variant="secondary" onClick={onAdd}>
          Add a task
        </Button>
      }
    />
  </div>
);

export const ConstellationTab = (props: ConstellationTabProps) => {
  const { hostKey, record } = props;
  const c = record.constellation;
  const draftKey = leadKey(hostKey, c.leadSessionId);
  const setDraft = (draft: MessageDraft | null) => patchLeadUi(draftKey, () => ({ draft }));
  const actions = useTabActions(props, setDraft);
  const ui = useLeadUi(actions.key);
  const facts = useFacts(record);
  const scrollRef = useRef<HTMLDivElement>(null);
  const filterRef = useRef<HTMLInputElement>(null);

  const rail = useMemo(
    () => buildRail(record, facts, { folds: ui.folds, filter: ui.filter, query: ui.query }),
    [record, facts, ui.folds, ui.filter, ui.query]
  );

  const items = useMemo(() => attentionItems(rail.tasks, facts), [rail, facts]);
  const strip = useMemo(() => segments(rail.tasks), [rail]);
  const { rows } = rail;
  const step = railStep(rail.depth);

  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => ESTIMATE,
    getItemKey: (index) => rows[index]?.key ?? index,
    overscan: 8,
    paddingStart: 2,
    paddingEnd: 16,
  });

  const jump = (taskId: string) => {
    const rowKey = `task:${taskId}`;

    for (const fold of foldsAbove(record, taskId)) actions.toggle(fold, true);
    patchLeadUi(actions.key, () => ({ selected: rowKey }));
    requestAnimationFrame(() => {
      const at = indexOf(rail.rows, rowKey);

      if (at >= 0) virtualizer.scrollToIndex(at, { align: "auto" });
    });
  };

  const onJump = (item: AttentionItem) => (item.taskId === null ? undefined : jump(item.taskId));

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.target instanceof HTMLInputElement || event.metaKey || event.ctrlKey || event.altKey)
      return;
    const action = railKey(event.key, rows, ui.selected);

    if (action === null || (action.kind === "next-needs-you" && items.length === 0)) return;
    event.preventDefault();
    runKey(action, { actions, ui, items, jump, filter: () => filterRef.current?.focus() });

    if (action.kind === "select") {
      const at = indexOf(rows, action.key);

      if (at >= 0) virtualizer.scrollToIndex(at, { align: "auto" });
    }
  };

  const handlers: RowHandlers = {
    onToggleGroup: (group) => {
      const header = rows.find(
        (r) =>
          (r.kind === "group" && r.group === group) || (r.kind === "parent" && r.fold === group)
      );

      actions.toggle(
        group,
        header?.kind === "group" || header?.kind === "parent" ? !header.open : true
      );
    },
    onFocus: actions.focus,
    onReview: actions.menu.onReview,
    onApprove: actions.menu.onApprove,
    onRetrySetup: actions.retry,
    onProposal: actions.answer,
    onHandover: (revision) =>
      patchLeadUi(actions.key, () => ({ focus: { kind: "handover", revision } })),
    menu: (row) => (
      <RowMenu
        row={row}
        on={actions.menu}
        open={ui.menu === row.key}
        onOpenChange={(open) => patchLeadUi(actions.key, () => ({ menu: open ? row.key : null }))}
      />
    ),
  };

  const focusedKey = focusKey(ui);

  return (
    <section
      aria-label={`Constellation ${c.name}`}
      className="@container flex h-full min-h-0 min-w-0 flex-1 flex-col"
      data-testid="constellation-tab"
    >
      <Header
        record={record}
        segments={strip}
        top={items[0] ?? null}
        onJump={onJump}
        hostKey={hostKey}
        statsOpen={ui.stats}
        onStatsOpen={(stats) => patchLeadUi(actions.key, () => ({ stats }))}
        ledBy="led by this session"
      />
      {c.state === "completed" || c.state === "archived" ? (
        <CompletionCard hostKey={hostKey} record={record} />
      ) : null}
      {rail.large ? (
        <Filters
          rail={rail}
          filter={ui.filter}
          query={ui.query}
          onFilter={(filter) => patchLeadUi(actions.key, () => ({ filter }))}
          onQuery={(query) => patchLeadUi(actions.key, () => ({ query }))}
          inputRef={filterRef}
        />
      ) : null}
      {c.tasks.length === 0 && record.proposals.length === 0 ? (
        <Empty
          onAdd={() =>
            setDraft({ title: "Add a task", authority: "conversation", text: "Add a task: " })
          }
        />
      ) : (
        <div
          ref={scrollRef}
          role="list"
          aria-label="Tasks"
          tabIndex={0}
          onKeyDown={onKeyDown}
          className="min-h-0 flex-1 overflow-x-hidden overflow-y-auto overscroll-contain px-1"
          style={laneStyle(laneWidth(rail.ids, LANE_MAX.tab))}
          data-testid="constellation-rail"
        >
          <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
            {virtualizer.getVirtualItems().map((item) => {
              const row = rows[item.index];

              if (row === undefined) return null;
              const selected = row.key === ui.selected || row.key === focusedKey;

              const body = (
                <div
                  role="listitem"
                  aria-current={selected ? "true" : undefined}
                  data-selected={selected ? "" : undefined}
                  className={cn(
                    "group/row rounded-row",
                    selected && "bg-fill-selected/60",
                    row.kind === "task" && "hover:bg-fill-hover/60"
                  )}
                  onClick={(e) => {
                    if (e.target instanceof Element && e.target.closest("button") !== null) return;
                    patchLeadUi(actions.key, () => ({ selected: row.key }));

                    if (row.kind === "task") actions.focus(row);
                  }}
                >
                  <RowView row={row} on={handlers} large={rail.large} step={step} />
                </div>
              );

              return (
                <div
                  key={item.key}
                  ref={virtualizer.measureElement}
                  data-index={item.index}
                  className="absolute top-0 left-0 w-full"
                  style={{ transform: `translateY(${item.start}px)` }}
                >
                  {row.kind === "task" && row.attempt !== null ? (
                    <ContextMenu>
                      <ContextMenuTrigger asChild>{body}</ContextMenuTrigger>
                      <RowContextMenu row={row} on={actions.menu} />
                    </ContextMenu>
                  ) : (
                    body
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
      <KeyHints
        last={
          ui.focus?.kind === "task"
            ? MESSAGE_LEAD
            : lastHint(rows.find((r) => r.key === ui.selected))
        }
      />
      <MessageLeadDialog
        hostKey={hostKey}
        constellationId={c.id}
        draft={ui.draft}
        onClose={() => setDraft(null)}
      />
    </section>
  );
};

/**
 * The Output lane right of Intent (DESIGN.md, Output): the 240px rail while
 * collapsed, else the panel, resizable from its left edge. Opening slides
 * the panel in from the rail on `transform` only; Reduce Motion makes it instant.
 */
import type { SessionId } from "@polaris/protocol";
import { cn } from "@polaris/ui";
import { type KeyboardEvent, type PointerEvent, type RefObject, useRef } from "react";
import { slots } from "../app/slots.tsx";
import {
  clampWidth,
  defaultWidth,
  KEY_STEP,
  RAIL_WIDTH,
  setOutputWidth,
  useOutputShown,
  useOutputWidth,
  widthCss,
} from "../features/session/index.ts";
import { TerminalDock } from "../features/terminal/index.ts";

export interface OutputLaneProps {
  readonly hostKey: string;
  readonly workspaceId: string;
  readonly sessionId: SessionId;
  /** Intent and Output together: the panel's width is measured against it. */
  readonly lane: RefObject<HTMLDivElement | null>;
}

/** True for the render that opens the panel in the same session, until it closes again. */
const useSlideIn = (key: string, shown: boolean) => {
  const last = useRef({ key, shown });
  const sliding = useRef<string | null>(null);

  if (shown && !last.current.shown && last.current.key === key) sliding.current = key;

  if (!shown) sliding.current = null;
  last.current = { key, shown };

  return shown && sliding.current === key;
};

/** The edge is on the panel's left: ← widens it, → narrows it. */
const STEPS = new Map([
  ["ArrowLeft", KEY_STEP],
  ["ArrowRight", -KEY_STEP],
]);

const ResizeEdge = ({ lane }: { readonly lane: RefObject<HTMLDivElement | null> }) => {
  const width = useOutputWidth();

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    const box = lane.current?.getBoundingClientRect();

    if (box === undefined) return;
    event.currentTarget.setPointerCapture(event.pointerId);

    const move = (e: globalThis.PointerEvent) =>
      setOutputWidth(clampWidth(box.right - e.clientX, box.width));

    const up = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
    };

    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const available = lane.current?.getBoundingClientRect().width;
    const step = STEPS.get(event.key) ?? 0;

    if (available === undefined || step === 0) return;
    event.preventDefault();
    setOutputWidth(clampWidth((width ?? defaultWidth(available)) + step, available));
  };

  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-label="Resize output"
      aria-valuenow={width ?? undefined}
      tabIndex={0}
      onPointerDown={onPointerDown}
      onKeyDown={onKeyDown}
      onDoubleClick={() => setOutputWidth(null)}
      className="absolute inset-y-0 -left-1 z-10 w-2 cursor-col-resize focus-visible:outline-none"
      data-testid="output-resize"
    />
  );
};

export const OutputLane = ({ hostKey, workspaceId, sessionId, lane }: OutputLaneProps) => {
  const shown = useOutputShown({ hostKey, workspaceId }, sessionId);
  const width = useOutputWidth();
  const slide = useSlideIn(`${hostKey}\u0000${sessionId}`, shown);

  if (!shown) {
    return (
      <div className="bg-surface-sunken flex shrink-0 flex-col" style={{ width: RAIL_WIDTH }}>
        <TerminalDock hostKey={hostKey} workspaceId={workspaceId}>
          <slots.OutputRail hostKey={hostKey} sessionId={sessionId} />
        </TerminalDock>
      </div>
    );
  }

  return (
    <div className="relative flex shrink-0 flex-col" style={{ width: widthCss(width) }}>
      <ResizeEdge lane={lane} />
      <div
        className={cn("flex min-h-0 flex-1 flex-col", slide && "output-slide-in")}
        data-testid="output-panel"
      >
        <TerminalDock hostKey={hostKey} workspaceId={workspaceId} tuckable>
          <slots.SessionOutput hostKey={hostKey} sessionId={sessionId} />
        </TerminalDock>
      </div>
    </div>
  );
};

/**
 * `GitHub`: the Desktop App's GitHub client (ENG-185, ENG-219). Accounts through
 * the device flow, tokens in `SecureStorage`, repositories routed to accounts,
 * the pull request list, reviews, Viewed marks and Review Checkout states. The
 * renderer reaches it over IPC (`github.*`); see README.md.
 */
import { Context, Effect, Layer, Stream, SubscriptionRef } from "effect";
import {
  type CheckoutStateView,
  type CheckoutWatch,
  type GitHubAccountsView,
  type PullListView,
  parseGitHubRemote,
  type RepoRef,
  repoKey,
  type WorkspaceRef,
  workspaceKey,
  type PullRef,
  type PullDetailView,
} from "../../shared/github.ts";
import { openAccounts } from "./accounts.ts";
import { type BudgetPolicy, DEFAULT_POLICY, newBudget } from "./budget.ts";
import { newCheckouts } from "./checkouts.ts";
import { newClient } from "./client.ts";
import { newCompare } from "./compare.ts";
import type { EndpointConfig } from "./config.ts";
import { newCreate } from "./create.ts";
import { newCredentials } from "./credentials.ts";
import { DEFAULT_INTERVALS, type Intervals, newPoller } from "./poller.ts";
import { EMPTY_LIST, newPulls, type Watched } from "./pulls.ts";
import { join } from "node:path";
import { newOverviewActions } from "./overviewActions.ts";
import {
  type AutoMergeInput,
  type MergeInput,
  newPullActions,
  type ReviewerChange,
} from "./pullActions.ts";
import { MUTATION_GAP_MS, newReviews } from "./reviews.ts";
import { newRouting } from "./routing.ts";
import { SecureStorage } from "../secure/index.ts";
import { openStore } from "./store.ts";
import { type Fetch, newTransport } from "./transport.ts";

export type { NewPull } from "./create.ts";

export type { AutoMergeInput, BranchRestore, MergeInput, ReviewerChange } from "./pullActions.ts";

export type {
  CommentEdit,
  Discard,
  NewThread,
  Reply,
  Submission,
  ThreadResolution,
  ViewedMark,
} from "./reviews.ts";

export interface GitHubInput {
  /** `<userData>/github`. */
  readonly dir: string;
  readonly fetch: Fetch;
  readonly endpoints: EndpointConfig;
  readonly policy?: BudgetPolicy;
  readonly intervals?: Intervals;
  /** The pause between one account's mutations (GitHub asks for a second). */
  readonly mutationGapMs?: number;
  /** Wall-clock ms for rate-limit windows; tests share it with the fake. */
  readonly now?: () => number;
}

/** A Workspace and its git remotes (`origin`, `upstream`…), as the PR list watches them. */
export interface WorkspaceRemotes {
  readonly workspace: WorkspaceRef;
  readonly remotes: ReadonlyArray<string>;
}

/** Groups Workspaces by the repository (on github.com or an Enterprise `hosts`) their remotes point at. */
export const watchedFrom = (
  entries: ReadonlyArray<WorkspaceRemotes>,
  hosts: ReadonlyArray<string> = []
): ReadonlyArray<Watched> => {
  const byRepo = new Map<string, { repo: RepoRef; workspaces: Array<WorkspaceRef> }>();

  for (const { workspace, remotes } of entries) {
    for (const repo of remotes.map((remote) => parseGitHubRemote(remote, hosts))) {
      if (repo === null) continue;

      const entry = byRepo.get(repoKey(repo)) ?? { repo, workspaces: [] };

      if (!entry.workspaces.some((w) => workspaceKey(w) === workspaceKey(workspace))) {
        entry.workspaces.push(workspace);
      }

      byRepo.set(repoKey(repo), entry);
    }
  }

  return [...byRepo.values()];
};

/** Who a pull request watch belongs to. */
type WatchGroup = "checkouts" | "sessions";

const make = Effect.fn("GitHub.make")(function* (input: GitHubInput) {
  const scope = yield* Effect.scope;
  const now = input.now ?? Date.now;
  const store = openStore({ dir: input.dir, crypto: input.crypto });
  const budget = newBudget(now, input.policy ?? DEFAULT_POLICY);
  const transport = newTransport({ fetch: input.fetch, budget, now });
  const accounts = yield* openAccounts({ store, transport, endpoints: input.endpoints, scope });

  const credentials = newCredentials({
    store,
    transport,
    signedOut: accounts.signedOut,
    accessOf: accounts.accessOf,
  });

  const client = newClient(transport, credentials, accounts);
  const routing = newRouting({ client, accounts });
  const reviews = newReviews({ client, routing, gapMs: input.mutationGapMs ?? MUTATION_GAP_MS });
  const overview = newOverviewActions(reviews, join(input.dir, "published-descriptions.json"));
  const pullActions = newPullActions({ client, reviews });
  const list = yield* SubscriptionRef.make<PullListView>(EMPTY_LIST);
  const detailViews = yield* SubscriptionRef.make<ReadonlyArray<PullDetailView>>([]);

  const publishDetails = Effect.flatMap(overview.cached(), (views) =>
    SubscriptionRef.set(detailViews, views)
  );

  const checkoutStates = yield* SubscriptionRef.make<ReadonlyArray<CheckoutStateView>>([]);

  const poller = yield* newPoller({
    accounts,
    client,
    pulls: newPulls({ client, routing }),
    checkouts: newCheckouts({ client, routing }),
    list,
    checkoutStates,
    intervals: input.intervals ?? DEFAULT_INTERVALS,
    refreshDetails: Effect.andThen(reviews.refreshDetails, publishDetails).pipe(Effect.ignore),
  });

  let remotes: ReadonlyArray<WorkspaceRemotes> = [];

  const rewatch = Effect.flatMap(accounts.hostNames, (hosts) =>
    poller.watch(watchedFrom(remotes, hosts))
  );

  // Signing in, out, reordering or adding a host changes which account sees what.
  const signature = (view: GitHubAccountsView) =>
    JSON.stringify([
      (view.hosts ?? []).map((h) => [h.host, h.clientId]),
      view.accounts.map((a) => [a.id, a.state]),
      view.owners,
      view.workspaces,
    ]);

  yield* SubscriptionRef.changes(accounts.view).pipe(
    Stream.map(signature),
    Stream.changes,
    Stream.drop(1),
    Stream.runForEach(() => Effect.andThen(routing.reset, rewatch)),
    Effect.forkIn(scope)
  );
  yield* Effect.forkIn(poller.loop, scope);
  const watchGroups = new Map<WatchGroup, ReadonlyArray<CheckoutWatch>>();

  return {
    accounts: accounts.view,
    pulls: list,
    checkouts: checkoutStates,
    /** Signs in to github.com, or to an Enterprise host added with `addHost`. */
    startSignIn: (host?: string) => accounts.startSignIn(credentials, host),
    addHost: accounts.addHost,
    removeHost: (host: string) => accounts.removeHost(host, credentials),
    cancelSignIn: accounts.cancelSignIn,
    removeAccount: (accountId: number) => accounts.remove(accountId, credentials),
    reorderAccounts: accounts.reorder,
    setOwner: accounts.setOwner,
    setWorkspace: (workspace: WorkspaceRef, accountId: number | null) =>
      accounts.setWorkspace(workspaceKey(workspace), accountId),
    watch: (entries: ReadonlyArray<WorkspaceRemotes>) =>
      Effect.andThen(
        Effect.sync(() => {
          remotes = entries;
        }),
        rewatch
      ),
    /** Each caller (Review Checkouts, accepted sessions' pull requests) keeps its own group. */
    watchCheckouts: (watches: ReadonlyArray<CheckoutWatch>, group: WatchGroup = "checkouts") =>
      Effect.suspend(() => {
        watchGroups.set(group, watches);

        return poller.watchCheckouts([...watchGroups.values()].flat());
      }),
    refresh: poller.poke(true),
    /** The user asked to check a blocked repository again (after requesting access). */
    recheck: (repo: RepoRef) => Effect.andThen(routing.invalidate(repo), poller.poke(true)),
    setFocused: poller.setFocused,
    /** GitHub's stack when it has one, else the one the list inferred (no extra request). */
    detail: (pull: PullRef, fresh = false) =>
      Effect.gen(function* () {
        const view = yield* overview.detail(pull, fresh);
        yield* publishDetails;

        if ((view.stack ?? null) !== null) return view;

        const current = yield* SubscriptionRef.get(list);

        const row = [
          ...current.requested,
          ...current.mine,
          ...current.other,
          ...(current.reviewed ?? []),
        ].find((r) => r.id === view.id);

        return { ...view, stack: row?.stack ?? null };
      }),
    details: detailViews,
    comment: (input: Parameters<typeof overview.comment>[0]) =>
      overview.comment(input).pipe(Effect.tap(() => poller.poke(true))),
    botCommand: (input: Parameters<typeof overview.botCommand>[0]) =>
      overview.botCommand(input).pipe(Effect.tap(() => poller.poke(true))),
    publishDescription: (input: Parameters<typeof overview.publishDescription>[0]) =>
      overview.publishDescription(input).pipe(Effect.tap(() => poller.poke(true))),
    addThread: reviews.addThread,
    reply: reviews.reply,
    resolveThread: reviews.resolve,
    editComment: reviews.editComment,
    submitReview: (input: Parameters<typeof reviews.submit>[0]) =>
      reviews.submit(input).pipe(Effect.tap(() => poller.poke(true))),
    discardReview: reviews.discard,
    setViewed: reviews.setViewed,
    createPull: newCreate(client, routing),
    compare: newCompare(client, routing),
    pullActions: pullActions.actions,
    searchReviewers: pullActions.search,
    requestReviewers: (change: ReviewerChange) =>
      pullActions.request(change).pipe(Effect.tap(() => poller.poke(true))),
    removeReviewers: (change: ReviewerChange) =>
      pullActions.unrequest(change).pipe(Effect.tap(() => poller.poke(true))),
    merge: (input: MergeInput) =>
      pullActions.merge(input).pipe(Effect.tap(() => poller.poke(true))),
    autoMerge: (input: AutoMergeInput) =>
      pullActions.autoMerge(input).pipe(Effect.tap(() => poller.poke(true))),
    restoreBranch: pullActions.restoreBranch,
  };
});

