import { hostname } from "node:os";
import { CapabilityProbe } from "@polaris/client/prediction/probe";
import type { PredictionTarget } from "@polaris/client/prediction";
import { PredictionError, PredictionRequest, PredictionStreamItem } from "@polaris/protocol";
import { Effect, ManagedRuntime, Predicate, Queue, Stream, type Layer } from "effect";
import { HostDirectory, LOCAL_HOST_KEY, type ClientRuntime } from "../hosts.ts";
import type { Settings } from "../settings.ts";
import {
  PredictionFeedItem,
  type PredictionCompletionInput,
  type PredictionInspection,
} from "../../shared/predictionContract.ts";
import type { IpcError } from "../../shared/api.ts";
import type { MainPredictionPlacement } from "./placement.ts";
import type { PredictionSettings } from "./preferences.ts";
import { LocalPredictor } from "./localPredictor.ts";

export interface PredictionBridgePorts {
  readonly localLayer?: Layer.Layer<LocalPredictor>;
  readonly probe?: Pick<CapabilityProbe, "get">;
  readonly runtime: ClientRuntime;
  readonly placement: MainPredictionPlacement;
  readonly preferences: PredictionSettings;
  readonly read: () => Settings;
  readonly commit: (settings: Settings) => void;
}

/** One LocalPredictor Layer per main process, shared by all completion subscriptions. */
export const createPredictionBridge = (ports: PredictionBridgePorts) => {
  const local = ManagedRuntime.make(ports.localLayer ?? LocalPredictor.layer);
  const probe = ports.probe ?? new CapabilityProbe();

  const enabled = () => ({
    enabled: ports.read().predictionEnabled ?? false,
    configured: ports.read().predictionConfigured ?? false,
  });

  const setEnabled = (value: boolean) => {
    ports.placement.invalidateAll();
    ports.commit({ ...ports.read(), predictionEnabled: value, predictionConfigured: true });

    return enabled();
  };

  const hostSession = Effect.fn("prediction.hostSession")(function* (hostKey: string) {
    const directory = yield* HostDirectory;
    const connection = yield* directory.connection(hostKey);

    return yield* connection.session;
  });

  const labels = (hostKey: string) =>
    ports.runtime.runPromise(
      Effect.gen(function* () {
        const directory = yield* HostDirectory;
        // The local Host's own name ("This Mac"), never the network hostname.
        const clientLabel = directory.entry(LOCAL_HOST_KEY)?.label ?? hostname();

        return {
          clientLabel: hostname(),
          hostLabel:
            directory.entry(hostKey)?.label ?? (hostKey === LOCAL_HOST_KEY ? clientLabel : hostKey),
        };
      })
    );

  const inspect = async (hostKey: string): Promise<PredictionInspection> => {
    const [names, client, host] = await Promise.all([
      labels(hostKey),
      probe.get(
        ports.preferences.getClientEndpoints().map((endpoint) => ({ ...endpoint, models: [] }))
      ),
      ports.runtime
        .runPromise(
          Effect.flatMap(hostSession(hostKey), (session) =>
            session.capabilities.includes("prediction.capability")
              ? session.client["prediction.capability"]({
                  endpoints: ports.preferences
                    .get(hostKey)
                    .hostEndpoints.map((endpoint) => endpoint.url),
                })
              : Effect.succeed(null)
          )
        )
        .catch(() => null),
    ]);

    const found = [...client.endpoints, ...(host?.endpoints ?? [])].some(
      (endpoint) => endpoint.models.length > 0
    );

    const offer = found && !enabled().configured && !ports.read().predictionDiscoveryShown;

    return { ...names, client, host, offer };
  };

  const complete = (input: PredictionCompletionInput) =>
    Stream.callback<PredictionFeedItem, IpcError>(
      Effect.fn("prediction.bridge.complete")(function* (queue) {
        const started = performance.now();
        const timings: Record<string, number> = {};

        if (input.dispatchedAt !== undefined)
          timings.ipc = Math.max(0, performance.timeOrigin + started - input.dispatchedAt);

        const mark = (stage: string) => {
          timings[stage] = performance.now() - started;
        };

        const controller = new AbortController();
        yield* Effect.addFinalizer(() => Effect.sync(() => controller.abort()));

        const serve = async (target: PredictionTarget, signal: AbortSignal) => {
          delete timings.firstToken;
          delete timings.prompt;
          delete timings.final;
          mark("placement");
          Queue.offerUnsafe(queue, PredictionFeedItem.cases.Reset.make({}));

          if (input.cursor > input.buffer.length)
            throw new PredictionError({
              reason: "invalid-request",
              message: "Cursor is outside the buffer",
            });

          const session = await ports.runtime.runPromise(hostSession(input.hostKey), { signal });

          const context = session.capabilities.includes("prediction.context")
            ? await ports.runtime.runPromise(session.client["prediction.context"](input), {
                signal,
              })
            : [];

          mark("context");

          const request = PredictionRequest.make({
            context,
            path: input.path,
            prefix: input.buffer.slice(0, input.cursor).split("\n").slice(-121).join("\n"),
            suffix: input.buffer.slice(input.cursor).split("\n").slice(0, 41).join("\n"),
            model: target.model,
            format: target.format,
            endpoint: target.endpoint,
            budgetTokens: input.budgetTokens,
            maxTokens: 128,
            maxLines: 8,
          });

          const names = await labels(input.hostKey);
          const predictorStart = performance.now() - started;
          let final: typeof PredictionStreamItem.cases.Final.Type | null = null;

          const receive = (item: PredictionStreamItem) => {
            if (Predicate.isTagged(item, "Final")) {
              final = item;
              mark("final");
            } else {
              if (timings.firstToken === undefined) mark("firstToken");
              Queue.offerUnsafe(queue, PredictionFeedItem.cases.Delta.make({ text: item.text }));
            }
          };

          if (target.side === "client") {
            await local.runPromise(
              LocalPredictor.use((predictor) =>
                predictor
                  .complete(request, {
                    signal,
                    onTiming: (stage, elapsed) => {
                      timings[stage] = predictorStart + elapsed;
                    },
                  })
                  .pipe(Stream.runForEach((item) => Effect.sync(() => receive(item))))
              ),
              { signal }
            );
          } else {
            if (!session.capabilities.includes("prediction.complete"))
              throw new PredictionError({
                reason: "unavailable",
                message: "Host cannot serve completion",
              });
            await ports.runtime.runPromise(
              session.client["prediction.complete"](request).pipe(
                Stream.runForEach((item) => Effect.sync(() => receive(item)))
              ),
              { signal }
            );
          }
          // SAFETY: receive runs synchronously for every consumed stream item before runPromise resolves.

          const result = final as typeof PredictionStreamItem.cases.Final.Type | null;

          if (result === null)
            throw new PredictionError({
              reason: "invalid-response",
              message: "Prediction ended without a final result",
            });

          return PredictionFeedItem.cases.Final.make({
            text: result.text,
            timings: { ...timings },
            elapsedMs: result.elapsedMs,
            model: target.model,
            machine: target.side === "client" ? names.clientLabel : names.hostLabel,
          });
        };

        const run = Effect.tryPromise({
          try: async () => {
            if (!enabled().enabled) throw new Error("Tab completion is off");

            const result = await ports.placement.run(
              input.hostKey,
              input.workspaceId,
              serve,
              controller.signal
            );

            Queue.offerUnsafe(queue, result);
            Queue.endUnsafe(queue);
          },
          catch: (error): IpcError => ({ code: "PredictionUnavailable", message: String(error) }),
        });

        yield* Effect.forkScoped(run.pipe(Effect.catch((error) => Queue.fail(queue, error))));
      })
    );

  return {
    enabled,
    setEnabled,
    inspect,
    complete,
    discoveryShown: () => ports.commit({ ...ports.read(), predictionDiscoveryShown: true }),
    release: (hostKey: string, workspaceId: string) =>
      ports.placement.release(hostKey, workspaceId),
    dispose: () => {
      ports.placement.invalidateAll();

      return local.dispose();
    },
  };
};

export type PredictionBridge = ReturnType<typeof createPredictionBridge>;

/**
 * What is selected, resolved against the data: the navigation state records
 * the user's choices, which may point at a Workspace or session that has since
 * gone; this picks the nearest thing that exists. Pure, so it is unit-tested.
 */
import type { SessionId, WorkspaceId } from "@polaris/protocol";
import type { Route } from "../../shared/api.ts";
import type { HostModel, SessionEntry } from "../store/hostModel.ts";
import {
  activeSessions,
  type BarHost,
  barWorkspaces,
  isRegistered,
  LOCAL_HOST,
  needsYou,
  type TopBarMode,
} from "./topBar.ts";

export type SidebarView = "sessions" | "needs-you";

export type Pane = "session" | "new-session";

/** The Settings pages (DESIGN.md, Settings); features/machines fills "hosts". */
export type SettingsSection =
  | "appearance"
  | "sessions"
  | "editor"
  | "harnesses"
  | "constellations"
  | "usage"
  | "hosts"
  | "attachments"
  | "reviewer"
  | "github"
  | "about";

export const SETTINGS_SECTIONS: ReadonlyArray<SettingsSection> = [
  "appearance",
  "sessions",
  "editor",
  "harnesses",
  "constellations",
  "usage",
  "hosts",
  "attachments",
  "reviewer",
  "github",
  "about",
];

/** The ⌘O dialog (DESIGN.md, Open folder): which Host it opens on; null for the selected one. */
export interface FolderRoute {
  readonly hostKey: string | null;
}

/** Settings, open over the three zones; null when closed. */
export interface SettingsRoute {
  readonly section: SettingsSection;
  /** Hosts and GitHub accounts: start adding one at once. */
  readonly adding: boolean;
}

export interface NavState {
  readonly mode: Route;
  readonly hostKey: string | null;
  readonly workspaceId: WorkspaceId | null;
  readonly sessionId: SessionId | null;
  readonly pane: Pane;
  readonly sidebar: SidebarView;
  readonly jumpOpen: boolean;
  /** The Command Palette (⇧⌘P). */
  readonly paletteOpen: boolean;
  /** The keyboard shortcut overlay (⌘/ or ?). */
  readonly helpOpen: boolean;
  /** The ⌘O dialog, one of the shell's overlays; null when closed. */
  readonly folder: FolderRoute | null;
  readonly settings: SettingsRoute | null;
  readonly topBar: TopBarMode;
  /** Sessions and Workspaces opened lately, newest first (`recentKey`), for the jump menu. */
  readonly recent: ReadonlyArray<string>;
  /** The session last open in each Workspace (`workspaceKey`), restored on switching back. */
  readonly lastSession: Readonly<Record<string, SessionId>>;
  /** Machine-mode Workspace groups the user folded or unfolded (`workspaceKey`). */
  readonly folded: Readonly<Record<string, boolean>>;
}

export const initialNav: NavState = {
  mode: "orchestrate",
  hostKey: null,
  workspaceId: null,
  sessionId: null,
  pane: "session",
  sidebar: "sessions",
  jumpOpen: false,
  paletteOpen: false,
  helpOpen: false,
  folder: null,
  settings: null,
  topBar: "workspaces",
  recent: [],
  lastSession: {},
  folded: {},
};

export const workspaceKey = (hostKey: string, workspaceId: string) =>
  `${hostKey}\u0000${workspaceId}`;

export type RecentKind = "session" | "workspace";

/** One recent item: its kind, Host and id. */
export const recentKey = (kind: RecentKind, hostKey: string, id: string) =>
  `${kind}\u0000${hostKey}\u0000${id}`;

export const RECENT_LIMIT = 8;

/** `key` moved to the front, without duplicates, capped. */
export const withRecent = (recent: ReadonlyArray<string>, key: string) =>
  [key, ...recent.filter((k) => k !== key)].slice(0, RECENT_LIMIT);

export interface Selection {
  readonly mode: Route;
  readonly topBar: TopBarMode;
  readonly hostKey: string | null;
  readonly workspaceId: WorkspaceId | null;
  readonly sessionId: SessionId | null;
  readonly pane: Pane;
  readonly sidebar: SidebarView;
  readonly settings: SettingsRoute | null;
}

/** Sidebar order: Needs You first (rule/needs-you-is-loudest), then newest first; stable while working. */
export const sessionOrder = (a: SessionEntry, b: SessionEntry) =>
  Number(needsYou(b)) - Number(needsYou(a)) ||
  b.session.createdAt.localeCompare(a.session.createdAt);

export interface ResolveInput {
  readonly nav: NavState;
  readonly bar: ReadonlyArray<BarHost>;
  readonly models: Readonly<Record<string, HostModel>>;
}

const pickHost = ({ nav, bar }: ResolveInput): string | null => {
  const known = bar.find((h) => h.host.key === nav.hostKey);

  if (known !== undefined) return known.host.key;

  // No choice yet: a Host with Workspaces; else this Mac (it runs sessions in its home
  // directory), else any connected Host; bar order puts this Mac last, so ask for it.
  const connected = (h: BarHost) => h.host.status.state === "connected";

  const pick =
    bar.find((h) => h.workspaces.length > 0) ??
    bar.find((h) => h.host.key === LOCAL_HOST && connected(h)) ??
    bar.find(connected) ??
    bar.find((h) => h.host.key === LOCAL_HOST) ??
    bar[0];

  return pick?.host.key ?? null;
};

const pickWorkspace = (input: ResolveInput, hostKey: string | null): WorkspaceId | null => {
  const { nav, bar } = input;
  const host = bar.find((h) => h.host.key === hostKey);
  const shown = (host?.workspaces ?? []).filter((w) => !w.hidden);

  // A hidden Workspace stays open once chosen (a jump, a session in it); it is never picked.
  if (hostKey === nav.hostKey && isRegistered(models, hostKey, nav.workspaceId))
    return nav.workspaceId;

  return shown[0]?.workspace.id ?? null;
};

const pickSession = (
  input: ResolveInput,
  hostKey: string,
  workspaceId: WorkspaceId | null
): SessionId | null => {
  const { nav, models } = input;
  const model = models[hostKey];

  if (model === undefined) return null;

  const inScope = (id: SessionId | null | undefined) => {
    const entry = id === null || id === undefined ? undefined : model.sessions.get(id);

    return entry !== undefined &&
      entry.session.state !== "archived" &&
      (workspaceId === null || entry.session.workspaceId === workspaceId)
      ? entry.session.id
      : null;
  };

  const chosen = inScope(nav.sessionId);

  if (chosen !== null || workspaceId === null) return chosen;

  const remembered = inScope(nav.lastSession[workspaceKey(hostKey, workspaceId)]);

  if (remembered !== null) return remembered;

  return [...activeSessions(model, workspaceId)].sort(sessionOrder)[0]?.session.id ?? null;
};

/** A chosen session decides its Workspace, even one selected before its SessionCreated arrived. */
const followSession = ({ nav, models }: ResolveInput): NavState => {
  const entry =
    nav.hostKey === null || nav.sessionId === null
      ? undefined
      : models[nav.hostKey]?.sessions.get(nav.sessionId);

  return entry === undefined ? nav : { ...nav, workspaceId: entry.session.workspaceId };
};

export const resolveSelection = (raw: ResolveInput): Selection => {
  const input = { ...raw, nav: followSession(raw) };
  const { nav, bar } = input;

  // In the Workspace bar a stale Workspace falls back to the first chip, on any Host; a
  // Host chosen on its own (its label: add a Workspace, or what needs attention) is kept.
  const hostOnly = nav.workspaceId === null && bar.some((h) => h.host.key === nav.hostKey);

  const known =
    bar.some((h) => h.host.key === nav.hostKey) &&
    isRegistered(input.models, nav.hostKey, nav.workspaceId);

  const stale = nav.topBar === "workspaces" && !hostOnly && !known;

  const first = stale ? barWorkspaces(bar)[0] : undefined;
  const hostKey = first?.hostKey ?? pickHost(input);
  const workspaceId = first?.workspace.id ?? pickWorkspace(input, hostKey);

  const sessionId =
    hostKey === null || nav.pane === "new-session"
      ? null
      : pickSession(input, hostKey, workspaceId);

  return {
    mode: nav.mode,
    topBar: nav.topBar,
    hostKey,
    workspaceId,
    sessionId,
    pane: nav.pane,
    sidebar: nav.sidebar,
    settings: nav.settings,
  };
};

